(window.GIM_TS=window.GIM_TS||{})["Chullin.9"]={"from":216,"a":[["\u0003שבשלה בחלבה\u0004 (החלב שינק הגדי מאמו) — הריהי \u0003אסורה,\u0004 ש\u0003אפילו\u0004 ב\u0003דיעבד נמי\u0004 \u0005[שנעשה\u0006 הדבר \u0005גם כן]\u0006 \u0003לא\u0004 יאכלנה, לכך \u0003תנא נמי רישא\u0004 \u0005[שנה גם כן בהתחלה]\u0006 \u0003שבשלה\u0004 בלשון בדיעבד, ואולם מעיקר הדין, אף לכתחילה מותר לצלות את הכחל בחלבו.","למעלה הובאה שיטת רב (בלשון השניה) האוסר את הכחל שנצלה בלא קריעה, ובענין זה מוסרים: \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003ר' אלעזר\u0004 מבבל לארץ ישראל, \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 את החכם \u0003זעירי, אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר לזעירי: האם \u0003איכא תנא דאתנייה\u0004 \u0005[יש\u0006 פה \u0005שונה משניות ששנה לו]\u0006 \u0003לרב\u0004 דין זה ש\u0003כחל\u0004 שנצלה בלא קריעה הריהו אסור? \u0003אחוייה\u0004 \u0005[הראה לו]\u0006 זעירי את \u0003רב יצחק בר אבודימי,\u0004 שהוא ששנה כן לרב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יצחק בר אבודימי לר' אלעזר: \u0003אני לא שניתי לו\u0004 דין \u0003כחל כל עיקר,\u0004 כלומר, אני לא אמרתי לו שום דבר לאסור בזה. אלא \u0003רב\u0004 ששנה להם כי הכחל שנצלה בחלבו הריהו אסור, משום ש\u0003בקעה,\u0004 כלומר, מקום פרוץ (בלא גדרות), \u0003מצא\u0004 בבבל, שראה שהריהם מזלזלים באיסור בשר בחלב, \u0003ו\u0004לכך \u0003גדר בה גדר,\u0004 הוסיף סייג, להחמיר עליהם באיסור זה, שיהא הכחל אסור, וכדי שלא יבואו לעבור על איסור תורה בבשר וחלב.","שכן מסופר כי \u0003רב איקלע\u0004 \u0005[הזדמן]\u0006 \u0003ל\u0004מקום בבבל ששמו \u0003טטלפוש, שמעה לההיא איתתא דקאמרה\u0004 \u0005[שמע את אישה אחת שאומרת]\u0006 \u0003לחבירתה: ריבעא דבשרא\u0004 \u0005[רבע,\u0006 ליטרא, \u0005של בשר]\u0006 \u0003כמה חלבא בעי לבשולי\u0004 \u0005[חלב היא צריכה לבשל אותה]?\u0006 \u0003אמר\u0004 רב: מכאן אני רואה כי \u0003לא גמירי\u0004 \u0005[אין\u0006 אלה \u0005למודים]\u0006 ש\u0003בשר בחלב\u0004 הריהו \u0003אסור,\u0004 ולכך \u0003איעכב\u0004 \u0005[התעכב]\u0006 רב באותו מקום, \u0003וקאסר להו כחלי\u0004 \u0005[ואסר להם\u0006 גם \u0005כחלים],\u0006 \u0005כדי לעשות הרחקה במקום שזילזלו באיסור בשר בחלב.\u0006 \u0005קודם הובאה מסורת בעניינו של ר' אלעזר שעלה לארץ ישראל, ושאל מי הוא התנא ששנה לרב שכחל הריהו אסור. ומציינים:\u0006","\u0003רב כהנא מתני הכי\u0004 \u0005[היה שונה כך]\u0006 את הדברים, וכפי שהובא למעלה. ואולם \u0003ר' יוסי בר אבא מתני\u0004 \u0005[היה שונה]\u0006 את הדברים באופן שונה, שאמר לו רב יצחק בר אבודימי לר' אלעזר: \u0003אנא\u0004 \u0005[אני],\u0006 רק ב\u0003כחל של\u0004 בהמה \u0003מניקה\u0004 (שחלב רב כנוס בכחל שלה) \u0003שניתי לו\u0004 לרב שהריהו אסור, \u0003ומפלפולו של רב חייא\u0004 מפני שר' חייא היה חריף ומפולפל, לכך סבור היה רב יצחק בר אבודימי (שונה המשניות בבית מדרשו של ר' חייא) כי אף תלמידי ר' חייא חריפים כרבם, ולכך \u0003שנה ליה\u0004 \u0005[לו]\u0006 \u0003כחל סתם,\u0004 ובלא לפרט שמדובר דווקא בכחל של מניקה, כי סבור היה שונה המשניות שאין צורך לציין זאת. ואילו רב הבין מתוך כך שהכוונה לכל כחל שהוא, אף של הבהמה שאינה מניקה.","ועוד בדינו של הכחל מסופר כי \u0003רבין ורב יצחק בר יוסף איקלעו לבי\u0004 \u0005[הזדמנו לביתו]\u0006 של \u0003רב פפי. אייתו לקמייהו תבשילא דכחל\u0004 \u0005[הביאו לפניהם\u0006 לאכול \u0005תבשיל של כחל],\u0006 \u0003רב יצחק בר יוסף אכל\u0004 ממנו, ו\u0003רבין לא אכל. אמר אביי: רבין תכלא\u0004 \u0005[השכול],\u0006 \u0003אמאי לא אכל\u0004 \u0005[מדוע אינך אוכל]?\u0006 \u0003מכדי, דביתהו\u0004 \u0005[הרי, אשתו]\u0006 של \u0003רב פפי ברתיה\u0004 \u0005[בתו]\u0006 של \u0003ר' יצחק נפחא הואי\u0004 \u0005[הינה],\u0006 \u0003ור' יצחק נפחא, מריה דעובדא הוה\u0004 \u0005[בעל מעשים,\u0006 מדקדק במצוות, \u0005היה],\u0006 ומעתה, \u0003אי לאו דשמיע לה מבי נשא, לא הוה עבדא\u0004 \u0005[אם לא ששמעה\u0006 כן \u0005בבית אביה\u0006 שמותר הכחל באכילה, \u0005לא היתה עושה כן],\u0006 ואפשר לסמוך עליה!","למעלה נמסר על מנהגו של ר' יצחק נפחא בענין אכילת כחל, ועתה מוסרים על מנהגם של ערים שונות בבבל. שכן היהודים ש\u0003ב\u0004עיר \u0003סורא לא אכלי כחלי\u0004 \u0005[לא היו אוכלים כחל]\u0006 כלל, אף זה שנצלה ואף זה שנקרע. ואילו \u0003ב\u0004עיר \u0003פומבדיתא אכלי כחלי\u0004 \u0005[היו אוכלים כחל].\u0006 ובענין זה מסופר כי \u0003רמי בר תמרי\u0004 ש\u0003הוא\u0004 זה המכונה \u0003רמי בר דיקולי\u0004 שהיה \u0003מ\u0004העיר \u0003פומבדיתא\u0004 (שבה היה הכחל נאכל) \u0003איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לסורא\u0004 (שבה אין הכחל נאכל), \u0003במעלי יומא דכפורי\u0004 \u0005[בערב יום הכיפורים],\u0006 שבו מצווים על אכילה ושתיה, והתבשלו באותו יום מאכלי בשר מרובים, \u0003אפקינהו כולי עלמא לכחלינהו שדינהו\u0004 \u0005[הוציאו כולם את הכחלים שלהם וזרקו אותם],\u0006 שהרי אינם נאכלים במקום זה, \u0003אזל איהו, נקטינהו אכלינהו\u0004 \u0005[הלך הוא,\u0006 רמי בר תמרי, \u0005אסף אותם\u0006 את הכחלים, צלאם ו\u0005אכל אותם],\u0006 שהרי במקומו הכחל נאכל.","\u0003אייתוה לקמיה\u0004 \u0005[הביאו אותו לפני]\u0006 \u0003רב חסדא\u0004 לדין על שאכל אכילה האסורה במקום זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרמי בר תמרי: \u0003אמאי תעביד הכי\u0004 \u0005[מדוע אתה עושה כך],\u0006 שהרי במקומנו אסורה אכילת הכחל? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר תמרי: \u0003מאתרא\u0004 \u0005[ממקומו]\u0006 של \u0003רב יהודה אנא\u0004 \u0005[אני],\u0006 \u0003דאכיל\u0004 \u0005[שאוכל]\u0006 רב יהודה את הכחל, וכך הכל נוהגים במקומי, בפומבדיתא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרמי בר תמרי: \u0003ולית לך\u0004 \u0005[ואין לך,\u0006 אין אתה מקבל\u0005]\u0006 את ההלכה הקובעת כי אדם שיצא ממקום שיש לו מנהגים מסויימים למקום אחר שנוהגים בו באופן שונה, ש\u0003נותנין\u0004 (מטילים) \u0003עליו\u0004 על אותו אדם \u0003חומרי המקום שיצא משם, וחומרי המקום שהלך לשם,\u0004 והיה לך איפוא לנהוג כחומרות העיר סורא, ולא לאכול את הכחל! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר תמרי לרב חסדא בתשובה: לא נאמר כלל זה אלא לאדם הנמצא בתוך תחומה של העיר שאליה הוא הגיע, ואילו אני \u0003חוץ לתחום\u0004 העיר \u0003סורא\u0004 \u0003אכלתינהו\u0004 \u0005[אכלתי אותם],\u0006 ואין חלים עלי חומרות המקום הזה.","הוסיף ושאל אותו רב חסדא: \u0003ובמה טויתינהו\u0004 \u0005[צלית אותם,\u0006 את הכחלים\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר תמרי: \u0003בפורצני\u0004 \u0005[בחרצנים של ענבים]\u0006 מן היקבים המצויים שם. שאל אותו רב חסדא: כיצד צלית בחרצנים אלה, \u0003ו\u0004הרי היה לך לחשוש \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003מיין נסך הויא\u0004 \u0005[היו]\u0006 החרצנים הללו, שאסורים בהנאה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 רמי בר תמרי: ישנים היו החרצנים, ש\u0003לאחר שנים עשר חדש הוו\u0004 \u0005[היו],\u0006 ובטל מעליהם איסורם.","הוסיף ושאל אותו רב חסדא: ועדיין כיצד צלית בחרצנים אלה, \u0003ו\u0004הרי היה לך לחשוש \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 של \u0003גזל הוה\u0004 \u0005[היו]\u0006 החרצנים, ששייכים הם לאדם מסויים, ויש איסור גזל בלקיחתם! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר תמרי: לא היה מקום לחשש זה, שכן \u0003יאוש בעלים הוה\u0004 \u0005[היה]\u0006 בהם, \u0003דקדחו בהו חילפי\u0004 \u0005[שכבר צמחו בהם עשבים],\u0006 משמע שהרבה זמן עבר מאז, והתייאשו מהם הבעלים, שלא באו לקחתם בזמן מרובה כל כך.","\u0003חזייה דלא הוה מנח\u0004 \u0005[ראהו\u0006 רב חסדא \u0005ש\u0006רמי בר תמרי \u0005אינו מניח]\u0006 \u0003תפילין,\u0004 וכדרכם של תלמידי חכמים שתפילין בראשיהם, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא לא מנחת\u0004 \u0005[מה טעם אין אתה מניח]\u0006 \u0003תפילין? אמר ליה\u0004 \u0005[לו]\u0006 רמי בר תמרי לרב חסדא: \u0003חולי מעיין הוא\u0004 (אני), \u0003ואמר רב יהודה\u0004 כי זה שחולה ב\u0003חולי מעיין\u0004 הריהו \u0003פטור מן התפילין,\u0004 שכן תפילין דורשות גוף נקי, ואילו אדם זה שנזקק תכופות לצרכיו, הריהו צריך לחולצן פעמים רבות.","ועוד \u0003חזייה דלא הוה קא רמי חוטי\u0004 \u0005[ראהו\u0006 רב חסדא לרמי בר תמרי \u0005ש\u0006הוא \u0005לא הטיל חוטי\u0006 ציצית בבגדו\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא לית לך חוטי\u0004 \u0005[מה טעם אין לך חוטי\u0006 ציצית בבגדך\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר תמרי לרב חסדא: \u0003טלית שאולה היא\u0004 זו, \u0003ואמר רב יהודה\u0004"],["כי \u0003טלית שאולה\u0004 — \u0003כל שלשים יום\u0004 ראשונים לשאילתה הריהי \u0003פטורה מן הציצית.\u0004","\u0003אדהכי\u0004 \u0005[בתוך כך,\u0006 בעוד הם מדברים\u0005],\u0006 \u0003אייתוה לההוא גברא דלא הוה מוקר אבוה ואמיה\u0004 \u0005[הביאו\u0006 לפני בית דינו של רב חסדא \u0005אדם אחד שלא היה מכבד אביו ואמו],\u0006 \u0003כפתוהו\u0004 \u0005[קשרו אותו]\u0006 על העמוד על מנת להלקותו,","\u0003אמר להו\u0004 \u0005[להם]\u0006 רמי בר תמרי: \u0003שבקוהו\u0004 \u0005[הניחו לו,\u0006 אל תלקוהו\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 כי \u0003כל מצות עשה שמתן שכרה\u0004 כתוב \u0003בצדה\u0004 — \u0003אין בית דין שלמטה מוזהרין עליה\u0004 לכפות על ידי ענישה, כמלקות, ובמצות כיבוד אב נאמר \"למען יאריכון ימיך\". \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא לרמי בר תמרי: \u0003חזינא לך דחריפת טובא\u0004 \u0005[רואה אני בך שאתה חריף ביותר]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רמי בר תמרי לרב חסדא: \u0003אי הוית באתריה\u0004 \u0005[אם היית\u0006 נמצא \u0005במקומו]\u0006 של \u0003רב יהודה, אחוינא\u0004 \u0005[הייתי מראה]\u0006 \u0003לך חורפאי\u0004 \u0005[חריפותי]\u0006 הרבה יותר מעכשיו.","מתוך שנדונה בסוגיה הקודמת הנהגת מקומות שונים בדין הכחל, מביאים בדומה דברים בעניינו של הכבד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב ספרא: כי סלקת להתם\u0004 \u0005[כאשר אתה עולה לשם,\u0006 לארץ ישראל\u0005],\u0006 \u0003בעי מינייהו\u0004 \u0005[שאל מהם,\u0006 מחכמי ארץ ישראל\u0005]\u0006 שאלה זו: \u0003כבדא\u0004 \u0005[הכבד],\u0006 \u0003מה,\u0004 כיצד \u0003אתון\u0004 \u0005[אתם]\u0006 נוהגים \u0003ביה\u0004 \u0005[בו]?\u0006 ומסופר, \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 רב ספרא לארץ ישראל, \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003רב זריקא,\u0004 ושאלו באשר לכבד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב זריקא בתשובה: \u0003אנא שלקי ליה\u0004 \u0005[אני בישלתי אותו]\u0006 \u0003לר' אמי, ואכל\u0004 את הכבד.","\u0003כי\u0004 \u0005[כאשר]\u0006 חזר רב ספרא לבבל, \u0003אתא לגביה\u0004 \u0005[בא אצל]\u0006 אביי, ומסר לו את ששמע מפי רב זריקא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: בכבד שהתבשל לעצמו, ולענין \u0003למיסר נפשה\u0004 \u0005[לאסור את עצמו]\u0006 בדם שנפלט ממנו בבישול — \u0003לא קא מיבעיא\u0004 \u0005[היתה נשאלת]\u0006 \u0003לי\u0004 שאלתי, שכן ברור הוא לי שאין הדם הנפלט שב ונבלע בכבד בתוך הבישול. ואולם \u0003כי קמבעיא לי\u0004 \u0005[כאשר נשאלה לי\u0006 השאלה\u0005]\u0006 היה זה בכבד שהתבשל עם חתיכת בשר אחרת באותה קדירה, ו\u0003למיסר\u0004 \u0005[\u0006ולענין \u0005לאסור]\u0006 את \u0003חבירתה,\u0004 כלומר, אותה חתיכת בשר. ומעתה, במה שר' אמי אכל מהכבד שהתבשל כשלעצמו, אין איפוא פתרון לשאלתי. שאל רב ספרא את אביי:","\u0003מאי שנא למיסר נפשה\u0004 \u0005[במה שונה\u0006 לענין \u0005לאסור את עצמה,\u0006 כשהתבשל הכבד לעצמו\u0005],\u0006 \u0003דלא מיבעיא\u0004 \u0005[שלא נשאלה]\u0006 \u0003לך\u0004 כל שאלה וברור לך שהריהו מותר — משום \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה במסכת תרומות\u0005]\u0006 כי הכבד \u0003אינה נאסרת\u0004 בבישולה. מעתה, \u0003למיסר\u0004 \u0005[ל\u0006ענין \u0005איסור]\u0006 \u0003חבירתה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תבעי\u0004 \u0005[לא תישאל]\u0006 \u0003לך\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה זו\u0005]\u0006 כי \u0003הכבד אוסרת\u0004 את המתבשל עימה בקדירה, \u0003ואינה נאסרת, מפני שהיא\u0004 אכן \u0003פולטת\u0004 דם בשעת הבישול \u0003ו\u0004אולם היא עצמה \u0003אינה בולעת\u0004 דם זה, מתוך שהיא טרודה בפליטתו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: אין ממשנה זו פתרון לשאלתי, שכן \u0003דילמא\u0004 \u0005[שמא]\u0006 מדובר \u0003התם\u0004 \u0005[שם]\u0006 דווקא \u0003בכבדא דאיסורא\u0004 \u0005[בכבד של איסור,\u0006 ככבד של בהמה טריפה\u0005],\u0006"],["\u0003ו\u0004נאסרה החתיכה שהתבשלה עם הכבד, לא משום הדם שבלעה ממנו, אלא \u0003משום שמנוניתא\u0004 \u0005[השמנונית]\u0006 שבכבד האסור שבלעה ממנו. ואילו שאלתי היא בכבד המותר, שהתבשל עם חתיכת בשר אחרת, ו\u0003משום\u0004 בליעת \u0003דמא\u0004 \u0005[דם]\u0006 שבולעת החתיכה האחרת מהכבד, \u0003מאי\u0004 \u0005[מה]\u0006 דינה. ולא נפתרה בעייתי ממה שמסרת מפי ר' זריקא, שכן ר' אמי אכל את הכבד שהתבשל לעצמו.","ובהמשך הדברים מסופר, \u0003כי הדר סליק\u0004 \u0005[כאשר חזר\u0006 ו\u0005עלה]\u0006 רב ספרא לארץ ישראל, שוב \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003ר' זריקא,\u0004 והציע רב ספרא שוב את שאלתו לענין ההנהגה בבישול כבד, והוסיף כי שאלתו מתייחסת לכבד המתבשל עם חתיכות בשר אחרות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זריקא: \u0003האי נמי לא תבעי לך\u0004 \u0005[\u0006ב\u0005זה גם כן לא תישאל לך],\u0006 \u0003דאנא\u0004 \u0005[ש\u0006כן \u0005אני]\u0006 \u0003וינאי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אמי איקלען לבי\u0004 \u0005[הזדמנו לבית]\u0006 \u0003יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי, וקריבו לן קניא בקופיה\u0004 \u0005[והביאו לפנינו את הקנה\u0006 של הבהמה, \u0005וסביבותיו,\u0006 כל המחובר אליו\u0005],\u0006 הריאה, הלב, והכבד, שכולם התבשלו יחד, \u0003ואכלנא\u0004 \u0005[ואכלנו].\u0006 והרי זו ראיה כי אין הכבד אוסר בדם הנפלט ממנו את החתיכות שהתבשלו אתו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהקשה זאת \u0003ר' שמואל מזרוקיניא: ודלמא\u0004 \u0005[ושמא]\u0006 באותו מעשה שהעיד עליו ר' זריקא \u0003פי\u0004 ה\u0003קנה חוץ לקדרה הוה\u0004 \u0005[היה],\u0006 ובאופן זה אין דם הכבד יוצא אל תוך הקדירה, אלא עובר דרך קנה הכבד אל הקנה הגדול שבריאה, ודרכו הוא נשפך אל מחוץ לקדירה, ואין דם הכבד יכול להיבלע בשאר החתיכות. ולכך לא נאסרו הלב והריאה שהתבשלו עם הכבד. ועדיין אין אנו יודעים מה דין חתיכה שהתבשלה עם הכבד. והוסיף עוד בדחיית הראיה, \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 אפשר לומר כי במעשה שהעיד עליו ר' זריקא, \u0003מיחלט הוה חליט ליה מעיקרא\u0004 \u0005[לחלוט הוא שחלט אותו בתחילה],\u0006 שעשה בו פעולה המצמיתה את הדם במקומו שלא יצא עוד משם, לפני שהתבשל עם הריאה והלב, ולכך לא נאסרו בבישול עם הכבד. ואילו שאלת אביי היתה בכבד שלא נחלט לפני שהתבשל עם חתיכות בשר אחרות. שכן מנהג הוא לחלוט את הכבד, \u0003כי הא\u0004 \u0005[כמו זה]\u0006 ש\u0003רב הונא חלטי ליה בחלא\u0004 \u0005[היו חולטים לו\u0006 את הכבד \u0005בחומץ],\u0006 \u0003ורב נחמן חלטי ליה\u0004 \u0005[היו חולטים לו]\u0006 \u0003ב\u0004מים \u0003רותחין. ו\u0004כן למדנו בענין זה כי \u0003סבר רב פפא\u0004 שהיה תלמיד \u0003קמיה\u0004 \u0005[לפני]\u0006","\u0003רבא למימר\u0004 \u0005[לומר]\u0006 שכבד שחלטו אותו ב\u0003חלא\u0004 \u0005[חומץ]\u0006 — אותו החומץ \u0003אסיר\u0004 \u0005[אסור]\u0006 באכילה, מפני שבלע מדם הכבד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב פפא: אין זה כדבריך, שכן \u0003אי חלא אסיר\u0004 \u0005[אם החומץ\u0006 שחלטו בו את הכבד \u0005אסור]\u0006 — \u0003איהו נמי אסיר\u0004 \u0005[הוא,\u0006 הכבד \u0005גם כן אסור],\u0006 שהרי \u0003כי היכי דפליט, הדר בלע\u0004 \u0005[כמו ש\u0006הוא \u0005פולט\u0006 דם ואוסר את החומץ, כן הוא \u0005חוזר ובולע]\u0006 מן החומץ האסור, ונאסר הוא עצמו בכך. ואולם כיון שמנהג הוא לחלוט את הכבד בחומץ, הרי זה מלמד שאין החומץ נאסר בכך.","ומסופר כי \u0003רב בר שבא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב נחמן, אייתו ליה כבדא שליקא\u0004 \u0005[הביאו לפניו\u0006 לאכילה \u0005כבד שלוק,\u0006 מבושל\u0005]\u0006 \u0003ולא אכל\u0004 רב בר שבא ממנו. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 בני הבית לרב נחמן כי \u0003בר בי רב דלגיו לא אכיל\u0004 \u0005[בן בית המדרש,\u0006 תלמיד חכם \u0005שנמצא בפנים אינו אוכל]!\u0006 \u0003ומנו\u0004 \u0005[ומי הוא]?\u0006 \u0003רב בר שבא. אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן: גאמו לשבא\u0004 \u0005[האכילו את שבא]\u0006 בעל כרחו.","ומסכמים שבעייתו של אביי בדין הכבד שהתבשל עם חתיכות בשר אחרות תלויה \u0003כ\u0004מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 בה. שכן שנינו כי \u0003ר' אליעזר אומר\u0004 ש\u0003הכבד\u0004 שהתבשלה עם חתיכות בשר אחרות הריהי \u0003אוסרת\u0004 אותן, \u0003ו\u0004אילו היא עצמה \u0003אינה נאסרת, מפני ש\u0004אמנם היא \u0003פולטת\u0004 דם בזמן שהיא מתבשלת \u0003ו\u0004אולם היא עצמה \u0003אינה\u0004 שבה ו\u0003בולעת\u0004 מהדם שנפלט ממנה, שכן טרודה היא בפליטה. ואילו \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר\u0004 כי אם הכבד היתה \u0003מתובלת\u0004 כשהתבשלה עם חתיכות בשר אחרות — הריהי \u0003אוסרת\u0004 אותן, \u0003ו\u0004אף היא עצמה \u0003נאסרת\u0004 בכך, משום שהתיבול גורם לכבד לבלוע בשעת הבישול מן הדם שנפלט ממנו. וכמו כן אם הכבד היתה \u0003שלוקה\u0004 (מבושלת ביותר) — הריהי \u0003אוסרת\u0004 את החתיכות האחרות שהתבשלו עימה, \u0003ו\u0004אף היא עצמה \u0003נאסרת,\u0004 שבולעת מן הדם.","ועוד בענין הכבד, מסופר כי \u0003רבה בר רב הונא אקלע לבי\u0004 \u0005[הזדמן לביתו]\u0006 של \u0003רבה בר רב נחמן,\u0004 וסעד על שולחנו של רבה בר רב נחמן ביום השבת. בתוך כך \u0003אייתי לקמיה תלת סאוי טחאי\u0004 \u0005[הביאו לפניו\u0006 לאכול \u0005שלוש סאים\u0006 של פת נקיה ש\u0005ניטוחה\u0006 בשמן ודבש\u0005],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 רבה בר רב הונא לבני ביתו של רבה בר רב נחמן: \u0003מי הוה ידעיתו דאתינא\u0004 \u0005[האם הייתם יודעים שאני בא]\u0006 שהכנתם אוכל כה משובח? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מי עדיפת לן מינה\u0004 \u0005[האם אתה עדיף ממנה,\u0006 מהשבת\u0005],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר\u0006 בה\u0005]:\u0006 \u0003\"וקראת לשבת עונג\"\u0004 (ישעיהו נח, יג), ולכבוד השבת עשינו כן!","\u0003אדהכי, אשכח ההוא כבדא דהוה בה סמפונא דבליעא דמא\u0004 \u0005[בתוך כך, מצא\u0006 רבה בר רב הונא בתוך המאכלים שהוגשו לפניו \u0005כבד אחד שהיה בו סימפון שמובלע\u0006 בו \u0005דם],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 לבני הבית: \u0003אמאי עבדיתו הכי\u0004 \u0005[מדוע אתם עושים כך],\u0006 שהרי אף שדם הבלוע בכבד מותר, אבל דם הכנוס בסימפונות שבו הריהו אסור! \u0003אמרו ליה\u0004 \u0005[לו]\u0006 בני ביתו של רב בר נחמן: \u0003אלא היכי נעביד\u0004 \u0005[איך נעשה]\u0006 בהכשר אכילתו של הכבד? \u0003אמר להו\u0004 \u0005[להם]:\u0006 בתחילה \u0003קרעו\u0004 את הכבד \u0003שתי וערב\u0004 (לאורך ולרוחב), \u0003ו\u0004הניחו את צד \u0003חיתוכא\u0004 \u0005[החיתוך]\u0006 \u0003לתחת,\u0004 כלפי מטה, כשתתנוהו בתנור, כדי שבכך יזוב הדם ויצא.","ומעירים: \u0003והני מילי כבדא\u0004 \u0005[ודברים אלה\u0006 אמורים \u0005דווקא\u0006 \u0005בכבד],\u0006 ומפני הדם הכנוס בתוכו בסימפונות, \u0003אבל\u0004 ב\u0003טחלא\u0004 \u0005[טחול]\u0006 — אין צורך בקריעה זו, כי מה שיש בו \u0003שומנא בעלמא\u0004 \u0005[שומן בלבד]\u0006 \u0003הוא. כי הא\u0004 \u0005[כמו זה]\u0006 הנמסר לנו כי \u0003שמואל עבדי ליה תבשילא דטחלי ביומא דעביד מלתא\u0004 \u0005[היו עושים לו תבשיל של טחולים ביום שהקיז דם].\u0006","ומביאים עוד בדינו של הכבד. \u0003אתמר\u0004 \u0005[נאמר]\u0006 כי אם צלו בתנור על שיפוד חתיכות בשר, באופן זה ש\u0003כבדא עילוי בשרא\u0004 \u0005[הכבד\u0006 נתון \u0005על הבשר]\u0006 — אף שזב דם מן הכבד על הבשר, הבשר \u0003שרי\u0004 \u0005[מותר].\u0006 וטעם הדבר: שכן \u0003דמא\u0004 \u0005[הדם]\u0006 הזב מן הדבר הצלוי בתנור הריהו \u0003משרק שריק\u0004 \u0005[מחליק]\u0006 על הבשר שתחתיו ואינו נבלע בו. ואולם אם \u0003כחלא עילוי בשרא\u0004 \u0005[כחל\u0006 נמצא \u0005על הבשר]\u0006 בשעה שנצלה בתנור — הבשר \u0003אסור, מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שכן ה\u0003חלב\u0004 היוצא מן הכחל הניצלה הריהו \u0003סרוכי מסריך\u0004 \u0005[נדבק\u0006 ונבלע בבשר\u0005].\u0006","\u0003רב דימי מנהרדעא מתני אפכא\u0004 \u0005[היה שונה להיפך]:\u0006 באופן בו \u0003כחלא עילוי בשרא\u0004 \u0005[כחל מעל הבשר]\u0006 — הבשר \u0003שרי\u0004 \u0005[מותר],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שכן איסור בשר בחלב, ב\u0003חלב\u0004 של בהמה \u0003שחוטה\u0004 (כגון החלב שבכחל) אינו אלא \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 ולכך אין חוששים באיסור חכמים שמא נבלע החלב בבשר שמתחתיו. ואולם באופן בו \u0003כבדא עילוי בשרא\u0004 \u0005[כבד מעל הבשר]\u0006 — הבשר \u0003אסור,\u0004 משום שאיסור \u0003דם\u0004 הריהו איסור \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ויש לחשוש שמא בלע הבשר דם מן הכבד שמעליו.","ובענין זה \u0003דרש מרימר\u0004 ברבים, \u0003הלכתא\u0004 \u0005[הלכה]\u0006 היא: \u0003בין כבדא\u0004 \u0005[כבד]\u0006 \u0003בין כחלא\u0004 \u0005[כחל],\u0006 הניצלים בתנור עם חתיכת בשר, אם היו הכבד או הכחל \u0003תותי בשרא\u0004 \u0005[מתחת לבשר]\u0006 — \u0003שרי\u0004 \u0005[מותר]\u0006 הדבר, ואם היו \u0003עילוי בשרא\u0004 \u0005[מעל הבשר],\u0006 ב\u0003דיעבד\u0004 אם עשה כן — \u0003אין\u0004 \u0005[כן]\u0006 מותר הבשר, ואולם \u0003לכתחלה\u0004 — \u0003לא\u0004 יעשה כן.","ומסופר בענין זה כי \u0003רב אשי איקלע לבי\u0004 \u0005[הזדמן לביתו]\u0006 של \u0003רמי בר אבא חמוה\u0004 \u0005[חמיו],\u0006 \u0003חזייה לבריה\u0004 \u0005[ראה את בנו]\u0006 של \u0003רמי בר אבא דקא\u0004 \u0005[שהוא]\u0006"],["\u0003שפיד כבדא עילוי בשרא\u0004 \u0005[שם בשיפוד\u0006 לקראת צלייה, \u0005כבד על הבשר],\u0006 \u0003אמר\u0004 רב אשי: \u0003כמה יהיר\u0004 (גאה) הוא \u0003האי מרבנן\u0004 \u0005[תלמיד חכם זה]\u0006 שנוהג כן, שהרי \u0003אימר דאמור רבנן\u0004 \u0005[אמור שאמרו חכמים]\u0006 והתירו ב\u0003דיעבד\u0004 את הבשר שנצלה בתנור תחת הכבד, ואולם לעשות כן \u0003לכתחלה מי אמור\u0004 \u0005[האם אמרו]\u0006 חכמים?!","\u0003ו\u0004עוד מוסיפים בדין צליית כבד ובשר בתנור: \u0003אי איכא בי דוגי\u0004 \u0005[אם יש\u0006 מתחת לשיפוד כלי \u0005שבו נאסף השומן\u0006 הנוטף\u0005]\u0006 — אפילו באופן בו \u0003בשרא עילוי כבדא, נמי אסיר\u0004 \u0005[הבשר על הכבד, גם כן אסור]\u0006 לצלות את הבשר, שהשומן שנאסף בכלי אסור, מפני שיש בו מדם הכבד, ועלול לאוכלו.","ושואלים על כך: \u0003ומאי שנא\u0004 \u0005[ומה שונה,\u0006 במה נבדל\u0005]\u0006 צליית כבד על בשר במקום שיש בו כלי לאיסוף השומן שהריהו אסור, \u0003מ\u0004צליית חתיכת בשר מעל כלי כזה, שהרי \u0003דמא דבשרא\u0004 \u0005[דם הבשר]\u0006 נוטף עם השומן לתוך הכלי, ונאסר השומן בכך? ומשיבים: \u0003דמא דבשרא\u0004 \u0005[דם הבשר]\u0006 — \u0003שכן\u0004 \u0005[שוקע]\u0006 אל תחתית הכלי, והשומן צף מעליו, וניתן להפריד את השומן מעליו, ולכך מותר השומן. ואילו \u0003דמא דכבדא\u0004 \u0005[דם הכבד]\u0006 — הריהו \u0003קפי\u0004 \u0005[צף]\u0006 מעל השומן, ולא ניתן להפרידם, ולכך אסור הדבר.","ומביאים עוד בהלכה דומה, \u0003אמר רב נחמן, אמר שמואל: סכין\u0004 של שחיטה \u0003ששחט בה,\u0004 כיון שמקום השחיטה (\"בית השחיטה) חם ביותר — בלעה הסכין מדם השחיטה, ומעתה \u0003אסור\u0004 לשוב ו\u0003לחתוך בה\u0004 דבר מאכל \u0003רותח,\u0004 שהרי היא מבליעה בו מדם השחיטה הבלוע בה. ואם חתך בסכין זו דבר מאכל \u0003צונן\u0004 — \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 כי חתיכה זו שנחתכה \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003הדחה\u0004 כדי להתירה באכילה, \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי \u0003לא בעיא\u0004 \u0005[אינה צריכה]\u0006 \u0003הדחה.\u0004","ועוד הלכות בשמו של שמואל, \u0003אמר רב יהודה, אמר שמואל: קערה שמלח בה בשר,\u0004 כדי להוציא את דמו לקראת בישולו — כיון שנבלע מן הדם בקערה, \u0003אסור לאכול בה\u0004 דבר מאכל \u0003רותח,\u0004 שהרי הקערה חוזרת ונותנת בו מהדם הבלוע בה. \u0003ו\u0004מסבירים כי בהלכה זו הולך \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכן \u0003אמר שמואל:\u0004 הדבר ה\u0003מליח\u0004 — \u0003הרי הוא\u0004 נחשב \u0003כרותח, ו\u0004הדבר ה\u0003כבוש\u0004 — \u0003הרי הוא\u0004 נחשב \u0003כמבושל.\u0004","ובענין זה נמסר, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: מליח\u0004 — \u0003אינו כרותח, וכבוש\u0004 — \u0003אינו כמבושל.\u0004 \u0003אמר אביי: הא\u0004 \u0005[זו]\u0006 המסורת של \u0003רבין\u0004 בשם ר' יוחנן, \u0003ליתא\u0004 \u0005[אינה\u0006 נכונה\u0005],\u0006 וראיה לדבר, \u0003דההיא פינכא דהוה בי\u0004 \u0005[שקערת חרס אחת שהיתה בבית]\u0006 \u0003ר' אמי, דמלח ביה בשרא, ותבריה\u0004 \u0005[שהיה מולח בה בשר, ושברו\u0006 ר' אמי לכלי זה\u0005]\u0006 שלא יוכלו להשתמש בו עוד. \u0003מכדי\u0004 \u0005[הרי],\u0006 \u0003ר' אמי תלמיד\u0004 של \u0003ר' יוחנן הוה\u0004 \u0005[היה],\u0006 \u0003מאי טעמא תבריה\u0004 \u0005[מה טעם שברו]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דשמיעא ליה מיניה\u0004 \u0005[ששמע זאת ממנו]\u0006 מ\u0003ר' יוחנן\u0004 ש\u0003אמר: מליח\u0004 — \u0003הרי הוא כרותח!\u0004 הרי שדעת ר' יוחנן היא כשמואל, ושלא כדברי רבין. ועוד נמסר בהלכה זו כי","\u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב כהנא אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב יהודה קמיה\u0004 \u0005[לפני]\u0006 \u0003רב הונא, ויתיב וקאמר\u0004 \u0005[וישב ואמר]:\u0006 \u0003קערה שמלח בה בשר\u0004 — \u0003אסור לאכול בה\u0004 מאכל \u0003רותח.\u0004 \u0003ו\u0004הוסיף עוד הלכה: \u0003צנון שחתכו בסכין\u0004 שעליה שמנונית בשר שנחתך בה — אף שיש חריפות בצנון, ומתוך כך הריהו בולע מן הסכין, מכל מקום \u0003מותר לאכלו בכותח\u0004 (מאכל חלב).","ודנים בדברי רב כהנא: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מבחינים אנו בין הדם הבלוע בקערה (שנמלח בה בשר) שאוסר אכילת רותח בקערה זו, לבין שמנונית הבשר שעל הסכין (שחתך בה צנון) שאינה אוסרת את הצנון מלהיאכל במאכל חלבי? \u0003אמר אביי: האי\u0004 \u0005[זה]\u0006 הצנון — \u0003היתרא\u0004 \u0005[היתר]\u0006 \u0003בלע,\u0004 שהרי שמנונית הבשר שעל הסכין מותרת באכילה, \u0003ו\u0004אילו \u0003האי\u0004 \u0005[זו]\u0006 הקערה שמלח בה בשר — \u0003איסורא\u0004 \u0005[איסור,\u0006 דם\u0005]\u0006 \u0003בלע.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לאביי: מה בכך, והרי גם \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003בלע היתרא\u0004 \u0005[היתר],\u0006 כצנון זה, \u0003מאי הוי\u0004 \u0005[מה נהיה]?!\u0006 \u0003סוף סוף,\u0004 לכשיבוא לאכול צנון זה בכותח, \u0003האי היתרא דאתי לידי איסורא\u0004 \u0005[זה היתר שבא לידי איסור]\u0006 \u0003הוא, דאיסורא קאכיל\u0004 \u0005[ש\u0006עתה \u0005איסור הוא אוכל]!\u0006 \u0003אלא אמר רבא\u0004 בהסבר דברי רב כהנא הללו: יש הבדל בין קערה שנמלח בה בשר לבין צנון שנחתך בסכין שחתכו בו בשר, שכן \u0003האי\u0004 \u0005[זה]\u0006 טעם הבשר שבצנון, \u0003אפשר\u0004 לאדם מישראל \u0003למטעמיה\u0004 \u0005[לטעום אותו],\u0006 שהרי הוא מותר באכילה \u0003ו\u0004אילו \u0003האי\u0004 \u0005[זה]\u0006 הדם שנבלע בקערה, \u0003לא אפשר למטעמיה\u0004 \u0005[אי אפשר לטעום אותו].\u0006 שהרי הדם אסור באכילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לרבא: ו\u0004הרי גם בקערה ניתן לדעת אם יש בה טעם דם, ש\u0003ליטעמיה קפילא ארמאה\u0004 \u0005[שיטעם אותו טבח גוי],\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו]\u0006 כי \u0003קדרה שבישל בה בשר\u0004 — \u0003לא יבשל בה חלב, ואם\u0004 עבר ו\u0003בשל\u0004 — הרי היא אוסרת \u0003ב\u0004שיעור שיש בו כדי ש\u0003נותן\u0004 הבשר \u0003טעם\u0004 בחלב. וכן קדירה ש\u0003בשל בה תרומה\u0004 האסורה באכילה למי שאינו כהן — \u0003לא יבשל בה חולין. ואם בשל\u0004 — החולין אסורים באכילה למי שאינו כהן, \u0003ב\u0004שיעור ש\u0003נותן\u0004 התרומה \u0003טעם\u0004 בחולין.","\u0003ואמרינן\u0004 \u0005[ואמרנו,\u0006 ושאלנו\u0005]:\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 לגבי נתינת טעם \u0003תרומה\u0004 בחולין — יכול \u0003ש\u0004\u0003טעים לה\u0004 \u0005[טועם אותה,\u0006 את התערובת\u0005]\u0006 \u0003כהן,\u0004 ואומר אם נתנה טעם או לא. \u0003אלא בשר בחלב, מאן טעים לה\u0004 \u0005[מי טועם אותה]\u0006 שיאמר לנו אם יש טעם בשר בחלב, שהרי הדבר אסור לישראלי?! \u0003ואמר לן\u0004 \u0005[לנו\u0006 רבא\u0005]:\u0006 \u0003ליטעמיה קפילא\u0004 \u0005[שיטעם אותו טבח גוי],\u0006 \u0003הכי נמי ליטעמיה קפילא\u0004 \u0005[כאן גם כן שיטעם אותו טבח גוי]!\u0006 השיב רבא לרב פפא: \u0003הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן],\u0006 במקרה זה שלפנינו, שאם יש לפנינו טבח גוי — נותנים אנו לו לטעום, ואולם \u0003כי קאמינא דליכא קפילא\u0004 \u0005[כאשר אמרתי\u0006 את דבריי, הרי זה \u0005כשאין טבח גוי].\u0006","ומביאים עוד בענין קרוב, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בדינם של \u0003דגים שעלו\u0004 מן הצלי, וניתנו בעודם רותחים \u0003בקערה\u0004 שאכלו בה בשר, שעתה בלוע בהם טעם בשר, ש\u0003רב אמר\u0004 כי \u0003אסור לאכלן בכותח,\u0004 שהוא מאכל חלב, מפני איסור בשר בחלב. \u0003ו\u0004אילו \u0003שמואל אמר\u0004 כי \u0003מותר לאכלן בכותח.\u0004","ומסבירים את שיטותיהם: \u0003רב אמר\u0004 כי \u0003אסור\u0004 לאוכלם בכותח, משום שטעם הבשר שבקערה \u0003נותן טעם הוא\u0004 בדגים, וטעם זה יינתן בכותח. \u0003ושמואל אמר\u0004 כי \u0003מותר\u0004 לאוכלם בכותח, שכן אין טעם הבשר ניתן במישרין בדגים, שהרי לא נתבשלו הדגים עם בשר כאחד, אלא \u0003נותן טעם בר\u0004 \u0005[בן]\u0006 \u0003נותן טעם הוא,\u0004 שטעם הבשר נכנס בתחילה בקערה, שהיא עצמה אינה בשר אלא מוטעמת מבשר (\"נותן טעם\"), ומשם בא טעם הבשר לדגים (והריהם \"בר נותן טעם\"). ובאופן זה מותר לאכול את הדגים בכותח.","ומעירים: \u0003והא\u0004 \u0005[ו\u0006הלכה \u0005זו]\u0006 של \u0003רב, לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש איתמר\u0004 \u0005[נאמרה]\u0006 \u0003אלא מכללא איתמר\u0004 \u0005[מכלל\u0006 הדברים \u0005נאמרה],\u0006 כיצד? ש\u0003רב איקלע לבי\u0004 \u0005[הזדמן לביתו]\u0006 של \u0003רב שימי בר חייא בר בריה\u0004 \u0005[בן בנו],\u0006 \u0003חש\u0004 כאבים \u0003בעיניו,\u0004 ו\u0003עבדו ליה שייפא בצעא\u0004 \u0005[עשו לו\u0006 לרפואתו \u0005משחה בתוך קערה],\u0006 \u0003בתר הכי רמו ליה בשולא בגווה\u0004 \u0005[לאחר כך שמו לו תבשיל בתוכה,\u0006 בתוך הקערה הזו\u0005],\u0006 \u0003טעים ליה טעמא דשייפא\u0004 \u0005[טעם בו\u0006 בתבשיל את \u0005טעם המשחה],\u0006 \u0003אמר: יהיב טעמא כולי האי\u0004 \u0005[נותן\u0006 הוא \u0005טעם כל זאת,\u0006 כל כך הרבה\u0005],\u0006 ומכאן הסיקו השומעים כי שיטת רב היא שדבר שהוא נותן טעם בן נותן טעם, עדיין יש בכוחו לתת טעם. ודוחים ראיה זו: \u0003ולא היא,\u0004 אין ממעשה זה להסיק מסקנה כוללת לענין כל נותן טעם בן נותן טעם, \u0003שכן\u0004 \u0003שאני התם דנפיש מררה טפי\u0004 \u0005[שונה,\u0006 נבדל משאר מקרים הוא \u0005המקרה\u0006 \u0005שם, שמרובה מרירותה מאד\u0006 של משחת התרופה\u0005],\u0006 ולכן היא נותנת טעם אף באופן זה.","ובענין זה מסופר: \u0003ר' אלעזר הוה קאים קמיה\u0004 \u0005[היה עומד לפני]\u0006 \u0003מר שמואל, אייתו לקמיה\u0004 \u0005[הביאו לפניו,\u0006 לפני שמואל\u0005]\u0006 \u0003דגים\u0004 \u0003שעלו\u0004 (שהתבשלו) \u0003בקערה\u0004 של בשר, \u0003וקא אכיל\u0004 \u0005[והיה אוכל]\u0006 אותם \u0003ב\u0004יחד עם \u0003כותח. יהיב ליה\u0004 \u0005[נתן לו]\u0006 שמואל לר' אלעזר מתבשיל זה, \u0003ולא אכל\u0004 ר' אלעזר, שכן הוא תלמידו של רב האוסר תבשיל שכזה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 שמואל: \u0003לרבך,\u0004 כלומר, לרב, \u0003יהיבי ליה\u0004 \u0005[נתתי לו]\u0006 לאכול מתבשיל כזה, \u0003ואכל, ואת לא אכלת\u0004 \u0005[ואתה אינך אוכל]?\u0006 לאחר זמן, ר' אלעזר \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב, אמר ליה\u0004 \u0005[לו]\u0006 ר' אלעזר לרב: האם \u0003הדר ביה מר משמעתיה\u0004 \u0005[חזר בו אדוני מהלכתו],\u0006 והריהו מתיר אכילת תבשיל כזה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב בתשובה: \u0003חס ליה לזרעיה\u0004 \u0005[חס\u0006 ושלום \u0005לו לזרעו,\u0006 לבנו\u0005]\u0006 של \u0003אבא בר אבא\u0004 אביו של שמואל \u0003דליספי לי מידי ולא סבירא לי\u0004 \u0005[שיאכילני דבר שאין אני סבור בו\u0006 שהוא מותר באכילה\u0005],\u0006 שלא היו דברים אלה מעולם, ולא האכילו שמואל תבשיל כזה.","ועוד מסופר בתבשיל דגים שעלו מקערה של בשר ולענין אכילתם בכותח, \u0003ש\u0004\u0003רב הונא ורב חייא בר אשי הוו יתבי\u0004 \u0005[היו יושבים]\u0006 לסעודה. \u0003חד בהאי גיסא דמברא\u0004 \u0005[אחד\u0006 ישב \u0005בצד זה של המעבורת]\u0006 של נהר \u0003סורא,\u0004 \u0003וחד בהאי גיסא דמברא\u0004 \u0005[ואחד\u0006 ישב \u0005בצד זה של המעבורת].\u0006 \u0003למר אייתו ליה\u0004 \u0005[לחכם זה הביאו לו]\u0006 \u0003דגים שעלו בקערה ואכל בכותח, למר אייתו ליה\u0004 \u0005[לחכם זה הביאו לו]\u0006 \u0003תאנים וענבים בתוך הסעודה, ואכל, ולא בריך\u0004 \u0005[ולא בירך]\u0006 על אכילת התאנים והענבים, לפניה ולאחריה, אף שאין הם באים ללפת את הפת והדרך הנוהגת היא להביאם לאחר הסעודה ולברך עליהם.","\u0003מר אמר ליה לחבריה\u0004 \u0005[חכם זה אמר לו לחבירו]:\u0006 \u0003יתמא\u0004 \u0005[יתום],\u0006 כלומר, שאין לו רב! וכי \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003רבך הכי\u0004 \u0005[כך]\u0006 לאכול דגים כאלה בכותח? \u0003ומר אמר ליה לחבריה\u0004 \u0005[וחכם זה אמר לו לחבירו]:\u0006 \u0003יתמא\u0004 \u0005[יתום]!\u0006 וכי \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003רבך הכי\u0004 \u0005[כך]\u0006 לאכול פירות בתוך הסעודה בלא לברך עליהם? \u0003מר אמר ליה לחבריה\u0004 \u0005[חכם זה אמר לו לחבירו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כשמואל סבירא לי\u0004 \u0005[סבור אני]\u0006 שמתיר אכילת דגים אלה בכותח, \u0003ומר אמר ליה לחבריה\u0004 \u0005[וחכם זה אמר לו לחבירו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003כר' חייא סבירא לי\u0004 \u0005[סבור אני],\u0006 \u0003דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003ר' חייא\u0004 ברייתא זו: \u0003פת\u0004 שבירך עליה תחילה — הריהי \u0003פוטרת כל מיני מאכל\u0004 שבאותה סעודה, מלברך עליהם. \u0003ו\u0004כן \u0003יין\u0004 שבירך עליו — הריהו \u0003פוטר כל מיני משקין\u0004 שבאותה סעודה מלברך עליהם.","ובסיכומם של דברים, \u0003אמר חזקיה משום\u0004 \u0005[בשם]\u0006 \u0003אביי: הלכתא\u0004 \u0005[הלכה]\u0006 היא כי \u0003דגים שעלו בקערה\u0004 של בשר — \u0003מותר לאוכלן בכותח,\u0004 וכשיטת שמואל. ואילו \u0003צנון שחתכו בסכין שחתך בה בשר\u0004 — \u0003אסור לאוכלו בכותח,\u0004 ושלא כשיטת רב כהנא.","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא ב\u0003צנון,\u0004"],["\u0003דאגב חורפיה בלע\u0004 \u0005[שמתוך חריפותו\u0006 הוא \u0005בולע\u0006 ביותר\u0005]\u0006 ובלע משמנונית הבשר שבסכין, ונאסר בכך לאכילה בכותח. \u0003אבל\u0004 סכין שיש בה טעם בשר שחתכה את ירק ה\u0003קישות,\u0004 שאין בירק כזה חריפות כשל צנון — אין הקישות נאסר בכך לאכילה בכותח, שאין שמנונית הבשר נבלעת בו, ולכך די שיהא \u0003גריר לבי פסקיה ואכיל\u0004 \u0005[גורר,\u0006 מסיר \u0005את מקום החיתוך, ואוכל]\u0006 את הקישות אף בכותח.","וכן \u0003קילחי דליפתא\u0004 \u0005[קלחים של לפת]\u0006 שנחתכו בסכין שיש בה טעם בשר — \u0003שרי\u0004 \u0005[מותרים]\u0006 הם באכילה עם כותח. ואולם קלחים \u0003דסילקא\u0004 \u0005[של סלק]\u0006 שנחתכו בסכין שיש בה טעם בשר — הריהם \u0003אסירי\u0004 \u0005[אסורים]\u0006 באכילה עם כותח, לפי שהסכין בחיתוכם נתן בהם משמנונית הבשר שבה. \u0003ו\u0004אולם \u0003אי פתך בהו דליפתא\u0004 \u0005[אם עירב\u0006 בין קלחי הסלק, \u0005קלחי\u0006 \u0005לפת]\u0006 באופן שחתך בתחילה בקלחי הלפת ולאחר מכן בקלחי הסלק — \u0003שפיר דמי\u0004 \u0005[יפה נחשב],\u0006 ומותר, שכן חיתוך קלחי הלפת מבטל את טעם השמנונית שבסכין.","ובענין קרוב מביאים מה ש\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב דימי מרב נחמן: מהו\u0004 הדין \u0003ל\u0004ענין \u0003אנוחי כדא דמלחא גבי כדא דכמכא\u0004 \u0005[הנחת כד מלח,\u0006 שממנו רגילים למלוח את התבשיל הבשרי, \u0005אצל\u0006 ליד \u0005כד של כותח,\u0006 שהוא מאכל חלבי\u0005],\u0006 האם יש מקום לחשוש שמא יפול מן הכותח במלח, בלא שידע, ויבוא למלוח ממנו את התבשיל הבשרי? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לרב דימי בתשובה: \u0003אסור\u0004 הדבר. חזר ושאל אותו רב דימי: וכד \u0003דחלא מאי\u0004 \u0005[של חומץ,\u0006 הניתן בתבשיל הבשרי בצד כד של כותח, \u0005מהו],\u0006 האם יש לחשוש שמא יפול מן הכותח אל החומץ? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שרי\u0004 \u0005[מותר]\u0006 הדבר, שאין מקום לחשש זה.","חזר ושאל רב דימי: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 הדבר, מה ההבדל בין שני אלה? השיב לו רב נחמן: \u0003לכי תיכול עלה כורא דמלחא\u0004 \u0005[כאשר תמדוד על כך כור,\u0006 מידה גדולה, \u0005של מלח]\u0006 אז תבין! כלומר, עיין ותבין בעצמך. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003האי\u0004 \u0005[זה,\u0006 כותח שנפל ממנו למלח\u0005]\u0006 — \u0003איתיה איסורא בעיניה\u0004 \u0005[ישנו האיסור בעינו],\u0006 שהרי הוא ניכר, שכן הריהו עבה, ואין הוא בטל במלח. ולכך אסור להניח את כד הכותח בצד כד המלח. \u0003ו\u0004אילו \u0003האי\u0004 \u0005[זה,\u0006 כותח שנפל לחומץ\u0005]\u0006 — \u0003ליתיה איסורא בעיניה\u0004 \u0005[אין האיסור\u0006 ניכר \u0005בעינו].\u0006 ואין הכותח נותן טעם בחומץ.","ועוד בדינו של כד כותח, נמסר כי \u0003ההוא בר גוזלא דנפל לכדא דכמכא\u0004 \u0005[גוזל אחד שנפל לתוך כד של כותח],\u0006 ואף שהכותח הוא מאכל חלבי — \u0003שרייה\u0004 \u0005[התיר אותו]\u0006 \u0003רב חיננא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מפשרוניא\u0004 את הגוזל באכילה. \u0003אמר רבא: מאן חכים למישרי כי האי גוונא\u0004 \u0005[מיהו החכם להתיר דבר כזה\u0006 שנראה על פניו כאיסור\u0005],\u0006 \u0003אי לאו\u0004 \u0005[אם לא]\u0006 \u0003רב חיננא\u0004 \u0003בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מפשרוניא!\u0004 וטעם ההיתר, שכן \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 כך: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר שמואל מליח הרי הוא כרותח\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא\u0004 \u0005[במקום,\u0006 באופן\u0005]\u0006 שהוא מלוח כל כך, עד שהוא \u0003אינו נאכל מחמת מלחו. אבל האי כותחא\u0004 \u0005[כותח זה]\u0006 \u0003הרי נאכל מחמת מלחו. ו\u0004בהגדרה מדוייקת של","היתר זה בגוזל מוסיפים כי \u0003הני מילי\u0004 \u0005[ודברים אלה]\u0006 שהותר הגוזל, נאמרו רק בבשר גוזל \u0003חי\u0004 (שאין הבשר מבושל), \u0003אבל\u0004 אם היה זה בשר גוזל \u0003צלי\u0004 — \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003קליפה\u0004 \u0005[היה צריך לקלוף אותו]\u0006 מלמעלה סביב. \u0003ואי אית ביה פילי\u0004 \u0005[ואם יש בו,\u0006 בבשר הגוזל, \u0005בקעים]\u0006 — \u0003כוליה\u0004 \u0005[כולו]\u0006 \u0003אסור,\u0004 שכן הריהו בולע מבעד בקעיו. \u0003ו\u0004כן \u0003אי מתבל\u0004 \u0005[אם\u0006 הוא \u0005מתובל]\u0006 \u0003בתבלין\u0004 — הרי התבלין מרכך את הבשר, ובולע ו\u0003כוליה\u0004 \u0005[כולו]\u0006 \u0003אסור.\u0004","\u0003אמר רב נחמן, אמר שמואל: ככר\u0004 לחם \u0003שחתך עליה בשר\u0004 צלוי — \u0003אסור לאכלה,\u0004 מפני שהדם היוצא מן הבשר הצלוי נבלע בה. ומסייגים הלכה זו בכמה סיוגים: \u0003והני מילי דאסמיק\u0004 \u0005[ודברים אלה\u0006 נאמרו רק כ\u0005שמואדם\u0006 הבשר\u0005]\u0006 מפני ריבוי הדם שבו, ולא בשאר בשר. \u0003ו\u0004עוד: \u0003הני מילי דאבריה\u0004 \u0005[\u0006\u0005דברים אלה\u0006 נאמרו דווקא \u0005כ\u0006\u0005שעברו],\u0006 שחלחל הדם שנבלע בככר הלחם מצד לצד, עד שנראה משני הצדדים. \u0003ו\u0004\u0005עוד:\u0006 \u0003הני מילי דאסמכיה\u0004 \u0005[דברים אלה\u0006 נאמרו דווקא כ\u0005שסמיך\u0006 הוא הנוזל היוצא מן הבשר הצלוי\u0005],\u0006 \u0003אבל\u0004 אם היה \u0003קלישתא\u0004 \u0005[קלוש,\u0006 צלול\u0005]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 איסור בככר לחם זה.","ומסופר כי \u0003שמואל שדי ליה לכלביה\u0004 \u0005[היה זורק אותו,\u0006 אותו ככר לחם \u0005לכלבו],\u0006 אף שהתקיימו בו כל התנאים הללו, ואילו \u0003רב הונא\u0004 לא היה אוכל ככר זו, אלא \u0003יהיב ליה לשמעיה\u0004 \u0005[היה נותן אותו לשמשו].\u0006 על דבר זה תוהים: \u0003מה נפשך\u0004 \u0005[מה רצונך]\u0006 בהנהגה זו של רב הונא, שכן \u0003אי שרי\u0004 \u0005[אם מותר\u0006 לאכול\u0005]\u0006 ככר זו — \u0003לכולי עלמא שרי\u0004 \u0005[לכל מותר],\u0006 ואף רב הונא יכול לאוכלה. ו\u0003אי\u0004 \u0005[אם]\u0006 \u0003אסור\u0004 לאכול ככר זו — \u0003לכולי עלמא\u0004 \u0005[לכל]\u0006 \u0003אסור,\u0004 ואין לתת לשמש! ומשיבים: מותרת ככר זו באכילה, ואולם \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד\u0005]\u0006 הוא \u0003רב הונא, דאנינא דעתיה\u0004 \u0005[שדעתו אנינה],\u0006 ונמנע מלאוכלה לא מחמת האיסור אלא מפני שלא היה נעים לו לאכול את הדבר, ולכך נתן לשמשו לאכול. \u0003רבא אכיל ליה, וקרי ליה \"חמר בשר\"\u0004 \u0005[היה אוכל אותו, והיה קורא לו \"יין בשר\"].\u0006","ועוד הלכה דומה, \u0003אמר רב נחמן, אמר שמואל: אין מניחין כלי תחת בשר\u0004 הנצלה, כדי לקלוט בו את שמנונית הבשר, \u0003עד שיכלה כל מראה אדמומית שבו,\u0004 שכבר נפלט כל דמו של הבשר מתוכו, ומעתה יוצאים שומנים הכשרים לאכילה. ושואלים: \u0003מנא ידעינן\u0004 \u0005[מנין יודעים אנו]\u0006 שכלה מראה אדמומית שבו? ומשיבים: \u0003מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב פפא אמר: משתעלה תימרתו\u0004 (משיעלה העשן מן הבשר), הרי זה סימן שנגמר כבר תהליך יציאת הדם מן הבשר.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: ודלמא תתאה מטא, עילאה לא מטא\u0004 \u0005[ושמא\u0006 הצד \u0005התחתון\u0006 של הבשר, זה \u0005הנמצא על הגחלים אמנם כבר\u0006 \u0005נצלה,\u0006 אבל הצד \u0005העליון\u0006 של הבשר עדיין \u0005לא נצלה,\u0006 ויוצא ממנו דם האסור באכילה\u0005]?\u0006 \u0003אלא אמר רב אשי: לית ליה תקנתא\u0004 \u0005[אין לו תקנה]\u0006 לזה הרוצה לאסוף משמנונית בשר הנצלה על גחלים, \u0003אלא משדא ביה תרתי גללי מלחא\u0004 \u0005[לשים בו\u0006 בכלי שמתחת לבשר וכן על הבשר \u0005שני גושי מלח],\u0006"],["ובאופן זה הדם היוצא מחתיכת הבשר הנצלית נגרר למלח בשולי הכלי, ואילו השומן היוצא מחתיכת הבשר צף מעליו, \u0003ומשפייה\u0004 \u0005[ומטהו]\u0006 את הכלי בנחת, לעבר כלי אחר שמתחתיו, ומערה בזהירות את השמנונית אל הכלי האחר, מבלי שיתערב בה הדם שבשולי הכלי.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא לרב אשי\u0004 בשאלה על דברי רב נחמן בשם שמואל כי לאחר שכלה מראה האדמומית מן הבשר מותר להניח כלי מתחתיו לאסוף את שומניו: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל\u0004 כי \u0003ככר שחתך עליה בשר אסור לאכלה,\u0004 הרי משמע שאף שלאחר שכבר נצלה הבשר עדיין יש בו דם! השיב לו רב אשי: אכן משעה שנצלה הבשר ואין ניכר עוד מראה אדמומית בנוזל היוצא ממנו — אין אותו נוזל דם אסור. ואולם \u0003שאני התם\u0004 \u0005[שונה שם,\u0006 בחיתוך בשר בסכין\u0005],\u0006 משום \u0003דאגב דוחקא דסכינא,\u0004 \u0003פליט\u0004 \u0005[שמתוך דוחק,\u0006 לחץ \u0005הסכין,\u0006 הבשר \u0005פולט\u0006 דם ממש\u0005].\u0006","ועוד בהלכות אלה, \u0003אמר רב נחמן: דגים ועופות שמלחן זה עם זה\u0004 — הדגים \u0003אסורין\u0004 באכילה, מפני דם העופות שנבלע בהם. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 הם מונחים \u0003בכלי שאינו מנוקב,\u0004 שאין לדם היוצא מהעופות אפשרות לזוב אל מחוץ לכלי — לא רק בדגים ועופות, אלא \u0003אפילו עופות ועופות נמי אסירי\u0004 \u0005[גם כן אסורים],\u0006 שהרי הדם היוצא מעוף אחד נבלע בעוף האחר! ו\u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003בכלי מנוקב\u0004 ויש אפשרות לדם לזוב החוצה — \u0003אפילו דגים ועופות נמי שרי\u0004 \u0005[גם כן מותר]!\u0006","ומשיבים: \u0003לעולם\u0004 מדובר \u0003בכלי מנוקב,\u0004 ולכן דווקא ה\u0003דגים\u0004 אסורים \u0003משום דרפו קרמייהו\u0004 \u0005[שרפוי\u0006 הוא \u0005הקרום שלהם]\u0006 שאין להם עור קשה, ולכך כשהם מומלחים הריהם \u0003קדמי ופלטי\u0004 \u0005[מקדימים ופולטים],\u0006 את דמם, \u0003ו\u0004אילו ה\u0003עופות\u0004 הינם \u0003קמיטי\u0004 \u0005[נוקשים],\u0006 ואין הם ממהרים לפלוט דם. וכך קורה, כי \u0003בתר דניחי\u0004 \u0005[אחרי שנחים,\u0006 מסיימים\u0005]\u0006 ה\u0003דגים\u0004 מלפלוט את דמם, \u0003פליטי\u0004 \u0005[פולטים]\u0006 ה\u0003עופות\u0004 את דמם, \u0003והדר בלעי מיניה\u0004 \u0005[וחוזרים\u0006 הדגים \u0005ובולעים ממנו,\u0006 מדם העופות\u0005].\u0006 ולכן בעופות ועופות אינם נאסרים כיון שכל העופות פולטים דמם בזמן אחד.","ומסופר \u0003כי\u0004 \u0003רב מרי בר רחל אימלח ליה\u0004 \u0005[נמלח לו]\u0006 בכלי מנוקב כדרך מליחת הבשר, \u0003בשר שחוטה בהדי\u0004 \u0005[יחד עם]\u0006 \u0003בשר טרפה, אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא\u0004 לשאול בדינו של בשר השחוטה. שכן יש מקום לומר שמאחר וחתיכת הבשר הכשירה היתה עסוקה בפליטת דמה על ידי המליחה, לא בלעה באותה עת מבשר הטריפה, ולא נאסרה על ידה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: מה שנאמר בפרשת מאכלות אסורות \"אלה \u0003הטמאים\u0004 לכם\" (ויקרא יא, לא), ובצורת ריבוי בה\"א הידיעה (\"הטמאים\") — הרי זה בא \u0003לאסור\u0004 באכילה לא רק את בשרם של אלה, אלא אף את \u0003צירן\u0004 והציר (שיוצא מהם על ידי המלח), \u0003ורוטבן\u0004 ואת המרק שלהם, \u0003וקיפה שלהן\u0004 (תבלין שבקדירה). ומאחר וצירם אסור, נאסר גם הבשר השחוט שנמלח אתם. שכן נבלע הציר בבשר, אף שהבשר פולט באותה עת את דמו. שהרי הציר נוח להיבלע יותר מן הדם."],["ושואלים: \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 רבא לרב מרי בר רחל שאסור בשר השחוטה, מפני שכך עולה \u0003מ\u0004דברי \u0003שמואל,\u0004 שכן \u0003אמר שמואל\u0004 כי ה\u0003מליח\u0004 (הדבר המלוח) \u0003הרי הוא\u0004 נחשב \u0003כרותח, ו\u0004כמו כן הדבר ה\u0003כבוש הרי הוא\u0004 נחשב \u0003כמבושל.\u0004 ולכך בשר השחוטה שנמלח עם בשר הטריפה, נחשב כאילו התבשל איתו!","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 היה פוסק לו \u0003מ\u0004תוך דברי \u0003שמואל, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא לענין \u0003דמן,\u0004 וכגון שנמלחו בכלי שאינו מנוקב, שבשר השחוטה אסור משום שלאחר שסיים לפלוט את דמו הריהו חוזר ובולע מדם הטריפה. \u0003אבל\u0004 כאשר נמלח בשר שחוטה עם בשר טריפה בכלי נקוב (שאין חשש לבליעת דם), אף משום \u0003צירן ורוטבן\u0004 של בשר הטריפה, \u0003לא\u0004 ייאסר בשר השחוטה, לכך \u0003קמשמע לן\u0004 \u0005[הוא,\u0006 רבא \u0005משמיע לנו]\u0006 שנאסר בשר השחוטה משום ציר ורוטב בשר הטריפה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בדינו של \u0003דג טהור שמלחו עם דג טמא\u0004 שהוא \u0003מותר. מאי לאו\u0004 \u0005[האם אין]\u0006 המדובר במקרה \u0003שהיו שניהן מלוחין,\u0004 ונלמד שהדג הטהור אינו נאסר מפני הציר של הדג הטמא, ושלא כדברי רבא! ודוחים: \u0003לא,\u0004 מדובר \u0003כגון שהיה\u0004 הדג ה\u0003טהור מליח ו\u0004הדג ה\u0003טמא תפל\u0004 (שאינו מלוח). ולכך הדג הטהור אינו נאסר מפני הציר של הדג הטמא, שכיון שהוא תפל אין יוצא ממנו כלל ציר.","ומקשים על הסבר \u0003זה:\u0004 \u0003והא\u0004 \u0005[והרי]\u0006 אין להעמיד כן את הדברים, שכן \u0003מדקתני סיפא\u0004 \u0005[ממה ששנה\u0006 התנא \u0005בסוף,\u0006 בהמשך דבריו\u0005]\u0006 \u0003אבל אם היה\u0004 הדג ה\u0003טהור מליח ו\u0004הדג ה\u0003טמא תפל\u0004 הרי זה מותר, \u0003מכלל\u0004 הדברים אתה לומד \u0003דרישא\u0004 \u0005[שההתחלה]\u0006 \u0003ב\u0004אופן \u0003ששניהם מלוחין עסקינן\u0004 \u0005[עוסקים אנו]!\u0006 ודוחים: לא, אין המשך הדברים עוסק במקרה אחר, אלא \u0003פרושי קא\u0004 \u0005[פירוש הוא]\u0006 \u0003מפרש\u0004 את הנשנה מקודם, וכך יש לקרוא את הדברים: דג \u0003טהור שמלחו עם דג טמא\u0004 — \u0003מותר, כיצד?\u0004 כגון \u0003שהיה\u0004 הדג ה\u0003טהור מליח ו\u0004הדג ה\u0003טמא תפל.\u0004","ואומרים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 להעמיד את הדברים, \u0003דאי סלקא דעתך\u0004 \u0005[ש\u0006כן \u0005אם עולה על דעתך]\u0006 לומר ש\u0003רישא\u0004 \u0005[ההתחלה\u0006 של הברייתא\u0005]\u0006 מדברת באופן ש\u0003שניהם מלוחים,\u0004 והסוף של הברייתא מדבר באופן שהדג הטהור מלוח והדג הטמא תפל — \u0003השתא\u0004 \u0005[עכשיו]\u0006 שהשמיענו כבר בהתחלה שאם \u0003שניהם מלוחים\u0004 — \u0003שרי\u0004 \u0005[מותר]\u0006 הדג הטהור, כאשר הדג ה\u0003טהור מליח ו\u0004הדג ה\u0003טמא תפל מיבעיא\u0004 \u0005[נצרך]\u0006 לומר שהטהור מותר?!","את הראיה הזו דוחים: \u0003אי משום הא לא איריא\u0004 \u0005[אם משום זה, לא שייך,\u0006 אין זו ראיה\u0005],\u0006 שאפשר לומר שבתחילת הברייתא מדובר במקרה ששניהם מלוחים, ובסוף מדובר כשהטהור מלוח והטמא תפל, ובאשר לשאלה מדוע יש צורך לשנות את הסוף אחר שכבר נשנתה ההתחלה של הברייתא — \u0003תנא סיפא לגלויי רישא\u0004 \u0005[שנה\u0006 את \u0005הסוף\u0006 כדי \u0005לגלות\u0006 לנו מה ענינה של \u0005ההתחלה],\u0006 \u0003דלא תימא\u0004 \u0005[שלא תאמר]\u0006 ש\u0003רישא\u0004 \u0005[ההתחלה]\u0006 מדברת כשה דג ה\u0003טהור מליח ו\u0004הדג \u0003טמא תפל,\u0004 ותסיק מכאן: \u0003אבל\u0004 אם היו \u0003שניהם מלוחין\u0004 — \u0003אסור,\u0004 לכן \u0003תנא סיפא\u0004 \u0005[שנה\u0006 התנא \u0005את\u0006 \u0005הסוף]\u0006 בו מדובר בדג \u0003טהור מליח ו\u0004בדג \u0003טמא תפל,\u0004 ו\u0003מכלל\u0004 הדברים נלמד \u0003דרישא\u0004 \u0005[שההתחלה]\u0006 מדברת ב\u0003שניהן מלוחין, ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003שרי\u0004 \u0005[מותר].\u0006","ומציעים עוד, \u0003תא שמע מסיפא דסיפא\u0004 \u0005[בוא\u0006 ו\u0005שמע מסופה של סופה\u0006 של הברייתא\u0005]\u0006 ראיה שלא כהוראתו של רבא, שכן שנינו בה: \u0003אבל אם היה\u0004 הדג ה\u0003טמא מליח ו\u0004הדג ה\u0003טהור תפל\u0004 — הדג הטהור \u0003אסור\u0004 באכילה. ונדייק בדברים הללו: דווקא באופן זה שהדג ה\u0003טמא מליח ו\u0004הדג ה\u0003טהור תפל הוא\u0004 ש\u0003אסור\u0004 הדג הטהור, \u0003הא\u0004 \u0005[הרי]\u0006 אם היו \u0003שניהן מלוחין\u0004 — \u0003שרי\u0004 \u0005[מותר]\u0006 הדג הטהור, ושלא כדברי רבא!","ודוחים: אין ללמוד כן, וטעם הדבר שנשנו הדברים בסוף סופה של הברייתא באופן זה, כי \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה\u0006 ב\u0005התחלה]\u0006 \u0003טהור מליח וטמא תפל,\u0004 לכך \u0003תנא נמי סיפא\u0004 \u0005[שנה גם כן\u0006 ב\u0005סוף]\u0006 \u0003טמא מליח וטהור תפל,\u0004 ואין מכאן להוכיח שלא כרבא.","\u0003(סימן\u0004 לזכור על ידו שלוש הלכות שאמר שמואל שתובאנה בהמשך, שהן: \u0003בישרא\u0004 \u0005[בשר],\u0006 בדרך הוצאת הדם מן הבשר; \u0003דמנח\u0004 \u0005[שמונח],\u0006 בדין הנחת בשר מלוח על גבי כלי; \u0003נפקותא\u0004 \u0005[יציאה]\u0006 בדין שבירת מפרקתה של בהמה קודם יציאת נפשה).","\u0003אמר שמואל: אין הבשר יוצא מידי\u0004 האיסור שיש ב\u0003דמו, אלא אם כן מולחו יפה יפה, ומדיחו\u0004 (שוטפו במים) \u0003יפה יפה. אתמר\u0004 \u0005[נאמר]\u0006 בדרך המליחה הראויה של הבשר ש\u0003רב הונא אמר: מולח ומדיח\u0004 אותו במים, ואילו \u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 \u0003מדיח ומולח ומדיח.\u0004 ואומרים כי \u0003לא פליגי\u0004 \u0005[אין\u0006 הם \u0005חלוקים]\u0006 כי הם מדברים במקרים שונים: \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב הונא שמולח ומדיח — בזמן \u0003דחלליה בי טבחא\u0004 \u0005[ש\u0006כבר \u0005רחצוהו\u0006 את הבשר ב\u0005בית השוחט],\u0006 ואין צורך להדיחו שוב. ואילו \u0003הא\u0004 \u0005[זה]\u0006 ששנו בברייתא שיש להדיח את הבשר לפני המליחה — בזמן \u0003דלא חלליה בי טבחא\u0004 \u0005[שלא רחצוהו\u0006 ב\u0005בית השוחט].\u0006 ועוד באשר לדרך המליחה, \u0003רב דימי מנהרדעא מלח ליה במילחא גללניתא\u0004 \u0005[היה מולח אותו,\u0006 את הבשר, \u0005במלח גס],\u0006 \u0003ומנפיץ ליה\u0004 \u0005[ו\u0006אחר כך \u0005מנפץ,\u0006 מנער \u0005אותו]\u0006 מן הבשר.","ועוד בהלכות מליחה, \u0003אמר רב משרשיא: אין מחזיקין\u0004 אין מניחים שיש \u0003דם בבני\u0004 \u0003מעיים,\u0004 ולכך אם לא נמלחו, אין הם נאסרים. ומעירים: \u0003תרגמא\u0004 \u0005[תרגם,\u0006 הסבר את דבריו\u0005]\u0006 שהם מוסבים \u0003אכרכשא ומעייא והדרא דכנתא\u0004 \u0005[על הכרכשת, ועל המעיים, ועל היקף המעיים הגדול].\u0006","והלכה נוספת \u0003אמר שמואל: אין מניחין בשר מליח אלא על גבי כלי מנוקב,\u0004 שבאופן זה יכול הדם היוצא מן הבשר על ידי המליחה לצאת אל מחוץ לכלי. אבל בכלי שאינו מנוקב, נאסף הדם בשולי הכלי, ויחזור וייבלע בבשר.","ונמסר כי \u0003רב ששת מלח ליה גרמא גרמא\u0004 \u0005[היה מולח אותו,\u0006 את הבשר, \u0005עצם עצם,\u0006 חתיכה חתיכה בנפרד\u0005].\u0006 ושואלים: \u0003תרי מאי טעמא\u0004 \u0005[שנים\u0006 יחד \u0005מה טעם]\u0006 \u0003לא\u0004 מלח? הרי זה \u0003משום דפריש מהאי ובלע האי\u0004 \u0005[שפורש\u0006 הדם \u0005מזה ובולע זה],\u0006 אם כן הוא, ב\u0003חד נמי\u0004 \u0005[אחד גם כן],\u0006 הדם \u0003פריש מהאי גיסא ובלע האי גיסא\u0004 \u0005[פורש מזה הצד ובולע זה הצד]!\u0006 \u0003אלא לא שנא\u0004 \u0005[אין\u0006 זה \u0005שונה],\u0006 שגם בכמה חתיכות בשר הנמלחות ביחד אין מקום לחשש שיצא הדם מזה וייבלע בזה\u0005.\u0006","ועוד הלכה \u0003אמר שמואל, משום\u0004 \u0005[בשם]\u0006 \u0003ר' חייא: השובר מפרקתה של בהמה\u0004 לאחר שחיטתה אבל \u0003קודם שתצא נפשה\u0004 — \u0003הרי זה\u0004 בכך \u0003מכביד את הבשר\u0004 שכן בשעת שחיטתה הבהמה עסוקה בהוצאת דם, ובשעה שנשברת מפרקתה היא מאבדת את כוחותיה ואינה מוציאה עוד מדמה, ונשאר הדם בתוכה, דבר הגורם לתוספת כובד במשקלה. \u0003ו\u0004במעשה זה הריהו \u0003גוזל את הבריות\u0004 משום ש\u0003מבליע דם באברים,\u0004 והם קונים ממנו בשר במשקל מסויים, שיש בו בתוכו חלק גדול מן הרגיל של דם.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמי בית המדרש שאלה בהבנת דברי שמואל: \u0003היכי קאמר\u0004 \u0005[כיצד הוא אמר]\u0006 את דבריו, האם אמר שהשובר את מפרקתה של בהמה קודם שתצא נפשה הריהו \u0003מכביד את הבשר, ו\u0004נמצא שבכך הוא \u0003גוזל את הבריות משום\u0004 שהוא גורם ש\u0003מבליע דם באברים.\u0004 ומכאן נסיק כי הרי כאן איסור אחד ומשום גזל הבריות, \u0003הא\u0004 \u0005[הרי]\u0006 נלמד מכאן כי אם הוא עושה כן \u0003לדידיה, שפיר דמי\u0004 \u0005[לו עצמו, נחשב\u0006 הדבר \u0005יאה,\u0006 שמותר לעשות כן\u0005].\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 שני איסורים לפנינו, שכך אמר שמואל כי השובר את מפרקתה של הבהמה קודם שתצא נפשה הריהו מכביד את הבשר, והדם שוב לא יצא ממנה, והריהו נאסר בכך לאכילה. וכן שגוזל את הבריות. ואם עשה כן \u0003לדידיה נמי\u0004 \u0005[לו עצמו גם כן]\u0006 \u0003אסור\u0004 הדבר. שאלה זו לא נפתרה ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה ללא פתרון.","\u0003המעלה את העוף עם הגבינה על השלחן\u0004 שאוכל עליו — \u0003אינו עובר ב\u0004זה על איסור \u0003לא תעשה\u0004 שמן התורה.","שנינו במשנתנו כי אין בהעלאת עוף וגבינה על שולחן אחד שאוכלים בו משום עבירה מן התורה, ונדייק מכאן: בהעלאה כשלעצמה אין איסור מן התורה, \u0003הא\u0004 \u0005[הרי]\u0006 נדייק מכאן שאם \u0003אוכלו\u0004 לעוף עם הגבינה \u0003—\u0004 \u0003עובר בלא תעשה\u0004 מן התורה, ו\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי איסור אכילת \u0003בשר עוף בחלב\u0004 הוא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 ושלא כדעת ר' עקיבא הסבור כי איסור אכילת בשר עוף בחלב אינו אלא מדרבנן! ודוחים: אין זו ראיה, שכן \u0003אימא\u0004 \u0005[אמור,\u0006 פרש\u0005]\u0006 כך את דברי משנתנו: \u0003המעלה את העוף עם הגבינה על השולחן אינו בא\u0004 בכך \u0003לידי לא תעשה,\u0004 שאף אם יאכל את בשר העוף עם הגבינה, אין הוא עובר על איסור מן התורה, וכשיטת ר' עקיבא.","כל \u0003בשר בהמה טהורה\u0004 (ולאו דווקא גדי, האמור בתורה) \u0003ב\u0004כל \u0003חלב בהמה טהורה\u0004 (ולאו דווקא בחלב האם) — הרי זה \u0003אסור לבשל\u0004 מן התורה. ואם עבר \u0003ו\u0004בישל — \u0003אסור בהנאה.\u0004 ואולם \u0003בשר בהמה טהורה בחלב בהמה טמאה,\u0004 או \u0003בשר בהמה טמאה בחלב בהמה טהורה\u0004 — \u0003מותר\u0004 לכתחילה \u0003לבשל, ומותר בהנאה\u0004 (שיכול למוכרו לגוי, וליהנות מדמי המכירה). \u0003ר' עקיבא אומר: חיה ועוף\u0004 בבישול בחלב \u0003אינם\u0004 אסורים \u0003מן התורה, ש\u0004כן \u0003נאמר\u0004 באיסור בשר בחלב \u0003\"לא תבשל גדי בחלב אמו\" שלש פעמים\u0004 (שמות כג, יט. שם לד, כו. דברים יד, כא), והמלה \"גדי\" הנאמרת שלוש פעמים מלמדת שלושה מיעוטים: \u0003פרט לחיה, ו\u0004פרט \u0003לעוף, ו\u0004פרט ל\u0003בהמה טמאה,\u0004 שכל אלה אין בשרם אסור מן התורה בבישול בחלב.","\u0003ר' יוסי הגלילי אומר: נאמר \"לא תאכלו כל נבלה\"\u0004 (דברים שם), \u0003ונאמר\u0004 באותו כתוב \u0003\"לא תבשל גדי בחלב אמו\",\u0004 ללמד: \u0003את\u0004 בעל חיים זה \u0003ש\u0004הוא \u0003אסור משום\u0004 (שנוהג בו דין) \u0003נבלה, אסור לבשל בחלב.\u0004 ומעתה, \u0003עוף שאסור משום נבלה, יכול\u0004 שגם הוא \u0003יהא אסור לבשל בחלב?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"בחלב אמו\"\u0004 — \u0003יצא עוף שאין לו חלב אם.\u0004","שנינו במשנתנו כי כל בשר בהמה טהורה בכלל איסור בשר בחלב, ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ר' אלעזר:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וישלח יהודה את גדי העזים\"\u0004 (בראשית לח, כ),"],["\u0003כאן\u0004 פירש לנו הכתוב שמדובר ב\u0003גדי\u0004 של \u0003עזים\u0004 דווקא. ולכך נאמר בו בלשון מגדירה \"גדי העזים\" (בראשית לח, כ). ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 שב\u0003כל מקום\u0004 בתורה \u0003שנאמר\u0004 בו \u0003\"גדי\" סתם\u0004 — \u0003אפילו\u0004 ולד של \u0003פרה ורחל במשמע.\u0004 ומכאן ראיה שגם \"גדי\" האמור באיסור בשר בחלב הכוונה לכל בהמה טהורה.","\u0003ו\u0004מקשים: \u0003לילף מיניה\u0004 \u0005[נלמד ממנו,\u0006 מן הכתוב \"גדי העזים\"\u0005],\u0006 שכמו ש\"גדי\" זה הוא גדי עיזים, כך גם \"גדי\" האמור באיסור בשר בחלב הוא גדי עיזים, ושלא כמשנתנו! ומשיבים: אין לומר כן, כיון ש\u0003כתיב קרא אחרינא\u0004 \u0005[נאמר פסוק אחר]\u0006 \u0003\"ואת עורות גדיי העזים\"\u0004 (בראשית כז, טו), ו\u0003כאן\u0004 פירש לנו הכתוב שגדיים אלו היו מן העיזים, ככתוב \u0003\"גדיי העזים\", הא\u0004 \u0005[הרי]\u0006 נלמד מכאן כי \u0003כל מקום\u0004 אחר בתורה \u0003שנאמר\u0004 בו \u0003\"גדי\" סתם\u0004 — \u0003אפילו\u0004 ולד \u0003של\u0004 \u0003פרה ורחל במשמע.\u0004","ושואלים באותו אופן: \u0003ולילף מיניה\u0004 \u0005[ושילמד ממנו,\u0006 מכתוב זה\u0005]\u0006 שכל \"גדי\" האמור בתורה הוא גדי עיזים! ומשיבים: אין לומר כן, כי שני הפסוקים הללו \u0003הוו להו\u0004 \u0005[הרי הם]\u0006 \u0003שני כתובין הבאין כאחד, ו\u0004כלל הוא בדרכי הדרשות \u0003ש\u0004\u0003כל שני כתובים הבאים כאחד\u0004 — \u0003אין מלמדין.\u0004","ושואלים על הסבר זה: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 ששני כתובים הבאים כאחד \u0003אין מלמדין, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי שני כתובים הבאים כאחד \u0003מלמדין, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: בענין זה \u0003תרי מיעוטי כתיבי\u0004 \u0005[שני מיעוטים כתובים]\u0006 בפסוקים הללו, שהרי די היה לכתוב \"גדי \u0003עזים\"\u0004 וכן \"גדיי עזים\", וכתוב \"גדי \u0003העזים\",\u0004 ו\"גדיי העזים\" — להדגיש שרק כאן מדובר בעיזים.","ועוד בדיני בשר בחלב, \u0003אמר שמואל:\u0004 נאמר בתורה באיסור בשר בחלב שלוש פעמים \"לא תבשל גדי בחלב אמו\" (שמות כג, יט. שם לד, כו. דברים יד, כא) וכל אחד מהם בא ללמד: הנאמר בפעם הראשונה \u0003\"גדי\"\u0004 בא \u0003לרבות\u0004 לאיסור גם \u0003את החלב\u0004 שבו, שאם בישלו ואכלו, חייב עליו גם משום בשר בחלב וגם משום חלב. והנאמר בפעם השנית \u0003\"גדי\"\u0004 בא \u0003לרבות\u0004 באיסור בשר בחלב גם \u0003את\u0004 בשר \u0003המתה.\u0004 שאם בישל בשר נבילה בחלב, הוא חייב גם כן על כך. והנאמר בפעם השלישית \u0003\"גדי\"\u0004 בא \u0003לרבות את\u0004 בשר \u0003השליל\u0004 (העובר) שאף הוא בכלל איסור בשר בחלב.","ועוד מוסיף שמואל כי הכתוב בפעם הראשונה \u0003\"גדי\"\u0004 בא \u0003להוציא\u0004 מכלל איסור בשר בחלב \u0003את הדם.\u0004 שאם בישלו בחלב, אינו עובר עליו. והכתוב בפעם השנית \u0003\"גדי\"\u0004 \u0003בא\u0004 \u0003להוציא\u0004 מכלל איסור בשר בחלב \u0003את השליא.\u0004 והכתוב בפעם השלישית \u0003\"גדי\"\u0004 בא \u0003להוציא את\u0004 הבהמה \u0003הטמאה\u0004 מכלל איסור בשר בחלב.","וכן הכתוב בפעם הראשונה \u0003\"בחלב אמו\"\u0004 \u0003בא להורות כי הדברים אמורים רק בחלב של נקבה\u0004 \u0003ולא בחלב\u0004 של \u0003זכר,\u0004 שפעמים שיש לזכר חלב ואין זה נאסר בבשר. והכתוב בפעם השנית \u0003\"בחלב אמו\"\u0004 בא ללמד כי דווקא בחלב של בהמה חיה האיסור, \u0003ולא בחלב\u0004 של בהמה \u0003שחוטה,\u0004 שאינה ראויה עוד להיקרא \"אמו\". וכן הכתוב בפעם השלישית \u0003\"בחלב אמו\"\u0004 בא להשמיענו כי דווקא בחלב בהמה טהורה דבר הכתוב, \u0003ולא בחלב טמאה.\u0004","ותוהים: \u0003הא תלתא\u0004 \u0005[הרי שלושה]\u0006 \u0003\"גדי\" כתיבי\u0004 \u0005[כתובים],\u0006 \u0003ו\u0004אילו \u0003אנן שיתא דרשינן\u0004 \u0005[ואנו שש\u0006 דרשות \u0005אנו דורשים]!\u0006 ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003שמואל\u0004 כי \u0003איסור חל על איסור,\u0004 \u0003ו\u0004מעתה \u0003איסור חלב\u0004 בחלב, \u0003ו\u0004כן איסור \u0003מתה\u0004 בחלב, שניהם \u0003מחד קרא נפקי\u0004 \u0005[ממקרא אחד יוצאים,\u0006 נלמדים\u0005],\u0006 \u0003דם\u0004 שאינו בכלל בשר בחלב \u0003נמי\u0004 \u0005[גם כן]\u0006 אינו צריך לדרשת כתוב מיוחדת, שהרי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003גדי הוא. ו\u0004כמו כן \u0003שליא נמי\u0004 \u0005[גם כן]\u0006 אינה נצרכת לדרשה מיוחדת ללמד שאינה בכלל איסור בשר בחלב, שכן \u0003פירשא בעלמא\u0004 \u0005[פרש סתם]\u0006 \u0003הוא,\u0004 ואינו מן הבשר. הרי ש\u0003פשו להו תרי\u0004 \u0005[נשארו להם שני\u0006 \"גדי\" ללמדנו\u0005],\u0006 \u0003חד\u0004 \u0005[אחד]\u0006 מהם בא \u0003לרבות את השליל, וחד למעוטי\u0004 \u0005[ואחד\u0006 מהם בא \u0005למעט]\u0006 \u0003בהמה טמאה.\u0004","ושואלים על הסבר זה: \u0003ו\u0004כי \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003שמואל\u0004 ש\u0003איסור חל על איסור? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל משום\u0004 \u0005[בשם]\u0006 \u0003ר' אלעזר: מנין לכהן טמא שאכל תרומה טמאה שאינו ב\u0004חיוב \u0003מיתה? ש\u0004כן \u0003נאמר\u0004 באיסור אכילת תרומה טהורה לטמא \u0003\"ומתו בו כי יחללוהו\"\u0004 (ויקרא כב, ט) — שחייבים מיתה על שהתחללה התרומה על ידם, כשאכלוה בטומאתם, \u0003פרט לזו\u0004 התרומה \u0003שמחוללת ועומדת\u0004 קודם שאכלה זה. משמע שאין איסור (אכילת תרומה בזמן שהוא טמא) חל על הדבר האסור (כתרומה זו האסורה באכילה משום טומאה)!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003בעלמא\u0004 \u0005[בכלל]\u0006 סבור שמואל כי \u0003איסור חל על איסור, ו\u0004לענין שיטתו בדין אכילת תרומה טמאה בכהן טמא הוא כי \u0003שאני התם\u0004 \u0005[שונה שם,\u0006 בדין התרומה הטמאה\u0005]\u0006 שאין איסור חל על איסור, משום ש\u0003מיעט רחמנא\u0004 \u0005[הכתוב]\u0006 באומרו \u0003\"ומתו בו\u0004 כי יחללוהו\" — ולא זו שכבר מחוללת ועומדת. \u0003ו\u0004\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 תשובה אחרת: \u0003בעלמא קסבר\u0004 \u0005[בכלל סבור]\u0006 \u0003שמואל\u0004 כי \u0003אין איסור חל על איסור, ו\u0004לענין שיטתו בדין חלב ובשר המתה באיסור בשר בחלב הוא כי \u0003שאני הכא דרבי רחמנא\u0004 \u0005[ושונה כאן\u0006 הדין, כיון \u0005שריבתה התורה]\u0006 \u0003\"גדי\"\u0004 פעם נוספת כדי ללמדנו כן.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר שמואל בדין בשר בחלב באיסור חלב ומתה, הרי זו השיטה \u0003דידיה\u0004 \u0005[שלו עצמו],\u0006 שהוא סבור שאיסור חל על איסור. ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר שמואל בדין אכילת תרומה טמאה בכהן טמא, הרי זו השיטה \u0003דרביה\u0004 \u0005[של רבו,\u0006 ר' אלעזר\u0005]\u0006 הסבור כי אין איסור חל על איסור.","ומביאים עוד בדיני בשר בחלב. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב אחדבוי בר אמי מרב: המבשל בחלב גדי שלא הניקה\u0004 עדיין, כי טרם ילדה עד כה ואינה בגדר \"אמו\", אך היא קרובה ללדת ויש לה חלב, \u0003מהו\u0004 לענין איסור בשר בחלב? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מדאיצטריכא\u0004 \u0005[מ\u0006מה \u0005שהוצרך]\u0006 \u0003שמואל למימר\u0004 \u0005[לומר]\u0006 בדרשת הכתוב \u0003\"בחלב אמו\"\u0004 — \u0003ולא בחלב זכר,\u0004 נדייק מכאן כי דווקא חלב \u0003זכר הוא\u0004 שאינו בכלל איסור בשר בחלב, ומשום שהרי זה חלב של מי ש\u0003לא אתי\u0004 \u0005[יבוא]\u0006 לעולם \u0003לכלל אם. אבל האי\u0004 \u0005[זה]\u0006 החלב של מי שטרם ילדה, אך עומדת ללדת, \u0003כיון\u0004 שבסופו של דבר הריהו \u0003בא\u0004 \u0003לכלל אם\u0004 — הרי הוא \u0003אסור.\u0004","למעלה למדנו בדעתו של שמואל שהמבשל חלב בחלב הריהו בכלל איסור בשר בחלב, ועוד בענין זה \u0003אתמר\u0004 \u0005[נאמר]\u0006 כי \u0003המבשל חלב בחלב, ר' אמי ור' אסי\u0004 נחלקו בדינו, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 ש\u0003לוקה\u0004 משום אכילת בשר בחלב, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 ש\u0003אינו לוקה.\u0004 ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר\u0006 ש\u0005בזה הם חלוקים],\u0006 \u0003דמאן דאמר\u0004 \u0005[שמי שאמר]\u0006 \u0003לוקה, קסבר\u0004 \u0005[סבור הוא]\u0006 כי \u0003איסור חל על איסור, ומאן דאמר\u0004 \u0005[ומי שאמר]\u0006 ש\u0003אינו לוקה, קסבר\u0004 \u0005[סבור הוא]\u0006 כי \u0003אין איסור חל על איסור!\u0004","ודוחים: \u0003לא,\u0004 אפשר לומר כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אין איסור חל על איסור,\u0004 ולכך לענין ללקות על \u0003אכילה\u0004 של חלב שהתבשל בחלב — \u0003דכולי עלמא לא פליגי דלא לקי\u0004 \u0005[הכל אינם חלוקים שאינו לוקה].\u0006 ואולם \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים]\u0006 — הרי זה לענין \u0003בשול\u0004 חלב בחלב. ש\u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 \u0003לוקה\u0004 הרי זה משום ש\u0003חד איסורא\u0004 \u0005[איסור אחד]\u0006 \u0003הוא\u0004 בישול זה, ואין זה ענין לאיסור חל על איסור. \u0003ומאן דאמר\u0004 \u0005[ומי שאמר]\u0006 ש\u0003אינו לוקה\u0004 — \u0003להכי אפקה רחמנא\u0004 \u0005[לכך הוציאה,\u0006 כתבה \u0005התורה]\u0006 \u0003ל\u0004איסור \u0003אכילה\u0004 של בשר בחלב \u0003בלשון בישול\u0004 (ככתוב \"לא תבשל גדי בחלב אמו\", והרי בכלל הכתוב איסור אכילה),"],["\u0003כיון\u0004 ש\u0003על אכילה\u0004 של חלב שהתבשל בחלב \u0003לא לקי\u0004 \u0005[אינו לוקה]\u0006 משום איסור בשר בחלב (שהרי אין איסור בשר בחלב חל על איסור חלב), אף על ה\u0003בישול\u0004 של חלב בחלב \u0003נמי לא לקי\u0004 \u0005[גם כן אינו לוקה].\u0006","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 בהסבר דעותיהם של ר' אמי ור' אסי להיפך: על ה\u0003בישול\u0004 של חלב בחלב — \u0003כולי עלמא לא פליגי דלקי\u0004 \u0005[הכל אינם חלוקים שלוקה],\u0006 שהרי יש כאן רק איסור בישול אחד, של בשר בחלב (שכן החלב אינו אסור בבישול), \u0003כי פליגי\u0004 \u0005[כאשר\u0006 הם \u0005חלוקים]\u0006 על \u0003ה\u0004\u0003אכילה\u0004 אם לוקים עליה משום איסור אכילת בשר בחלב, ובכך נחלקו: \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 ש\u0003אינו לוקה,\u0004 טעמו \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אין איסור חל על איסור,\u0004 וכבר אסור הדבר משום חלב. \u0003ו\u0004אילו \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 ש\u0003לוקה,\u0004 סבור כי \u0003להכי אפקה רחמנא\u0004 \u0005[לכך הוציאה,\u0006 כתבה \u0005התורה]\u0006 \u0003ל\u0004איסור \u0003אכילה\u0004 של בשר בחלב דווקא \u0003בלשון בישול\u0004 (\"לא תבשל גדי בחלב אמו\". שמות כג, יט; שם לד, כו; דברים יד, כא), להשמיענו כי \u0003כיון\u0004 שעל ה\u0003בישול\u0004 באופן מסויים של בשר בחלב (וכגון זה שלפנינו במבשל חלב בחלב) הוא \u0003לקי\u0004 \u0005[לוקה],\u0006 על ה\u0003אכילה\u0004 של אותו דבר \u0003נמי לקי\u0004 \u0005[גם כן לוקה].\u0006","\u0003ו\u0004מציעים דרך שלישית להבנת דעותיהם של ר' אמי ור' אסי, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כי \u0003מר\u0004 \u0005[חכם זה]\u0006 \u0003אמר\u0004 הלכה \u0003חדא\u0004 \u0005[אחת]\u0006 העוסקת במקרה מסויים, \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003אמר\u0004 הלכה \u0003חדא\u0004 \u0005[אחת]\u0006 העוסקת במקרה אחר, \u0003ולא פליגי\u0004 \u0005[ואינם חלוקים]\u0006 זה על זה. שזה שאמר שלוקים על חלב שהתבשל בחלב דיבר על הבישול, ואילו זה שאמר שאין לוקים דיבר על האכילה. שלדעת הכל אין איסור חל על איסור, ולכך אין איסור בשר בחלב חל על איסור חלב.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו כי \u0003המבשל\u0004 בשר \u0003במי חלב\u0004 (המים הנשארים מהחלב לאחר שנחמץ ונעשה גבינה) — \u0003פטור\u0004 ממלקות, שאין אלה נחשבים כחלב לענין איסור בשר בחלב. וכן \u0003דם שבשלו בחלב\u0004 — \u0003פטור,\u0004 שאין הדם נחשב כבשר לענין איסור בשר בחלב. ובדומה לכך \u0003העצמות והגידים והקרנים והטלפים שבשלן בחלב\u0004 — \u0003פטור.\u0004","ואולם \u0003הפגול\u0004 (בשר קרבן שהתפגל, וכגון ששחטוהו על מנת לזרוק את דמו או לאכול מבשרו או להקטיר את אימוריו מחוץ לזמנו הראוי), \u0003ו\u0004הן \u0003הנותר\u0004 (מבשר הקרבן לאחר זמן אכילתו הראוי), \u0003ו\u0004כן הקרבן \u0003הטמא,\u0004 שכל אלה אסורים באכילה, \u0003שבשלן בחלב\u0004 — חל עליהם איסור בשר בחלב, ולכך \u0003חייב\u0004 מלקות אף משום בשר בחלב. הרי רואים אנו כי איסור בשר בחלב חל על איסור פיגול נותר וטמא, שכך מלמדנו הריבוי של המלה \"גדי\" (כמובא בעמוד הקודם בדברי שמואל). אם כן מעתה נאמר שכך הוא גם באיסור חלב, ושלא כדברי ר' אמי ור' אסי!","ומשיבים: אין הלכה זו שבברייתא מתבססת על דרשת \"גדי\", אלא \u0003האי תנא סבר\u0004 \u0005[התנא זה סבור]\u0006 ש\u0003איסור חל על איסור,\u0004 ולכן לדעתו חל איסור \u0003בשר בחלב על איסור פיגול ונותר, ולשיטתו גם יחול איסור בשר בחלב, על איסור חלב. ואילו הם סבורים כי אין איסור חל על איסור. ואין בדבר זה משום מחלוקתם של אמוראים כנגד תנאים, שכן הרבה מן התנאים סבורים כי אין איסור חל על איסור.\u0004","למעלה הובאו בתוך דברי הברייתא כי \u0003המבשל\u0004 בשר \u0003במי חלב פטור\u0004 ממלקות. ומעירים: הרי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003ל\u0004שיטת \u0003ריש לקיש, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה לענין המשקים המכשירים את האוכלים לקבל טומאה, שבכללם החלב והשמן: \u0003מי חלב הרי הן כחלב, והמוחל\u0004 (המוהל, המיץ) היוצא מן הזיתים \u0003הרי הוא כשמן.\u0004 ועל כך \u0003אמר ריש לקיש\u0004 כי \u0003לא שנו\u0004 שמי חלב נחשבים כחלב \u0003אלא\u0004 לענין \u0003להכשיר את הזרעים\u0004 (או שאר דברי מאכל), \u0003אבל לענין בישול בשר בחלב\u0004 — \u0003מי חלב אינו כחלב.\u0004","ומביאים עוד בהגדרת ה\"חלב\" האמור באיסור בשר בחלב. \u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]\u0006 על הכתוב \"לא תבשל גדי בחלב אמו\": מן המלים \"גדי \u0003בחלב אמו\"\u0004 — \u0003אין לי\u0004 איסור \u0003בשר בחלב\u0004 \u0003אלא\u0004 רק בשר גדי המתבשל \u0003בחלב אמו\u0004 (היא העז), בשר גדי המתבשל \u0003בחלב פרה ורחל מנין\u0004 לנו שאף הוא אסור?","\u0003אמרת, קל וחומר\u0004 הוא, ובאופן זה: \u0003ומה אמו,\u0004 שקלה היא בדין ביחס לגדי, \u0003ש\u0004הרי \u0003לא נאסרה עמו בהרבעה,\u0004 שכן מותר להכליא מין במינו — \u0003נאסרה עמו בבשולו\u0004 כמפורש בתורה. \u0003פרה ורחל, ש\u0004חמורות הן, \u0003ש\u0004הרי \u0003נאסרו עמו בהרבעה,\u0004 שהוא מין בשאינו מינו — \u0003אינו דין שנאסרו עמו בבשולו!\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בפסוק נוסף \"לא תבשל גדי \u0003בחלב אמו\"\u0004 — לרבות \u0003אף את אלה.\u0004","ותוהים על הדברים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003למה לי קרא\u0004 \u0005[פסוק]\u0006 ללמדנו כן? \u0003הא אתיא ליה\u0004 \u0005[הרי\u0006 כבר \u0005באה,\u0006 נלמדה \u0005לו\u0006 ההלכה\u0005]\u0006 מהקל וחומר המובא לפני כן!","\u0003אמר רב אשי\u0004 בתשובה: עדיין נצרכים אנו לדרשה זו, \u0003משום דאיכא למימר\u0004 \u0005[שיש מקום לומר]\u0006 כנגד הקל וחומר כי \u0003מעיקרא דדינא פירכא\u0004 \u0005[מעיקרו של הדין,\u0006 הקל וחומר, \u0005יש\u0006 עליו \u0005פירכה],\u0006 \u0003מהיכא קא מייתית לה\u0004 \u0005[מהיכן אתה מביא,\u0006 משתית \u0005אותה,\u0006 את הקל וחומר\u0005]?\u0006 \u0003מאמו,\u0004 שקלה היא בדין ביחס לגדי, ואולם ניתן לדחות ולומר באופן הפוך: \u0003מה לאמו\u0004 — שחמורה היא בדין ביחס לגדי, \u0003שכן נאסרה עמו בשחיטה,\u0004 שאסור לשחוט את שניהם באותו יום (ככתוב \"ושור או שה אותו ואת בנו לא תשחטו ביום אחד\". ויקרא כב, יח), \u0003תאמר בפרה ש\u0004היא קלה בדין ביחס לגדי, שהרי \u0003לא נאסרה עמו בשחיטה\u0004 ביום אחד! לכך \u0003תלמוד לומר \"בחלב אמו\".\u0004","למעלה הובאה ברייתא שעניינה בדרשת שני הכתובים \"בחלב אמו\", ועתה מביאים עוד ברייתא שעניינה דרשת הכתוב \"בחלב אמו\" השלישי. \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 הכתוב \u0003\"בחלב אמו\",\u0004 מה בא ללמדנו — שהיה מקום לומר כי \u0003אין לי\u0004 באיסור בשר בחלב \u0003אלא\u0004 הבשר המתבשל \u0003בחלב אמו\u0004 הצעירה, זו שילדה את בנה בשנה זו, ועדיין לא נכנסה לדיר לצורך לקיחת מעשר בהמה. ואולם איסור בשר בחלב \u0003בחלב אחותו גדולה\u0004 (כלומר, זו שכבר נכנסה לדיר לצורך מעשר בהמה) \u0003מנין\u0004 לנו?","ומשיבים: \u0003אמרת\u0004 כי נלמד הדבר ממידת \u0003קל וחומר, ו\u0004באופן זה, \u0003מה אמו\u0004 הקלה בדין ביחסה לגדי, \u0003ש\u0004הרי היא \u0003נכנסה עמו לדיר להתעשר\u0004 (שלא נתעשרה כבר) — \u0003נאסרה עמו בבשול, אחותו\u0004 החמורה בדין, ביחסה לגדי, \u0003ש\u0004הרי היא \u0003לא נכנסה עמו לדיר להתעשר\u0004 (כיון שהיא כבר היתה בכלל זה, ושוב אין היא חוזרת ומתעשרת) — \u0003אינו דין שנאסרה עמו בבשול!\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"בחלב אמו\",\u0004 שאף זו בכלל איסור בשר בחלב.","ותוהים: \u0003והא\u0004 \u0005[והרי]\u0006 כבר נלמדה הלכה זו מקל וחומר, ו\u0003למה לי קרא\u0004 \u0005[מקרא]\u0006 לזה, \u0003הא אתיא ליה\u0004 \u0005[הרי\u0006 כבר \u0005באה,\u0006 נלמדה \u0005לה\u0006 ההלכה מקל וחומר\u0005]!\u0006 \u0003אמר רב אשי\u0004 בתשובה: נצרכים אנו לדרשת הכתוב, ואין הקל וחומר מלמדנו זאת, \u0003משום דאיכא למימר\u0004 \u0005[שיש מקום לומר]\u0006 כי \u0003מעיקרא דדינא פירכא\u0004 \u0005[מעיקרו של הדין,\u0006 קל וחומר, יש עליו \u0005פירכה],\u0006 שהרי \u0003מהיכא קא מייתית לה\u0004 \u0005[מהיכן אתה מביא,\u0006 מוכיח \u0005אותה,\u0006 את הקל וחומר\u0005]?\u0006 \u0003מ\"אמו\"\u0004 שאתה מניח שהיא קלה בדינה ביחס לגדי, ואולם יש לומר את הדברים באופן שונה: \u0003מה לאמו\u0004 שחמורה היא ביחס לגדי, \u0003שכן נאסרה עמו בשחיטה\u0004 ביום אחד, \u0003תאמר באחותו גדולה\u0004 שקלה היא ביחס לגדי, \u0003ש\u0004הרי \u0003לא נאסרה עמו בשחיטה\u0004 ביום אחד! לכך \u0003תלמוד לומר \"בחלב אמו\".\u0004","ודנים עוד בדבר: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא ש\u0003אחותו גדולה\u0004 (שכבר התעשרה) היא בכלל איסור בשר בחלב, ואולם \u0003אחותו קטנה\u0004 (שעדיין לא התעשרה) \u0003מנין\u0004 לנו שאף היא בכלל איסור זה? ומשיבים: \u0003אתיא מביניא\u0004 \u0005[באה,\u0006 נלמדת היא \u0005מביניהם,\u0006 משתיהן, אמו ואחותו הגדולה\u0005].\u0006","ומבררים: \u0003מהי תיתי\u0004 \u0005[ממי\u0006 היא \u0005תבוא,\u0006 תילמד\u0005]?\u0006 אם \u0003תיתי\u0004 \u0005[תבוא]\u0006 \u0003מאמו\u0004 — יש להקשות על ההשוואה: \u0003מה לאמו\u0004 שיש בה צד חומרה, \u0003שכן נאסרה עמו בשחיטה,\u0004 מה שאין כן באחותו קטנה! ואולם אפשר לדחות כי \u0003אחותו גדולה תוכיח,\u0004 שאף שאין בה חומרה, שהרי זו לא נאסרה עמו בשחיטה ביום אחד, בכל זאת היא בכלל בשר בחלב. אף על ההשוואה לאחותו הגדולה יש להקשות: \u0003מה לאחותו גדולה\u0004 שיש בה צד חומרה, \u0003ש\u0004הרי \u0003לא נכנסה עמו לדיר להתעשר,\u0004 תאמר באחותו קטנה שנכנסת עמו לדיר! ואולם אפשר לדחות כי \u0003אמו תוכיח,\u0004 שאין בה צד חומרה זו, ובכל זאת היא בכלל איסור בשר בחלב.","\u0003ו\u0004מעתה \u0003חזר\u0004 (סובב) \u0003הדין\u0004 (דרך הלימוד) מצד לצד, ויש לסכמו כי אמנם \u0003לא ראי זה כראי זה, ולא ראי זה כראי זה,\u0004 שאין הם דומים זה לזה, כי בכל אחד מהם יש צד חומרה שאין באחר. ואולם \u0003הצד השוה שבהן: שהוא בשר, ו\u0004הריהו \u0003אסור לבשל בחלב. אף אני אביא\u0004 (אוסיף) \u0003בשר\u0004 \u0003אחותו קטנה, ש\u0004גם \u0003הוא בשר, ו\u0004יהיה גם הוא \u0003אסור לבשל בחלב.\u0004","ואומרים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא דרך הלימוד לענין אחותו קטנה, מעתה \u0003אחותו גדולה נמי תיתי מביניא\u0004 \u0005[גם כן תבוא מביניהן,\u0006 מאמו ופרה שהן בכלל איסור זה, כנלמד למעלה\u0005],\u0006 ואין צורך בלימוד מיוחד מן הכתוב לעניינה!","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כך הוא גם כן].\u0006 ושואלים: אם כן \u0003אלא \"בחלב אמו\"\u0004 הכתוב פעם נוספת \u0003למה לי?\u0004 ומשיבים: \u0003מבעי ליה לכדתניא\u0004 \u0005[נצרכה לו לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 מן הכתוב \u0003\"בחלב אמו\"\u0004 — \u0003אין לי\u0004 לאסור \u0003אלא\u0004 את הגדי בבישול \u0003בחלב אמו,\u0004"],["ואולם \u0003היא\u0004 (האם) \u0003עצמה\u0004 שנשחטה לענין בישול בשרה \u0003בחלבה\u0004 (שיצא ממנה בעודה בחיים) \u0003מנין\u0004 לנו שאסור הדבר? \u0003אמרת\u0004 כי נלמד הדבר מ\u0003קל וחומר,\u0004 ובאופן זה: \u0003ומה במקום\u0004 (בענין) איסור שחיטה ביום אחד, \u0003שלא נאסר פרי\u0004 (תולדת) האם, הוא בנה, \u0003עם פרי,\u0004 וולד אחר שלה, \u0003בשחיטה.\u0004 שהרי מותר לשחוט שני בנים של אותה בהמה ביום אחד — \u0003נאסר פרי עם האם בשחיטה\u0004 ביום אחד. \u0003מקום\u0004 (בענין) איסור בשר בחלב, \u0003שנאסר פרי עם פרי בבשול,\u0004 שהרי נאסר הגדי (שהוא \"פרי\") בבישול בחלב (שגם הוא \"פרי\") — \u0003אינו דין שנאסר פרי\u0004 (חלב האם) \u0003עם\u0004 בשר \u0003האם בבשול!\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"בחלב אמו\"\u0004 שאף בשר האם אסור בבישול עם חלבה של האם.","ותוהים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למה לי קרא\u0004 \u0005[פסוק]\u0006 ללמדנו כן, \u0003הא אתיא לה\u0004 \u0005[הרי\u0006 כבר \u0005באה,\u0006 נלמדה \u0005לה\u0006 הלכה זו מקל וחומר\u0005]!\u0006 \u0003אמר רב אחדבוי בר אמי\u0004 בתשובה: אין זה קל וחומר גמור, \u0003משום דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]:\u0006 \u0003סוס\u0004 שהוא \u0003בן\u0004 סוס ו\u0003סוסיא\u0004 \u0005[סוסה]\u0006 שהוא \u0003אחי פרדה\u0004 שאמו הסוסה המליטה אותה לאחר שהתעברה מחמור), \u0003יוכיח\u0004 שלא כקל וחומר זה. \u0003ש\u0004הרי במקרה זה \u0003אסור פרי עם פרי,\u0004 שאסור הסוס בפרדה, אף שהם אח ואחות, ושניהם פרי של אימם הסוסה, \u0003ו\u0004בכל זאת \u0003מותר פרי עם האם,\u0004 שכן מותרת הרבעתו של סוס עם אמו!","ודוחים: אין זו פירכה, שכן סיבת הדבר \u0003התם\u0004 \u0005[שם]\u0006 שאסור להרביע את הסוס עם אחותו הפרדה, הינה משום ש\u0003זרע האב הוא דקא גרים\u0004 \u0005[שהוא גורם]\u0006 את זהותו של הנולד, וסיבת הדבר שהסוס הזה אסור בפרדה זו הינה משום שהיא בת מין אחר (חמור), ומה שהוא מותר באמו הסוסה הוא משום שהיא בת מינו. ואין זה ענין ל\"פרי ופרי\".","וראיה לדבר: \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003פרד בן\u0004 חמור ו\u0003סוסיא\u0004 \u0005[סוסה],\u0006 שהוא \u0003אחי פרדה,\u0004 שהיתה לה לסוסה עוד בת מן החמור, \u0003יוכיח, שמותר פרי עם פרי, ואסור פרי עם האם.\u0004 הרי זה מורה שאיסור ההרבעה אינו אלא במינים שונים (הנקבעים על פי זרע האב), ולא משום \"פרי ופרי\".","\u0003אלא אמר מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא\u0004 טעם הדבר שאין הקל וחומר מלמדנו לענין בישול בשר בחלב של האם בחלבה שלה, הוא \u0003משום דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 פירכה זו: \u0003עבד בן שפחה\u0004 שהוא \u0003אחי\u0004 של שפחה \u0003משוחררת יוכיח. ש\u0004הרי עבד זה \u0003אסור\u0004 לבוא על אחותו המשוחררת, שהם \u0003פרי עם פרי, ו\u0004בכל זאת הריהו \u0003מותר\u0004 לבוא על אמו השפחה, שהם \u0003פרי עם האם!\u0004","ודוחים: אין זו פירכה, שכן \u0003התם\u0004 \u0005[שם]\u0006 האיסור של העבד באחותו המשוחררת אינו משום \"פרי ופרי\" אלא משום ש\u0003גט שיחרור הוא דקא גרים\u0004 \u0005[שהוא גורם]\u0006 את האיסור. וראיה לדבר, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003עבד בן\u0004 שפחה \u0003משוחררת,\u0004 שהוא \u0003אחי שפחה יוכיח, ש\u0004במקרה זה \u0003מותר פרי עם פרי\u0004 (שכן יכול העבד לבוא על אחותו, כיון ששניהם אינם משוחררים), \u0003ו\u0004אולם \u0003אסור פרי עם האם\u0004 (שאין העבד יכול לבוא על אמו, שהינה עתה יהודיה).","\u0003אלא אמר רב אידי בר אבין:\u0004 טעם הדבר שאין הקל וחומר מלמדנו לענין בישול בשר בחלבה של האם, הוא \u0003משום דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 כי \u0003כלאי זרעים\u0004 (שאסורים בזריעה מינים שונים זה עם זה\u0003)\u0004 \u0003יוכיחו, ש\u0004כן \u0003אסור\u0004 בזריעה \u0003פרי\u0004 של מין זה \u0003עם פרי\u0004 של מין זה, \u0003ומותר\u0004 לזרוע כל \u0003פרי עם האם\u0004 (היא הקרקע, שממנה באו כל הפירות)! ודוחים: אין זו פירכה על הקל וחומר, שכן אין זה ענין ל\"פרי ופרי\", שהרי \u0003כלום\u0004 (האם) \u0003נאסר פרי עם פרי\u0004 כשלעצמם, והלא לא נאסרו זה עם זה \u0003אלא על ידי האם,\u0004 שלא נאסר אלא לזורעם יחד בקרקע. וראיה לדבר, \u0003דהא חיטי ושערי בכדא\u0004 \u0005[חיטים ושעורים\u0006 הנתונות \u0005בכד\u0006 אחד\u0005]\u0006 בלא זריעה \u0003ולא מיתסרו\u0004 \u0005[ואינן נאסרות]\u0006 בכך.","\u0003אלא אמר רב אשי:\u0004 טעם הדבר שאין הקל וחומר מלמדנו לענין בישול בשר בחלבה, הוא \u0003משום דאיכא למימר\u0004 \u0005[שיש\u0006 מקום לדחות ו\u0005לומר]:\u0006 \u0003מה לפרי עם פרי,\u0004 כגדי הנולד לאם זו ולחלב היוצא ממנה, שאסורים בבישול — \u0003שכן שני גופים\u0004 נפרדים הם, שמעולם לא היו דבר אחד. \u0003תאמר בפרי עם האם,\u0004 כבשר האם וחלבה שיצא ממנה — \u0003שכן\u0004 היו שניהם \u0003גוף אחד.\u0004 ונדחה בכך הקל וחומר, ו\u0003משום הכי איצטריך קרא\u0004 \u0005[כך הוצרך הפסוק]\u0006 ללמדנו שבכלל איסור בשר בחלב אף אם וחלבה שלה.","ובעיקרו של איסור אכילת בשר בחלב \u0003אמר רב אשי: מנין לבשר בחלב ש\u0004הוא \u0003אסור באכילה,\u0004 שהרי בתורה לא נאמר אלא \"לא תבשל גדי בחלב אמו\" — \u0003ש\u0004כן \u0003נאמר \"לא תאכל כל תועבה\"\u0004 (דברים יד, ג) — לומר לך \u0003כי\u0004 \u0003כל\u0004 דבר \u0003שתעבתי לך\u0004 בעשייתו \u0003הרי הוא ב\"בל תאכל\".\u0004","\u0003ואין לי\u0004 מדרשת כתוב זה \u0003אלא\u0004 שבשר וחלב אסור \u0003באכילה,\u0004 שאסור הוא אף \u0003בהנאה מנין\u0004 לי? \u0003כ\u0004דברי \u0003ר' אבהו,\u0004 שכן \u0003אמר ר' אבהו, אמר ר' אלעזר: כל מקום שנאמר\u0004 בתורה \u0003\"לא יאכל\"\u0004 או \u0003\"לא תאכל\"\u0004 או \u0003\"לא תאכלו\"\u0004 — \u0003אחד\u0004 (בין) \u0003איסור אכילה ואחד\u0004 (ובין) \u0003איסור הנאה במשמע, עד שיפרוט\u0004 (שיפרש) \u0003לך הכתוב\u0004 שאין זה אסור אלא באכילה ולא בהנאה. \u0003כדרך שפרט לך ב\u0004איסור \u0003נבלה,\u0004 שאסורה באכילה ומותרת בהנאה, שכן אמרה התורה ש\u0003לגר\u0004 תושב ניתנת הנבילה \u0003בנתינה\u0004 (במתנה), \u0003ו\u0004אילו \u0003לגוי\u0004 היא ניתנת \u0003במכירה\u0004 (תמורת תשלום), ואין בה איסור הנאה, אף שנאמר בה הלשון \"לא תאכלו\".","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 ממה שנאמר בנבילה \u0003\"לא תאכלו כל נבלה לגר אשר בשעריך תתננה ואכלה או מכור לנכרי\"\u0004 (שם שם, כא) — \u0003אין לי\u0004 מפסוק זה \u0003אלא\u0004 שמותר לתיתה \u0003לגר ב\u0004דרך של \u0003נתינה, ולגוי ב\u0004דרך של \u0003מכירה.\u0004 אבל שמותר לתיתה \u0003לגר\u0004 גם \u0003ב\u0004דרך של \u0003מכירה מנין\u0004 לי? לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בפסוק \u0003\"לגר... תתננה... או מכור\",\u0004 שמתייחסות המלים \"או מכור\" גם לגר. וכמו כן, שמותר לתיתה","\u0003לגוי ב\u0004דרך של \u0003נתינה מנין\u0004 לי? לכך \u0003תלמוד לומר\u0004 \u0003\"תתננה... או מכור לנכרי\",\u0004 שמתייחסת המלה \"תתננה\" אף לגוי. \u0003נמצא\u0004 איפוא כי \u0003אחד גר ואחד גוי\u0004 — \u0003בין במכירה בין בנתינה\u0004 של הנבילה. אלו \u0003דברי ר' מאיר.\u0004 ואילו \u0003ר' יהודה אומר\u0004 כי יש לקיים את ה\u0003דברים ככתבן,\u0004 ולכן ניתנת הנבילה \u0003לגר\u0004 רק \u0003ב\u0004דרך \u0003נתינה, ו\u0004אילו \u0003לגוי\u0004 היא ניתנת רק \u0003ב\u0004דרך \u0003מכירה.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה?\u0004 ומסבירים: \u0003אי סלקא דעתך כדקאמר\u0004 \u0005[אם עולה על דעתך\u0006 לומר בפירוש הפסוק \u0005כמו שאומר]\u0006 \u0003ר' מאיר\u0004 — \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"לא תאכלו כל נבלה לגר אשר בשעריך תתננה ואכלה ומכור\u0004 לנכרי\", שבכך הושוו הנתינה והמכירה והושוו הגר והגוי, וכשיטת ר' מאיר, ומעתה המלה \u0003\"או\"\u0004 שבפסוק \u0003למה לי,\u0004 שהרי הכל שווים בכל? אלא \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003לדברים ככתבן הוא דאתא\u0004 \u0005[שבא]\u0006 הכתוב, שבאה המלה \"או\" לחלק בין הנתינה למכירה, ובין הגר לגוי, שתהא הנבילה ניתנת \u0003לגר\u0004 רק \u0003ב\u0004דרך \u0003נתינה, ולגוי\u0004 רק \u0003ב\u0004דרך \u0003מכירה.\u0004","\u0003ור' מאיר אמר לך\u0004 \u0005[היה אומר לך]\u0006 בתשובה לדברים: אף שאכן אפשר גם לתת וגם למכור, הן לגר והן לגוי, את הנבילה, \u0003האי\u0004 \u0005[זו]\u0006 המלה \u0003\"או\"\u0004 הכתובה בפסוק באה ללמדנו שיש \u0003להקדים\u0004 (להעדיף) את ה\u0003נתינה\u0004 של הנבילה ל\u0003גר\u0004 \u0003למכירה\u0004 של הנבילה ל\u0003גוי.\u0004 ושואלים לצד האחר: \u0003ור' יהודה\u0004 הסבור כי המלה \"או\" באה לחלק בין נתינה למכירה ובין גר לגוי, מנין לו הלכה זו שיש להעדיף את הנתינה לגר על פני המכירה לגוי? ומשיבים: לדעת ר' יהודה דין זה שיש \u0003להקדים\u0004 את ה\u0003נתינה\u0004 ל\u0003גר למכירה\u0004 ל\u0003גוי לא צריך קרא\u0004 \u0005[אין צריך מקרא]\u0006 ללמדנו זאת, כי \u0003סברא הוא\u0004 שיש בכך: \u0003זה\u0004 הגר, \u0003אתה מצווה להחיותו\u0004 (לדאוג למחייתו), \u0003וזה\u0004 הנכרי, \u0003אי\u0004 (אין) \u0003אתה מצווה להחיותו.\u0004 ומכאן ברור שיש להעדיף בנתינת הנבילה את הגר על פני הגוי.","למעלה הובאו דברי רב אשי כי כל דבר שתעבתי לך הריהו באיסור אכילה. ודנים בענין זה, ובתחילה מביאים \u0003(סימן\u0004 לעניינים שיידונו במהלך הסוגיה: \u0003שבת, חורש, וכלאי זרעים, אותו ואת בנו, ושילוח הקן).\u0004","ושואלים: \u0003אלא מעתה,\u0004 לפי שיטה זו שכל דבר שנאסר בעשיה (\"תעבתי לך\") הריהו אסור באכילה,"],["מעתה גם \u0003מעשה שבת\u0004 (הדברים הנעשים בחילול שבת, וכגון שהתבשלו בשבת), \u0003ליתסרו\u0004 \u0005[שייאסרו]\u0006 לאכילה המאכלים שהתבשלו בשבת, ולא רק לזה שבישל (במזיד), \u0003דהא\u0004 \u0005[שהרי]\u0006 בכלל \"כל ש\u0003תיעבתי לך\" הוא,\u0004 והרי זה שלא כדברי רב אשי!","ומשיבים: אין מעשה שבת בכלל \"כל שתיעבתי לך הריהו בבל תאכל\", שכן בענין השבת \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כי קדש היא לכם\"\u0004 (שמות לא, יד) — והרי זה לשון מיעוט: דווקא השבת עצמה \u0003היא קדש, ואין מעשיה\u0004 נעשים \u0003קדש\u0004 לענין שייאסרו באכילה לכול.","ומקשים עוד מדינו של ה\u0003חורש בשור ובחמור\u0004 (ועבר על הכתוב \"לא תחרוש בשור ובחמור יחדיו\", דברים כב, י), \u0003ו\u0004כן מדינו של ה\u0003חוסם פי פרה ודש בה\u0004 (ועבר על הנאמר בתורה \"לא תחסום שור בדישו\". שם כה, ד) \u0003ליתסרו\u0004 \u0005[שייאסרו]\u0006 הזרעים והדישה באכילה ובהנאה, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003\"תיעבתי לך\" הוא!\u0004","ומשיבים: אין זו קושיה, שכן \u0003השתא\u0004 \u0005[עכשיו]\u0006 שלמדנו כי מעשה שבת אינם אסורים באכילה לכול, אפשר ללמוד מקל וחומר מענין מעשה שבת לענין חסימה וחרישה: \u0003ומה שבת, דחמירא\u0004 \u0005[ש\u0006היא \u0005חמורה]\u0006 מאיסור חסימה ומאיסור חרישה בשור וחמור, בכל זאת \u0003מעשיה מותרים. הני\u0004 \u0005[אלה,\u0006 חרישה וחסימה\u0005],\u0006 שקלים הם ממעשה שבת, \u0003לא כל שכן\u0004 שהם מותרים!","ושואלים עוד על שיטת רב אשי: \u0003כלאי זרעים ליתסרו\u0004 \u0005[שייאסרו],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 בכלל \u0003\"תיעבתי לך\" הוא!\u0004 ומשיבים: אין לומר כן, כי \u0003מדגלי רחמנא\u0004 \u0005[מכיון שגילתה התורה]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003כלאי הכרם\u0004 \"לא תזרע כרמך כלאים פן תקדש המלאה הזרע אשר תזרע ותבואת הכרם\" (דברים כב, ט). והלשון \u0003\"פן תקדש\"\u0004 מובנה: \u0003פן תוקד אש,\u0004 שצריך לשרוף את הכל, כיון שהדבר הגדל הריהו אסור בהנאה. והדברים נאמרו דווקא באיסור כלאי הכרם, \u0003מכלל\u0004 זה אתה למד ש\u0003כלאי זרעים שרו\u0004 \u0005[מותרים].\u0006","ומקשים על הסבר זה, \u0003ואימא\u0004 \u0005[ואמור]\u0006 באופן שונה: \u0003כלאי כרם אסורין בין באכילה בין בהנאה,\u0004 ואילו \u0003כלאי זרעים באכילה אסירי\u0004 \u0005[אסורים],\u0006 \u0003בהנאה שרו\u0004 \u0005[מותרים]!\u0006 ומשיבים: אין לומר כי כלאי זרעים יהיו אסורים באכילה, שכן \u0003איתקוש\u0004 \u0005[הוקשו]\u0006 \u0003לכלאי בהמה. דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בכתוב אחד \u0003\"בהמתך לא תרביע כלאים שדך לא תזרע כלאים\"\u0004 (ויקרא יט, יט), להורות: \u0003מה\u0004 בהרבעת כלאיים ב\u0003בהמתך\u0004 — \u0003היוצא\u0004 (הוולדות שנולדו) \u0003ממנה\u0004 (מהרבעה אסורה זו) הריהי \u0003מותרת. אף שדך\u0004 שנזרעו בו כלאי זרעים — \u0003היוצא ממנו מותר.\u0004","ומבררים: \u0003וכלאי בהמה גופייהו מנא לן\u0004 \u0005[עצמם מנין לנו]\u0006 שוולדותיהם מותרים? ומשיבים: \u0003מדאסר רחמנא\u0004 \u0005[מכיון שאסרה התורה]\u0006 ולד הנולד מ\u0003כלאים ל\u0004צרכי \u0003גבוה\u0004 (בית המקדש, שהריהם אסורים בהקרבה) — \u0003מכלל\u0004 שלצרכי \u0003להדיוט,\u0004 כאכילה, \u0003שרי\u0004 \u0005[מותרים]\u0006 הוולדות הנולדים מכלאי בהמה.","ועוד שואלים על שיטת רב אשי: אלא מעתה, \u0003אותו ואת בנו\u0004 ששחטם ביום אחד \u0003ליתסר\u0004 \u0005[שייאסרו]\u0006 משום \"כל שתיעבתי לך\"! ומשיבים: אין לומר כן, כי \u0003מדאסר רחמנא\u0004 \u0005[מכיון שאסרה התורה]\u0006 \u0003מחוסר זמן\u0004 (קרבן שעדיין אינו בן שמונה ימים) \u0003לגבוה\u0004 (להקרבה במקדש), \u0003מכלל\u0004 הדברים נלמד ש\u0003ל\u0004צורך \u0003הדיוט שרי\u0004 \u0005[מותר],\u0006 ובכלל זה גם הנשחט ביום אחד עם אמו, שהרי אף הוא מחוסר זמן (שכן אם היה שוחט את הבן ביום המחרת — אין כל איסור בדבר. ומעתה שנשחט היום, הריהו \"מחוסר זמן\", שלא המתינו בשחיטתו ליום המחרת).","ועוד שואלים על שיטת רב אשי: אלא מעתה, זה שנטל ציפור מעל בניה, ועבר בכך על איסור התורה, ככתוב במצות \u0003שילוח הקן\u0004 \"לא תקח האם על הבנים\" (דברים כב, ו). ובאה לפני בית דין והורו לו לשלח את הציפור, \u0003ליתסר\u0004 \u0005[שתיאסר]\u0006 הציפור לכול, שהרי נעברה בה עבירה, ובכלל \"כל שתיעבתי לך\" היא! ומשיבים: אין לומר שתהא הציפור אסורה לכל המוצא אותה, שהרי \u0003לא אמרה תורה שלח\u0004 באופן שיכול הדבר להביא \u0003לתקלה,\u0004 אלא בוודאי אין בזה איסור.","למעלה הובאו דברי רב אשי באשר למקור איסור אכילה בבשר בחלב, ובענין זה \u0003אמר ריש לקיש: מנין לבשר בחלב שאסור? תלמוד לומר\u0004 (מלמדנו הנאמר) בקרבן פסח \u0003\"אל תאכלו ממנו נא ובשל מבושל\"\u0004 (שמות יב, ט), \u0003ש\u0004כן יש לשאול: \u0003אין תלמוד לומר\u0004 (מלמדנו הנאמר) \u0003\"מבושל\"\u0004 דבר חדש, שהרי כבר נאמר \"ובשל\". ואם כן, \u0003מה תלמוד לומר \"מבושל\"\u0004 — \u0003לומר לך\u0004 כי \u0003יש לך בשול אחר שהוא כזה,\u0004 שגם הוא אסור, \u0003ואי זה\u0004 — \u0003זה בשר בחלב.\u0004","\u0003אמר לו ר' יוחנן\u0004 לריש לקיש בתמיהה:"],["וכי \u0003כעורה\u0004 היא משנה \u0003זו ששנה\u0004 אותה \u0003רבי\u0004 (ר' יהודה הנשיא) לענין המקור בתורה לאיסור בשר בחלב, שאתה צריך להמציא ראיה נוספת?! שכך שנה: נאמר בתורה בפרשיה שעניינה פסולי המוקדשים שנפדו ויצאו לחולין, איסור אכילת דם \u0003\"לא תאכלנו\u0004 \u0003על הארץ תשפכנו כמים\" (דברים יב, כד), ושב הכתוב ואמר \"לא תאכלנו למען ייטב לך ולבניך אחריך\"\u0004 — לא בא הכתוב השני לענין דם (שהרי כתובים רבים נאמרו באיסור הדם) אלא \u0003בבשר בחלב הכתוב מדבר,\u0004 שאסור באכילה.","ודנים בדבר: \u0003אתה אומר\u0004 כי \u0003בבשר בחלב הכתוב מדבר, או\u0004 שמא \u0003אינו אלא באחד מכל\u0004 שאר \u0003האיסורין\u0004 האחרים \u0003שבתורה? אמרת\u0004 (אומר אתה) בתשובה לכך כי \u0003צא ולמד משלש עשרה מדות שהתורה נדרשת בהן,\u0004 ואחת מהן היא \u0003דבר הלמד מענינו. במה הכתוב מדבר\u0004 בפרשיה זו של פסולי המוקדשים — \u0003בשני מינין,\u0004 שהרי פסולי המוקדשים שנפדו, נחשבים כשני מינים: מצד אחד הריהם כחולין (לענין היתר אכילתם), ואולם מצד שני הם כקדשים (לענין איסור גיזה ועבודה בהם). \u0003אף כאן\u0004 בכתוב \"לא תאכלנו\" השני — \u0003בשני מינין\u0004 הכתוב מדבר, והוא איסור בשר בחלב. וזהו איפוא המקור בתורה לאיסור בשר בחלב.","אמר ריש לקיש לר' יוחנן: עדיין נצרכים אנו לדרשה זו שאמרתי, שכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004המשנה \u0003ההיא\u0004 ששנה רבי בלבד היינו למדים — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003רק\u0004 \u0003ב\u0004איסור \u0003אכילה\u0004 של בשר בחלב, \u0003אבל ב\u0004איסור \u0003הנאה\u0004 של בשר בחלב — \u0003לא\u0004 דיבר הכתוב. לכך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 הכתוב האמור בקרבן פסח \u0005משמיע לנו]\u0006 שיש גם איסור הנאה בבשר בחלב.","ושואלים: \u0003ו\u0004לשיטת \u0003רבי\u0004 שלמד את איסור בשר בחלב מן הכתוב \"לא תאכלנו\" בלבד, איסור בשר בחלב אף \u0003בהנאה מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה מהכא\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו\u0006 הדבר \u0005מכאן],\u0006 שכן \u0003נאמר כאן\u0004 בדין בשר בחלב \u0003\"כי עם קדוש אתה לה'\u0004 אלהיך לא תבשל גדי בחלב אמו\" (דברים יד, כא), \u0003ונאמר להלן\u0004 (בהמשך הספר) \u0003\"ולא יהיה קדש בבני ישראל\"\u0004 (שם כג, יח). הרי זה להקיש דין בשר בחלב לדין קדש: \u0003מה להלן ב\u0004איסור קדש — הריהו אסור ב\u0003הנאה,\u0004 (שכן הוא אסור בבעילה שהיא איסור הנאה). \u0003אף כאן,\u0004 באיסור בשר בחלב — הריהו אסור \u0003בהנאה.\u0004","ומביאים עוד הסבר מה המקור לשיטת רבי לאיסור הנאה בבשר בחלב: שכן התנא \u0003דבי\u0004 \u0005[של בית]]\u0006 מדרשו של \u0003ר' אליעזר תנא\u0004 \u0005[שנה]\u0006 על הפסוק \u0003\"לא תאכלו כל נבלה\u0004 לגר אשר בשעריך תתננה ואכלה או מכור לנכרי כי עם קדוש אתה לה' אלהיך לא תבשל גדי בחלב אמו\" (שם יד, כא) — \u0003אמרה תורה\u0004 את דין מכירת הנבילה לנכרי בסמוך לאיסור בשר בחלב, כדי להורות כי \u0003כשתמכרנה\u0004 לנכרי את הנבילה, \u0003לא תבשלנה\u0004 בחלב \u0003ותמכרנה,\u0004 שכן כיון שהתבשלה בחלב הריהי אסורה בהנאה, ושוב אין רשות למוכרה.","למעלה הובאו דברי רב אשי ודברי ריש לקיש ורבי בענין המקור לאיסור בשר בחלב, ובענין זה מביאים עוד. החכם \u0003דבי\u0004 \u0005[של בית]\u0006 מדרשו של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]:\u0006 הכתוב \u0003\"לא תבשל גדי בחלב אמו\"\u0004 נאמר \u0003שלש פעמים\u0004 בתורה (שמות כג, יט; שם לד, כו; דברים יד, כא). וסיבת הדבר שנכתב שלוש פעמים: כתוב \u0003אחד\u0004 בא \u0003ל\u0004למדנו \u0003איסור אכילה, ו\u0004כתוב \u0003אחד\u0004 בא \u0003ל\u0004למדנו \u0003איסור הנאה, ו\u0004כתוב \u0003אחד\u0004 בא \u0003ל\u0004למדנו \u0003איסור בשול.\u0004","ועוד בענין זה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003איסי בן יהודה אומר: מנין לבשר בחלב שאסור?\u0004 שכן \u0003נאמר כאן\u0004 באיסור בשר בחלב \u0003\"כי עם קדוש אתה\",\u0004 \u0003ונאמר להלן\u0004 \u0005[שם,\u0006 בספר שמות כב, ל\u0005]\u0006 \u0003\"ואנשי קדש תהיון לי ובשר בשדה טרפה לא תאכלו\".\u0004 להשוות זה לזה, וללמדנו: \u0003מה להלן\u0004 בשר טריפה — \u0003אסור, אף כאן\u0004 בשר בחלב — \u0003אסור.\u0004","\u0003ואין לי\u0004 לימוד מכאן \u0003אלא\u0004 לענין איסור בשר בחלב \u0003באכילה,\u0004 איסור בשר בחלב אף \u0003בהנאה מנין\u0004 לי? שכן \u0003אמרת\u0004 כי \u0003קל וחומר\u0004 הוא, ובאופן זה: \u0003ומה ערלה\u0004 שקלה היא, \u0003ש\u0004הרי \u0003לא נעבדה בה עבירה\u0004 כלל אלא צמחה בעצמה \u0003—\u0004 \u0003אסורה בהנאה, בשר בחלב\u0004 שחמור הוא, \u0003ש\u0004כן \u0003נעבדה בו עבירה\u0004 — \u0003אינו דין ש\u0004יהיה \u0003אסור בהנאה!\u0004","ודוחים: יש מקום לפרוך קל וחומר זה, שכן \u0003מה לערלה, שכן\u0004 יש בה צד חומרה, שהרי \u0003לא היתה לה\u0004 מעולם \u0003שעת הכושר\u0004 (זמן שבו היתה מותרת באכילה), תאמר בבשר בחלב שהיתה להם שעת הכושר!","ואומרים: \u0003חמץ בפסח יוכיח שהיתה לו שעת הכושר\u0004 (לפני חג הפסח) \u0003ו\u0004בכל זאת הריהו \u0003אסור בהנאה,\u0004 ומכאן נלמד גם לבשר בחלב. ומשיבים: אין זו דחייה, שכן \u0003מה לחמץ בפסח\u0004 שיש בו צד חמור אחר, \u0003שכן ענוש כרת\u0004 על אכילתו בפסח, ואפשר שצד חמור זה הוא שגרם לו להיאסר בהנאה.","ושבים ודוחים: אין צד זה של חומרה גורם איסור הנאה, שהרי \u0003כלאי הכרם יוכיחו, ש\u0004אף ש\u0003אין ענוש כרת\u0004 על אכילתם, \u0003ו\u0004בכל זאת הריהו \u0003אסור בהנאה.\u0004","ותוהים: \u0003למה לי גזרה שוה\u0004 זו של \"עם קדוש\" ו\"לא יהיה קדש\" ללמדני איסור אכילה בבשר בחלב, וקל וחומר מערלה ללמדני איסור הנאה בבשר בחלב, \u0003לייתי כולה\u0004 \u0005[שיבוא,\u0006 שיילמד \u0005הכל]\u0006 \u0003בקל וחומר מערלה, ו\u0004באופן זה: \u0003מה ערלה,\u0004 שקלה היא, \u0003ש\u0004הרי \u0003לא נעבדה בה עבירה\u0004 — בכל זאת \u0003היא\u0004 \u0003אסורה בין באכילה בין בהנאה. בשר בחלב,\u0004 שחמור הוא, \u0003ש\u0004הרי \u0003נעבדה בו עבירה\u0004 — \u0003אינו דין שאסור בין באכילה בין בהנאה!\u0004","ומשיבים: אין ללמוד כן מקל וחומר, \u0003משום דאיכא למימר\u0004 \u0005[שיש מקום לומר]\u0006 פירכה על קל וחומר זה כי \u0003חורש בשור ובחמור, וחוסם פי פרה ודש בה יוכיח,\u0004 שאין זה שנעבדה בו עבירה נאסר באכילה. \u0003ש\u0004הרי באלה \u0003נעבדה בהם עבירה, ו\u0004בכל זאת \u0003שרו\u0004 \u0005[מותרים]\u0006 התבואה שגדלה מחרישה זו והתבואה שנידושה בדייש זה.","ושואלים: כאשר דחינו את ההוכחה מחמץ בפסח, ואמרנו כי כלאי הכרם יוכיחו (שהרי אין עונש כרת על אכילתם), \u0003למה לי למימר\u0004 \u0005[לומר]\u0006 \u0003כלאי הכרם יוכיחו, לימא\u0004 \u0005[שיאמר]:\u0006 \u0003ערלה תוכיח, ו\u0004מעתה \u0003ליהדר דינא וליתי\u0004 \u0005[יחזור הדין ויבוא\u0006 וילמד\u0005]\u0006 \u0003במה הצד.\u0004 שאמנם אין ללמוד מערלה בלבד (שכן לא היתה לה שעת הכושר), וכמו כן אין ללמוד מפסח (שכן ענוש כרת). ואולם הצד השווה שבשניהם שהם אסורים באכילה ואסורים בהנאה. מעתה נאמר כן גם בבשר בחלב שאסור הוא באכילה (כדבר הנלמד מגזירה שווה \"עם קדוש\" \"לא יהיה קדש\"), והריהו אסור גם בהנאה!","\u0003אמר רב אשי\u0004 בתשובה: אין ללמוד במה הצד, \u0003משום דאיכא למימר\u0004 \u0005[שיש מקום לומר]\u0006 פירכה בדבר, כי \u0003נבלה תוכיח, ש\u0004הריהי \u0003אסורה באכילה ומותרת בהנאה.\u0004 ומעתה נאמר כי אף בשר בחלב אסור באכילה ומותר בהנאה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי:\u0004 אין מכאן פירכה, \u0003שכן\u0004 \u0003הכי אמרינן משמיה\u0004 \u0005[כך אנו אומרים משמו]\u0006 של \u0003ריש לקיש: כל\u0004 פירכה הבאה על לימוד של \u0003ב\u0004\u0003מה הצד\u0004 — \u0003מגופו\u0004 של הדינים הנזכרים במידת במה הצד (ובעניננו, בשר בחלב, ערלה, חמץ) \u0003פרכינן\u0004 \u0005[פורכים אנו],\u0006 ואולם \u0003מעלמא לא פרכינן\u0004 \u0005[מבחוץ,\u0006 כדרך שפרכת מנבילה, \u0005אין אנו פורכים].\u0006","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003תיתי\u0004 \u0005[שתבוא,\u0006 תילמד\u0005]\u0006 איסור הנאה בבשר בחלב \u0003במה הצד,\u0004 ומדוע נצרכים אנו לכלאי הכרם יוכיחו? ומשיבים: \u0003משום דאיכא למיפרך\u0004 \u0005[שיש מקום לפורכה]\u0006 באופן זה: \u0003מה להצד השוה שבהן,\u0004 בערלה ובחמץ — \u0003שכן גדולי קרקע\u0004 הם, תאמר בבשר בחלב שאינם מגידולי קרקע!","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא שיש מקום לפירכה זו, \u0003השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 שלמדנו מכלאי הכרם, גם כן \u0003איכא למיפרך\u0004 \u0005[יש מקום לפרוך]\u0006 ולומר: \u0003מה לכלאי הכרם שכן\u0004 גם הם \u0003גדולי קרקע!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: הכי אמרינן משמיה\u0004 \u0005[כך אנו אומרים משמו]\u0006 של \u0003ריש לקיש\u0004 כי \u0003כל\u0004 לימוד של ב\u0003מה הצד פרכינן כל דהו\u0004 \u0005[אנו פורכים\u0006 אותו ב\u0005כל\u0006 נימוק \u0005שהוא],\u0006 וכגון הפירכה \"מה להצד השווה שכן גידולי קרקע\". ואולם לימוד הנסמך על \u0003\"לא אם אמרת\"\u0004 (כגון הלימוד שלנו הנסמך על כלאי הכרם, שאומרים אנו בו: לא אם אמרת בכלאי הכרם, שגידולי קרקע הם), שלומדים אנו כ\u0003חדא מחדא\u0004 \u0005[כאחד\u0006 המלמד \u0005על\u0006 \u0005אחד\u0006 הנלמד\u0005]\u0006 — פירכה שהיא נוגעת ישירות ל\u0003קל וחומר פרכינן\u0004 \u0005[פורכים אנו],\u0006 ואילו פירכה \u0003כל דהו\u0004 \u0005[כל שהיא]\u0006 — \u0003לא פרכינן\u0004 \u0005[אין אנו פורכים].\u0006","ושואלים: \u0003וליפרוך לכולהו\u0004 \u0005[ושיפרוך על כולם],\u0006 ויקשה: \u0003מה לכולהו\u0004 \u0005[לכולם]\u0006 \u0003שכן גדולי קרקע,\u0004 ואי אפשר ללמוד מהם על בשר בחלב שאינם גידולי קרקע!","\u0003אלא, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי, הכי אמרינן משמיה\u0004 \u0005[כך אנו אומרים משמו]\u0006 של \u0003ריש לקיש:\u0004"],["דרך לימוד של הלכה \u0003חדא\u0004 \u0005[אחת]\u0006 הנלמדת \u0003מ\u0004הלכה \u0003חדא\u0004 \u0005[אחת]\u0006 המלמדת, כלימוד זה של בשר בחלב מערלה בלבד — פירכה המצביעה על צד של \u0003קולא\u0004 \u0005[קלות]\u0006 שיש בהלכה זו \u0003ו\u0004צד של \u0003חומרא\u0004 \u0005[חומרה]\u0006 שיש בהלכה זו, האחרת, \u0003פרכינן\u0004 \u0005[פורכים אנו],\u0006 ואילו פירכה \u0003כל דהו\u0004 \u0005[שהיא]\u0006 \u0003לא פרכינן\u0004 \u0005[אין אנו פורכים].\u0006 ואילו דרך לימוד של הלכה \u0003חדא\u0004 \u0005[אחת]\u0006 הנלמדת \u0003מתרתי\u0004 \u0005[משתי]\u0006 הלכות המלמדות, וכדרך שהוצעה למעלה ללמוד בשר בחלב מערלה ומחמץ בפסח — \u0003אפילו\u0004 פירכה \u0003כל דהו פרכינן\u0004 \u0005[כל שהיא אנו פורכים],\u0006 ודרך לימוד של הלכה","\u0003חדא\u0004 \u0005[אחת]\u0006 הנלמדת \u0003מתלת\u0004 \u0005[משלוש]\u0006 הלכות, כגון זה שהצענו למעלה ללמוד בשר בחלב מערלה וחמץ בפסח וכלאי הכרם, \u0003אי הדר דינא ואתי\u0004 \u0005[אם חוזר הדין ובא],\u0006 שניתן לומר בשלושתן מידת \u0003במה הצד,\u0004 שאמנם לא ראי זו כראי זו ולא ראי זו כראי זו, ואולם יש דבר המשותף לכולן — \u0003פרכינן\u0004 \u0005[פורכים אנו]\u0006 פירכה \u0003כל דהו\u0004 \u0005[שהיא],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 חוזר הדין, שאין לנו אפשרות למצוא צד משותף לכולן — פירכה המצביעה על צד של \u0003קולא\u0004 \u0005[קלות]\u0006 שיש בהלכה זו \u0003ו\u0004צד של \u0003חומרא\u0004 \u0005[חומרה]\u0006 שיש בהלכה זו, \u0003פרכינן\u0004 \u0005[פורכים אנו],\u0006 ואילו פירכה \u0003כל דהו\u0004 \u0005[שהיא]\u0006 \u0003לא פרכינן\u0004 \u0005[אין אנו פורכים].\u0006 ומעתה כיון שאין אנו לומדים איסור אכילה בבשר בחלב משלוש ההלכות הללו (ערלה, חמץ בפסח וכלאי הכרם) במידת במה הצד (שכן אין הדין חוזר בהן), שוב אין מקום להקשות על שלושתן \"מה לכולם שכן גידולי קרקע\".","ושואלים: \u0003ולפרוך\u0004 \u0005[ונקשה]\u0006 באופן זה: \u0003מה לכלאי הכרם\u0004 — \u0003שכן לא היתה להן שעת הכושר,\u0004 שכן סברה היא שאין התבואה הנזרעת בכרם נאסרת עם זריעתה, אלא הגידולים שצמחו מעל פני הקרקע בעקבות הזריעה. ומעתה הרי אלה מעולם לא היתה להם שעה של היתר, שמשעה שצמחו הריהם אסורים. והרי זה שלא כבשר בחלב, שהיתה לכל אחד מאלה זמן של היתר, בטרם התבשלו ביחד! \u0003אמר רב אדא בר אהבה\u0004 בתשובה על כך: \u0003זאת אומרת\u0004 שלא כפי שסברנו שב\u0003כלאי הכרם\u0004 נאסרים רק הגידולים שצמחו בעקבות הזריעה, אלא כבר ב\u0003עיקרן\u0004 (בשורשם, בהיותם זרעים שהכו שורשים בקרקע) \u0003נאסר\u0004 הזרע, \u0003ו\u0004נמצא איפוא כי \u0003היתה להן\u0004 לזרעים הללו \u0003שעת הכושר\u0004 (זמן היתר אכילה) \u0003קודם השרשה.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על דברי רב אדא בר אהבה \u0003רב שמעיה בר זעירא\u0004 ממה ששנינו בדינו של זה \u0003המעביר עציץ נקוב\u0004 שזרע בו מין תבואה או ירק, \u0003ב\u0004תוך ה\u0003כרם,\u0004 שלא הניח את העציץ על הקרקע אלא העבירו מתחת לעצי הכרם, \u0003אם\u0004 בזמן שהעביר אותו בכרם \u0003הוסיף\u0004 הזרע שבעציץ כדי אחד מ\u0003מאתים\u0004 — \u0003אסור\u0004 הזרע. ונדייק: רק אם הזרע \u0003הוסיף\u0004 כדי השיעור הזה — \u0003אין\u0004 \u0005[כן]\u0006 הוא נאסר, אבל אם הזרע \u0003לא הוסיף\u0004 כדי השיעור הזה — הוא \u0003לא\u0004 נאסר, שאין נאסרים באיסור כלאי הכרם אלא מה שגדל באיסור (ויש בו כשיעור האוסר), והרי זה שלא כרב אדא בר אהבה שאמר שעצם זריעתם בקרקע אוסרתם!","\u0003אמר אביי\u0004 בהסבר דברי רב אדא בר אהבה: \u0003תרי קראי כתיבי\u0004 \u0005[שני מקראות כתובים]\u0006 בתורה בדין כלאי הכרם, שכן \u0003כתיב\u0004 \u0005[נאמר]\u0006 \"לא תזרע כרמך כלאים פן תקדש המלאה הזרע אשר תזרע ותבואת הכרם\" (דברים כב, ט). והרי יש בדברים כעין סתירה: שכתוב אחד אומר \u0003\"פן תקדש המלאה\"\u0004 — הרי זה מורה שהגידולים הנוספים (\"המלאה\") הם הנאסרים. \u0003ו\u0004אולם עוד \u0003כתיב\u0004 \u0005[ונאמר]\u0006 בפסוק \u0003\"הזרע\u0004 אשר תזרע\" — והרי זה מורה שהזריעה עצמה נאסרת, ואף בטרם הצמיחה תוספת.","\u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 יתיישבו שני המקראות הללו? כל אחד מהכתובים עניינו במצב שונה: שאם היה מין התבואה או הירק \u0003זרוע מעיקרו\u0004 (מתחילתו) בתוך הכרם — הרי הוא נאסר \u0003מיד\u0004 \u0003בהשרשה,\u0004 והוא שאמר בו הכתוב \"הזרע אשר תזרע\". ואם היה \u0003זרוע ובא,\u0004 שבתחילה נזרע והשריש בהיתר מחוץ לכרם, בזה אומרים אנו שאם \u0003הוסיף\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 נאסר, ואם \u0003לא הוסיף\u0004 — \u0003לא\u0004 נאסר, והוא שאמר בו הכתוב \"תקדש המלאה\".","שנינו במשנתנו כי בשר בחלב אסור אף בהנאה, ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 היא ש\u0003לא כי האי תנא\u0004 \u0005[כמו\u0006 שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יהודה אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון: בשר בחלב\u0004 אמנם \u0003אסור באכילה ו\u0004אולם \u0003מותר בהנאה.\u0004 וטעמו: \u0003ש\u0004כן \u0003נאמר\u0004 בדין בשר בחלב \u0003\"כי\u0004 \u0003עם קדוש אתה\u0004 לה' אלהיך לא תבשל גדי בחלב אמו\" (דברים יד, כא), \u0003ו\u0004כן \u0003נאמר להלן\u0004 \u0005[שם,\u0006 בספר שמות\u0005]\u0006 באיסור טריפה \u0003\"ואנשי קדש תהיון לי\u0004 ובשר בשדה טרפה לא תאכלו לכלב תשליכון אותו\" (שמות כב, ל).","\u0003מה להלן\u0004 באיסור טריפה — \u0003אסור באכילה ומותר בהנאה,\u0004 שהרי נאמר כי אפשר ליתנו לכלב, \u0003אף כאן\u0004 באיסור בשר בחלב — \u0003אסור באכילה, ומותר בהנאה.\u0004","עוד שנינו במשנתנו כי \u0003ר' עקיבא אומר\u0004 ש\u0003חיה ועוף\u0004 בבשר בחלב אינם אסורים מן התורה, שכן נאמר \"לא תבשל גדי בחלב אמו\" שלוש פעמים (שמות כג, יט; שם לד, כו; דברים יד, כא), ובאו שלושה מיעוטים אלה להשמיענו שאין בכלל האיסור בשר של חיה ועוף ובהמה טמאה. ושואלים: \u0003הני\u0004 \u0005[אלה]\u0006 שלוש הפעמים שנכתב האיסור, \u0003הא אפקינהו\u0004 \u0005[הרי הוציא אותם,\u0006 נדרשו\u0005]\u0006 \u0003ל\u0004למדנו הלכות אחרות, ו\u0003כ\u0004דרך שאמר","\u0003שמואל\u0004 (לעיל קיג,ב), שאחד בא לענין בישול חלב בחלב ולענין בשר בהמה מתה (נבילה) בחלב, שאף אלה בכלל איסור בשר בחלב. ואחד בא לענין בישול עובר (שליל) בחלב, שאף הוא בכלל בשר בחלב. והאחר בא לענין בשר טמאה בחלב, שאין היא בכלל איסור בישול בשר בחלב! ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' עקיבא\u0004 כי משמעות הכתוב \"לא תבשל גדי\" היא \u0003שאף חלב ונבילה בכלל זה, ואין צורך בכתוב מיוחד (כשמואל) להשמיענו כן. ובטעם הדבר שאיסור בשר בחלב חל על הדבר שאסור כבר באיסור קודם (חלב או נבילה) —\u0004 סבור ר' עקיבא כי \u0003איסור חל על איסור,\u0004 ולכן \u0003חלב ומתה לא צריכי קרא\u0004 \u0005[אינם צריכים מקרא].\u0006 וכיוצא בזה גם לענין \u0003שליל\u0004 בבשר בחלב אין צורך בכתוב מיוחד להשמיענו כן, כי \u0003גדי מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא\u0004 השליל. מעתה \u0003אייתרו להו כולהו\u0004 \u0005[נשארו להם כולם,\u0006 כל שלוש הפעמים הכתובות\u0005],\u0006 ובאים הם ללמדנו שלוש דרשות: \u0003פרט לחיה, ו\u0004פרט ל\u0003עוף, ו\u0004פרט \u0003לבהמה טמאה.\u0004","עוד שנינו במשנתנו כי \u0003ר' יוסי הגלילי אומר\u0004 כי \u0003נאמר\u0004 בתורה \u0003\"לא תאכלו\u0004 כל נבילה\" (דברים יד, כא), וכן נאמר באותו כתוב \"לא תבשל גדי בחלב אמו\", והרי זה בא ללמדנו כי הדבר שאסור משום נבילה אסור לבשלו בחלב. ומעתה היה מקום לומר שאף עוף, שאסור משום נבילה, יהא אסור בבישול בשר בחלב, לכך אמר הכתוב \"בחלב אמו\" — יצא העוף שאין לו חלב אם. ושואלים: \u0003מאי איכא\u0004 \u0005[מה יש],\u0006 מה ההבדל \u0003בין ר' יוסי הגלילי\u0004 הממעט עוף מאיסור בשר בחלב מן הכתוב \"בחלב אמו\" \u0003ל\u0004בין \u0003ר' עקיבא\u0004 שממעטו מן הכתוב \"לא תבשל גדי\"?","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לענין בישול בשר \u0003חיה\u0004 בחלב. ש\u0003ר' יוסי הגלילי סבר\u0004 \u0005[סבור]\u0006 כי בשר \u0003חיה\u0004 בחלב אסור \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 שהרי אף החיה היא בכלל \"בחלב אמו\". \u0003ו\u0004אילו \u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 כי בשר \u0003חיה\u0004 בחלב אינו אלא \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 שהרי התמעט בשר חיה מן הכתוב \"לא תבשל גדי\".","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 הבדל נוסף שבין ר' יוסי הגלילי לר' עקיבא, דין בשר \u0003עוף\u0004 בחלב \u0003איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 ש\u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 כי \u0003חיה ועוף אינן\u0004 אסורות \u0003בחלב\u0004 \u0003מן התורה, הא מדרבנן אסירי\u0004 \u0005[הרי מדברי סופרים\u0006 הם \u0005אסורים],\u0006 \u0003ו\u0004אילו \u0003ר' יוסי הגלילי סבר\u0004 \u0005[סבור]\u0006 כי בשר \u0003עוף\u0004 בחלב \u0003אפילו מדרבנן נמי לא אסיר\u0004 \u0005[מדברי סופרים גם כן לא אסור].\u0006","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך,\u0006 כהסבר השני שהוצע\u0005]:\u0006 \u0003במקומו של ר' אליעזר היו כורתין עצים\u0004 בשבת, \u0003לעשות פחמין לעשות ברזל\u0004 כדי למול. \u0003במקומו של ר' יוסי הגלילי היו אוכלין בשר עוף בחלב.\u0004 שסברו שאף מדרבנן מותר הדבר.","ובענין זה מסופר כי החכם \u0003לוי איקלע לבי\u0004 \u0005[הזדמן לביתו]\u0006 של \u0003יוסף רישבא\u0004 \u0005[הצייד],\u0006 \u0003אייתו לקמיה רישא דטיוסא בחלבא\u0004 \u0005[הביאו לפניו ראש טווס בחלב],\u0006 \u0003ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003ו\u0004אף \u0003לא מידי\u0004 \u0005[דבר],\u0006 \u0003כי אתא לקמיה\u0004 \u0005[כאשר בא\u0006 לוי \u0005לפני]\u0006 \u0003רבי\u0004 וסיפר לו, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבי ללוי: \u0003אמאי\u0004 \u0005[מדוע]\u0006 מדוע שתקת על כך, ו\u0003לא תשמתינהו\u0004 \u0005[נידית אותם]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אתריה\u0004 \u0005[מקומו]\u0006 של \u0003ר' יהודה בן בתירא הוא, ואמינא\u0004 \u0005[ואמרתי\u0006 בלבי\u0005]\u0006 שמא ר' יהודה בן בתירא \u0003דרש להו\u0004 \u0005[להם,\u0006 לבני \u0005מקומו\u0006\u0005]\u0006 בהלכות בשר בחלב \u0003כר' יוסי הגלילי\u0004 ש\u0003אמר\u0004 שאין בשר עוף בכלל איסור בשר בחלב, כי \u0003יצא עוף\u0004 מכלל איסור זה כיון \u0003שאין לו חלב אם,\u0004 ומותר לכתחילה לאכול אותו בחלב.","\u0003קבת\u0004 בהמתו של \u0003גוי ו\u0004קיבתה \u0003של נבלה,\u0004 החלב הקרוש הנמצא בתוכן — \u0003הרי זו אסורה. המעמיד\u0004 (מקריש את החלב לעשותו גבינה) \u0003ב\u0004אמצעות \u0003עור של קבה\u0004 של בהמה \u0003כשרה\u0004 הניתן לתוך החלב, והריהו מעמידו בכך."],["\u0003אם יש\u0004 בעור הקיבה שיעור שיש בו \u0003בנותן טעם\u0004 בחלב — \u0003הרי זו\u0004 הגבינה שנעשתה מן החלב \u0003אסורה.\u0004 בהמה \u0003כשרה שינקה מן\u0004 הבהמה \u0003הטרפה\u0004 — החלב שב\u0003קבתה אסורה,\u0004 שהרי דינו כחלב הטריפה. ואילו בהמה \u0003טרפה שינקה מן\u0004 הבהמה \u0003הכשרה\u0004 — החלב שב\u0003קבתה מותרת,\u0004 שדין החלב הוא כדין הבהמה ממנה ינקו, \u0003מפני ש\u0004החלב שיונקת הבהמה מבהמה אחרת הוא \u0003כנוס במעיה,\u0004 ואינו חלק מגופה.","שנינו במשנתנו דינן של קיבת בהמת גוי וקיבת בהמה נבלה שהן אסורות. ותוהים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003קבת\u0004 בהמה ששחטה \u0003גוי לאו\u0004 \u0005[לא]\u0006 \u0003נבלה היא?!\u0004 ואם כן, מדוע מחלק אותם התנא? \u0003אמר רב הונא\u0004 בתשובה: \u0003הכא\u0004 \u0005[כאן\u0006 במשנתנו ששנינו בה \"קיבת גוי\"\u0005]\u0006 אין אנו עוסקים בבהמה ששחטה גוי, אלא \u0003ב\u0004ישראל ה\u0003לוקח\u0004 (קונה) \u0003גדי מן הגוי\u0004 ונשחט הגדי בידי הישראלי \u0003עסקינן\u0004 \u0005[עוסקים אנו].\u0006 שאין בגדי זה משום איסור נבלה, \u0003ו\u0004אולם \u0003חיישינן\u0004 \u0005[וחוששים אנו]\u0006 בו \u0003שמא ינק מן\u0004 הבהמה \u0003הטרפה,\u0004 ולכך החלב שבקיבתו אסור, והוא השנוי במשנתנו \"קיבת גוי\".","ומקשים על הסבר זה: \u0003ומי חיישינן\u0004 \u0005[והאם אנו חוששים]\u0006 בגדי הנקנה מן הגוי \u0003שמא ינק מן הטרפה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 כי \u0003לוקחים\u0004 (קונים) מלכתחילה \u0003ביצים מן הגוים, ואין חוששין\u0004 בדבר זה \u0003לא משום\u0004 שמא באו הביצים מתרנגולת \u0003נבלה ולא משום\u0004 שמא באו מתרנגולת \u0003טרפה!\u0004 ומשיבים: אכן אין חוששים ליניקת הגדי מן הבהמה הטרפה, \u0003אלא\u0004 כך \u0003אימא\u0004 \u0005[אמור]\u0006 את הסברו של רב הונא בדברי משנתנו: \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 בגדי זה שנקנה מן הגוי \u0003שמא ינק מן הטמאה,\u0004 ולכך החלב שבקיבתו אסור.","ושואלים: \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 בהמה \u0003טרפה דלא חיישינן\u0004 \u0005[שאין אנו חוששים]\u0006 שהגדי ינק ממנה, \u0003ומאי שנא\u0004 \u0005[ובמה שונה]\u0006 בהמה \u0003טמאה דחיישינן\u0004 \u0005[שאנו חוששים]\u0006 ליניקת הגדי ממנה? ומשיבים: בהמה \u0003טרפה לא שכיחא\u0004 \u0005[אינה מצויה],\u0006 ולכן אין לחשוש שמא ינק ממנה גדי זה, ואילו בהמה \u0003טמאה\u0004 היא \u0003שכיחא\u0004 \u0005[מצויה],\u0006 ולכן חוששים שמא ינק ממנה גדי זה.","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 בהמה טמאה היא \u0003שכיחא\u0004 \u0005[מצויה],\u0006 מעתה \u0003אפילו גבי דידן ניחוש\u0004 \u0005[אצלנו,\u0006 בקונה גדי מן הישראל, \u0005נחשוש]\u0006 שמא ינק גדי זה מן הטמאה, ויהא החלב שבקיבתו אסור! ומשיבים: \u0003אנן\u0004 \u0003דבדלינן מינייהו\u0004 \u0005[אנו,\u0006 ישראליים, \u0005שבדלים אנו מהן,\u0006 מבהמות טמאות\u0005],\u0006 \u0003וכי חזינן להו\u0004 \u0005[וכאשר אנו רואים אותן],\u0006 מיד \u0003מפרשינן להו\u0004 \u0005[מרחיקים אנו אותם\u0006 את הגדיים \u0005היונקים מן הבהמות הללו\u0006\u0005]\u0006 — \u0003לא גזרו בהו חכמים\u0004 \u0005[בהם חכמים],\u0006 \u0003אינהו\u0004 \u0005[הם,\u0006 הגוים\u0005],\u0006 \u0003דלא בדילי מינייהו\u0004 \u0005[שאין בדלים מהן,\u0006 מן הטמאות\u0005],\u0006 \u0003וכי חזו להו\u0004 \u0005[וכאשר\u0006 הם \u0005רואים אותן]\u0006 הם \u0003לא מפרשי להו\u0004 \u0005[לא מרחיקים אותם\u0006 את הגדיים היונקים מן הטמאות\u0005]\u0006 — \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים].\u0006","\u0003ושמואל אמר\u0004 תשובה אחרת לשאלה מדוע שונים אנו במשנתנו \"קיבת גוי וקיבה של נבלה\" והרי אף הקיבה של הבהמה הנשחטת על ידי גוי היא קיבת נבלה: הלכה \u0003חדא קתני\u0004 \u0005[אחת שנויה\u0006 במשנתנו\u0005],\u0006 שכך יש לשנותה, \u0003קבת שחיטת גוי,\u0004 שהריהי \u0003נבלה,\u0004 הרי זו אסורה.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר שמואל הכי\u0004 \u0005[כך]\u0006 שקיבת נבלה אסורה, כיון שהיא נחשבת כחלק מגוף הבהמה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003שמואל: מפני מה אסרו\u0004 חכמים את \u0003גבינת הגוים? מפני\u0004 \u0003שמעמידין אותה בעור קבת נבלה.\u0004 ונדייק מכאן: טעם האיסור הוא רק משום עור קיבת הנבלה, שהרי זה גוף הבהמה עצמה. \u0003הא\u0004 \u0005[הרי]\u0006 נלמד מכאן כי ה\u0003קבה\u0004 (החלב שנמצא בקיבה) \u0003גופה\u0004 \u0005[עצמה]\u0006 — \u0003שריא\u0004 \u0005[מותרת]!\u0006","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן שנינו במסכת עבודה זרה (כט,ב) שבתחילה אמר ר' יהושע בטעם איסור גבינות הגוים שהוא משום שמעמידים את החלב (ממנו נעשית הגבינה) בחלב הקרוש שבקיבת הנבלה. ולאחר מכן חזר בו ר' יהושע מהסברו זה, ואמר בטעם הדבר שהוא משום שמעמידים את החלב בקיבת עגלי עבודה זרה. ובעבודה זרה אף קיבתה אסורה. ומעתה יש לומר \u0003כי\u0004 \u0003כאן\u0004 במשנתנו מדובר \u0003קודם\u0004 ה\u0003חזרה\u0004 של ר' יהושע, ולכך אמר שמואל בהסבר דברי משנתנו כי האיסור הוא בכך שקיבת שחיטת גוי הינה נבלה. ואילו \u0003כאן\u0004 שאמר שמואל בטעם איסור גבינות הגוים שהוא מפני שמעמידים אותן בעור קיבת נבלה, ולא מפני שמעמידים אותן בקיבת נבלה, הרי זה \u0003לאחר\u0004 ה\u0003חזרה\u0004 של ר' יהושע.","שנינו במשנתנו כי בהמה \u0003כשרה שינקה מן\u0004 הבהמה \u0003הטרפה\u0004 — החלב שבתוך קיבתה אסור, ואילו בהמה טריפה שינקה מן הבהמה הכשרה — החלב שבתוך קיבתה מותר. ועל כך מקשים: \u0003והא קתני רישא\u0004 \u0005[והרי הוא,\u0006 התנא, \u0005שונה\u0006 ב\u0005התחלה\u0006 של המשנה\u0005]\u0006 כי \u0003קבת\u0004 (החלב הנמצא בקיבה) של בהמת \u0003גוי ושל\u0004 בהמת \u0003נבלה\u0004 — \u0003הרי זו אסורה,\u0004 ועתה שונים אנו שחלב קיבתה של הטריפה שינקה מן הכשרה הריהו כשר, ואין הבדל לענין זה בין בהמה נבלה לבין בהמה טריפה!","\u0003אמר רב חסדא\u0004 בתשובה: אכן אין החלב הנמצא בקיבה של בהמת נבלה אסור, ואולם טעם הדבר שה\u0003רישא\u0004 \u0005[ההתחלה]\u0006 של המשנה אוסרתו הוא משום שהאוכל מחלב זה הריהו \u0003נראה כאוכל נבלות,\u0004 ומאוס הוא. מה שאין כן \u0003הכא\u0004 \u0005[כאן,\u0006 באכילתו של החלב הנמצא בקיבה של בהמה טריפה\u0005]\u0006 אין הדבר מאוס, כי \u0003איכא\u0004 \u0005[יש כאן]\u0006 \u0003שחיטה\u0004 שהרי נשחטה בהמת טריפה זו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לרב חסדא בקושיה על הסברו: \u0003ולאו\u0004 \u0005[והאם לא]\u0006 \u0003כל\u0004 ש\u0003כן הוא\u0004 מנבלה לטריפה, שיש בו ללמד שתהא קיבת טריפה אף היא אסורה. ובאופן זה: \u0003ומה נבלה\u0004 הקלה בדינה בהשוואה לטריפה, \u0003דמאיסה\u0004 \u0005[ש\u0006כן היא \u0005מאוסה],\u0006 ומשום שהיא מאוסה, \u0003דאי שרית ליה\u0004 \u0005[שאם תתיר לה]\u0006 את \u0003קבתה, לא אתי למיכל מינה\u0004 \u0005[לא יבואו\u0006 אנשים מתוך כך \u0005לאכול ממנה,\u0006 מן הנבלה עצמה\u0005]\u0006 — בכל זאת \u0003אמרת\u0004 בה שהיא \u0003לא\u0004 מותרת באכילה. בהמה \u0003טרפה\u0004 שהיא \u0003שחוטה,\u0004 ולכך אינה מאוסה, \u0003דאי שרית\u0004 \u0005[שאם תתיר]\u0006 את קיבתה לאכילה, יש מקום לחשש כי \u0003אתי למיכל מינה\u0004 \u0005[יבואו\u0006 אנשים \u0005לאכול ממנה]\u0006 — \u0003לא כל שכן\u0004 שצריך לאוסרה!","\u0003אלא אמר רב יצחק, אמר ר' יוחנן: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 שאמרנו בתחילת המשנה שקיבת הנבלה אסורה הרי זה נשנה \u0003קודם\u0004 ה\u0003חזרה\u0004 שחזר בו ר' יהושע (כמובא למעלה) ובשלב זה סבורים היינו כי קיבת נבלה אסורה. ואילו \u0003כאן\u0004 בסוף המשנה לענין קיבת טריפה ששנינו בה שהיא מותרת הרי זה נשנה \u0003לאחר\u0004 ה\u0003חזרה. ו\u0004אף שכאמור ראשית המשנה נשנתה קודם חזרה, מכל מקום ה\u0003משנה\u0004 כפי שהיא שנויה לפנינו \u0003לא זזה ממקומה\u0004 אלא נשארה בנוסח של לפני החזרה.","ועוד בדין העמדת גבינות, \u0003אמר ר' חייא בר אבא, אמר ר' יוחנן: מעמידין\u0004 חלב לעשותו גבינה \u0003בקבת נבלות, ו\u0004אולם \u0003אין מעמידין בקבת שחיטת גוי. אמר לפניו ר' שמעון בר אבא: כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אתה אומר זאת? האם \u0003כ\u0004דעת \u0003ר' אליעזר,\u0004 ש\u0003אמר\u0004 כי \u0003סתם מחשבת גוי\u0004 היא \u0003ל\u0004שם \u0003עבודה זרה,\u0004 ולכן בהמה שנשחטה על ידי כל גוי, נשחטה לשם עבודה זרה, ולכך כולה אסורה בהנאה, ונאסרה גם קיבתה (אף שאין היא אלא כפרש בלבד). מה שאין כן בנבלה, שאין אסורה אלא באכילה, ותוכן קיבתה מותר!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן לר' שמעון בר אבא: \u0003ואלא כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אמרתי את דברי?! שהרי ודאי הוא שנאמרו הדברים לדעת ר' אליעזר! אכן, שלא כדברי ר' חייא בר אבא בשם ר' יוחנן, מביאים שיטה אחרת בשם ר' יוחנן.","שכן \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב שמואל בר רב יצחק אמר\u0004 בשם \u0003ר' יוחנן\u0004 כי \u0003מעמידין בין בקבת נבלה, בין בקבת שחיטת גוי, שלא\u0004 צריך \u0003לחוש לדברי ר' אליעזר,\u0004 שאין ר' יוחנן סבור כי סתם מחשבת גוי היא לשם עבודה זרה. ומסכמים:","\u0003והלכתא\u0004 \u0005[והלכה]\u0006 היא כי \u0003אין מעמידין בעור קבת נבלה, אבל מעמידין בקבת נבלה ובקבת שחיטת גוי, ובקבת כשרה שינקה מן הטרפה, וכל שכן\u0004 שמעמידים \u0003בקבת טרפה שינקה מן הכשרה. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003חלב המכונס\u0004 (הנמצא) \u0003בה\u0004 בפנים, \u0003פירשא בעלמא הוא\u0004 \u0005[פרש בלבד הוא]\u0006 ואיננו נחשב כמאכל.","אף שהן חלב והן דם אסורים מן התורה באכילה, והאוכלם חייב כרת, מכל מקום יש צד \u0003חומר\u0004 (חומרה) \u0003ב\u0004איסור \u0003חלב\u0004 יותר \u0003מב\u0004 איסור \u0003דם, ו\u0004יש צד \u0003חומר ב\u0004איסור \u0003דם\u0004 יותר \u0003מב\u0004 איסור \u0003חלב.\u0004 ומפרטים: יש צד \u0003חומר בחלב\u0004 שאין בדם — \u0003שהחלב\u0004"],["\u0003מועלין\u0004 (יש דין מעילה) \u0003בו,\u0004 שאם נהנה מחלב של קרבן חייב להביא קרבן מעילה. מה שאין כן בדם, שאין בו דין מעילה. \u0003ו\u0004אם נעשה הקרבן פיגול (ששחטו על מנת לזרוק את דמו או לאכול את בשרו או להקטיר את אימוריו \u0003מחוץ לזמנו הראוי), או שנעשה הקרבן נותר (שנותר הקרבן לאחר זמן אכילתו הראוי), או שאכל את הקרבן בטומאת גופו —\u0004 בכל אלה \u0003חייבין עליו\u0004 על האכילה מלבד איסור חלב גם \u0003משום פיגול ונותר וטמא. מה שאין כן בדם,\u0004 שאין דין מעילה נוהג בדם הקרבן, ואין חייבים על אכילת דם משום פיגול נותר וטמא.","\u0003ו\u0004מצד שני יש \u0003חומר\u0004 \u0003ב\u0004איסור \u0003דם\u0004 שאינו קיים באיסור חלב. \u0003ש\u0004כן איסור \u0003הדם נוהג בבהמה ו\u0004ב\u0003חיה ו\u0004ב\u0003עוף, בין\u0004 ב\u0003טמאים ובין\u0004 ב\u0003טהורים, ו\u0004אילו איסור \u0003חלב אינו נוהג אלא בבהמה טהורה בלבד.\u0004","שנינו במשנתנו כי יש בחלב כל הקרבנות דין מעילה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ר' ינאי\u0004 בתשובה: שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בעניינם של אימורי (חלק הקרבן המוקרב על המזבח) פר כהן משיח \u0003\"כאשר יורם משור זבח השלמים\u0004 והקטירם הכהן על מזבח העולה\" (ויקרא ד, י). ויש לשאול: \u0003וכי מה למדנו\u0004 בפר כהן משיח \u0003משור זבח השלמים\u0004 בכתוב, שהרי אף בפר כהן משיח התפרשו האימורים הקרבים (\"ואת כל חלב פר החטאת... את החלב המכסה על הקרב ואת כל החלב אשר על הקרב. ואת שתי הכליות ואת החלב אשר \u0003עליהן אשר על הכסלים ואת היותרת על הכבד על הכליות יסירנה\". שם שם, ח—\u0004 ט)?","\u0003מעתה\u0004 יש לנו לומר כי \u0003הרי זה\u0004 ההיקש \u0003בא ללמד\u0004 מקרבן שלמים על פר כהן משיח, \u0003ונמצא\u0004 שהוא \u0003למד\u0004 מפר כהן משיח, ובאופן זה: \u0003מקיש שור זבח השלמים לפר כהן משיח, מה פר כהן משיח\u0004 — \u0003יש בו\u0004 באימוריו \u0003מעילה,\u0004 \u0003שכן קדשי קדשים הוא, וממון גבוה הוא, וכל הנהנה ממנו עובר על הכתוב \"נפש כי תמעול מעל וחטאה בשגגה מקדשי ה' \" (שם ה, טו).\u0004 \u0003אף שור זבח השלמים,\u0004 אף שקדשים קלים הוא, ולכך בעת היות הקרבן בחיים טרם שחיטה, לא היה בו דין מעילה (כי ממון בעלים הוא באותה עת) — \u0003יש בו\u0004 באימוריו, דין \u0003מעילה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' חנינא\u0004 לר' ינאי: מה טעם דורש אתה אותה מכאן, וכי \u0003כעורה\u0004 משנה \u0003זו ששנה רבי\u0004 (ר' יהודה הנשיא) שמן הנאמר בקרבן השלמים \"והקטירם הכהן המזבחה לחם אשה לריח ניחוח \u0003כל חלב לה' \"\u0004(שם ג, טז) נלמד הדבר, שבא הכתוב \"לה' \" להורות שיש \u0003לרבות\u0004 גם \u0003אימורי קדשים קלים ל\u0004דין \u0003מעילה.\u0004 שאף שעיקרו של דין מעילה נאמר בקדשי קדשים שהם \"מקדשי ה' \", אף אימורי קדשים קלים בכלל זה!","\u0003אמר אביי\u0004 בתשובה: עדיין \u0003איצטריך\u0004 \u0005[נצרכת]\u0006 גם דרשתו של ר' ינאי. \u0003דאי כתב רחמנא\u0004 \u0005[ש\u0006כן \u0005אם היתה כותבת התורה]\u0006 רק את המקרא \"כל \u0003חלב\u0004 לה' \"להשמיענו שגם אימורי קדשים קלים בכלל דין מעילה, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי אכן ה\u0003חלב\u0004 שבאימורי קדשים קלים — \u0003אין\u0004 \u0005[כן]\u0006 הוא בכלל דין מעילה, אבל ה\u0003יותרת ושתי כליות\u0004 שבאימורי קדשים קלים, שאינם בכלל חלב — \u0003לא\u0004 נאמר בהם דין מעילה, אף על פי שהן עולות למזבח כחלב. לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 עוד את המקרא \u0003\"כאשר יורם\u0004 משור זבח השלמים\", וכדרשתו של ר' ינאי, ללמדנו שאף שאר אימורי קדשים קלים הינם בכלל דין מעילה.","\u0003ו\u0004מן הצד השני, \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 רק את המקרא \u0003\"כאשר יורם\u0004 משור זבח השלמים\", והיינו למדים מכאן כדרשתו של ר' ינאי, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי דין מעילה בחלב נוהג בקדשים קלים רק בדבר שישנו כמותו גם בשור, ומעתה הייתי מסיק כי \u0003חלב\u0004 ה\u0003אליה\u0004 (הזנב השמן של הכבשה) \u0003דליתא\u0004 \u0005[שאינה\u0006 נמצאת\u0005]\u0006 \u0003בשור\u0004 — \u0003לא\u0004 ינהג בו דין מעילה. לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 גם את המקרא \u0003\"כל חלב\",\u0004 ולהשמיענו כדרשתו של רבי שיש דין מעילה \u0003בכל אימוריהם של קדשים קלים, ואף בחלב האליה. שכן מצאנו שנקראת האליה \"חלב\" ככתוב \"חלבו האליה תמימה\" (שם שם, ט).\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרי לרב זביד: אי\u0004 \u0005[אם]\u0006 ה\u0003אליה איקראי\u0004 \u0005[נקראת]\u0006 \u0003\"חלב\",\u0004 מעתה \u0003תיתסר\u0004 \u0005[שתיאסר]\u0006 \u0003באכילה,\u0004 כדרך שהחלב אסור! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב זביד לרב מרי בתשובה: \u0003עליך\u0004 (כנגד סברה זו שאמרת) \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באיסור אכילת חלב \u0003\"כל חלב שור וכשב ועז\u0004 לא תאכלו\" (שם ז, כג) — לא אסרה תורה משום חלב \u0003אלא ב\u0004\u0003דבר השוה בשור\u0004 \u0003וכשב\u0004 (וכבש) \u0003ועז,\u0004 ומאחר ואין האליה שווה בכל אלה, שאין היא מצויה בשור ובעז, אין היא אסורה.","\u0003רב אשי אמר\u0004 הסבר אחר מדוע אין האליה אסורה משום חלב, שכן \u0003\"חלבו האליה\"\u0004 — \u0003איקראי\u0004 \u0005[נקראת],\u0006 אבל \u0003\"חלב\" סתמא\u0004 \u0005[סתם]\u0006 — \u0003לא איקראי\u0004 \u0005[אינה נקראת].\u0006 ומקשים על דברי רב אשי: \u0003אלא מעתה\u0004 שאין האליה נקראת סתם \"חלב\", מעתה גם \u0003לא ימעלו בה! אלא\u0004 יש לחזור מהסברו של רב אשי, ו\u0003מחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 שההסבר הוא \u0003כ\u0004מו שאמר \u0003רב זביד.\u0004","שנינו במשנתנו כי נוהג דין מעילה בחלב, \u0003מה שאין כן בדם,\u0004 שאין הוא נוהג בו. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר עולא\u0004 בתשובה: שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באיסור אכילת דם \"כי נפש הבשר בדם היא ואני נתתיו לכם על המזבח לכפר על נפשותיכם כי הדם הוא בנפש יכפר\" (שם יז, יא), ובאה המלה \u0003\"לכם\"\u0004 להורות: \u0003הדם\u0004 \u0003שלכם יהא,\u0004 שאין הוא ממון גבוה אלא ממון הדיוט. החכם \u0003דבי\u0004 \u0005[של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]\u0006 הסבר אחר מדוע אין דין מעילה בדם, שכן נאמר בכתוב זה \u0003\"לכפר\u0004 על נפשותיכם\", והרי זה בא להורות כי \u0003ל\u0004ענין \u0003כפרה\u0004 עליכם \u0003נתתיו\u0004 לדם כדבר שבקדשים, \u0003ו\u0004אולם \u0003לא ל\u0004ענין \u0003מעילה.\u0004","\u0003ור' יוחנן אמר\u0004 הסבר אחר מדוע אין דין מעילה נוהג בדם, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפסוק זה \"כי הדם \u0003הוא\u0004 בנפש יכפר\", והרי זה בא להורות כי \u0003הוא\u0004 דינו של הדם בזמן ש\u0003לפני כפרה\u0004 (לפני זריקת הדם על המזבח, המכפרת) \u0003כ\u0004דינו של הדם בזמן ש\u0003לאחר כפרה\u0004 (\"בנפש יכפר\"), \u0003מה לאחר כפרה\u0004 — \u0003אין בו\u0004 דין \u0003מעילה\u0004 אם נעשתה מצוותו, \u0003אף לפני כפרה\u0004 — \u0003אין בו\u0004 דין \u0003מעילה.\u0004","ושואלים \u0003ואימא\u0004 \u0005[ואמור]\u0006 להיפך: \u0003\"הוא\"\u0004 — \u0003לאחר כפרה כלפני כפרה, מה לפני כפרה\u0004 — \u0003יש בו מעילה, אף לאחר כפרה\u0004 — \u0003יש בו מעילה!\u0004 ומשיבים: אי אפשר לומר שיהא דין מעילה בדם לאחר כפרה, שכן \u0003אין לך דבר שנעשה\u0004 כבר \u0003מצותו ומועלין בו.\u0004","ותוהים: \u0003ו\u0004האם \u0003לא\u0004 נמצא דבר שנעשה מצוותו ובכל זאת יש בו דין מעילה? \u0003והרי תרומת הדשן\u0004 (שהיה הכהן אוסף כל בוקר בבית המקדש מן האפר שעל המזבח מלוא מחתה ונותנו בצידי המזבח, ושם היה נבלע. שהיה נגנז שם, לבל ישתמשו בו, שכן הוא אסור בהנאה), הרי זה דבר ש\u0003נעשה מצותו, ו\u0004בכל זאת \u0003מועלין בו, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \"והרים את הדשן אשר תאכל האש את העולה על המזבח \u0003ושמו אצל המזבח\"\u0004 (ויקרא ו, ג), לומר שצריך להשאירו שם, ואם נוטלו משם הרי הוא מועל! ומשיבים: אין ללמוד מתרומת הדשן שדבר שנעשה מצוותו מועלים בו,","\u0003משום דהואי\u0004 \u0005[שהריהם]\u0006 \u0003תרומת הדשן ו\u0004כן \u0003בגדי כהונה\u0004 (שאף בהם יש דין מעילה, הגם שכבר נעשתה מצוותם. שכן בגדי הכהן הגדול שעבד בהם ביום הכיפורים, טעונים גניזה, ואין משתמשים בהם עוד. \u0003שכן נאמר \"ובא אהרן אל אוהל מועד ופשט את בגדי הבד אשר לבש בבואו אל הקודש והניחם שם\" (שם טז, כג) —\u0004 שיהיו הבגדים מונחים שם בלי שימוש, וכל המשתמש בהם מעל). \u0003שני כתובין הבאין כאחד\u0004 (המלמדים אותו דבר), \u0003ו\u0004כלל הוא כי \u0003כל שני כתובין הבאין כאחד אין מלמדין.\u0004 ובשאר כל הדברים, כיון שנעשתה מצוותם, שוב אין מועלים בהם.","ומקשים: \u0003הניחא לרבנן דאמרי\u0004 \u0005[זה נוח ל\u0006שיטת \u0005חכמים שאומרים]\u0006 כי הכתוב \u0003\"והניחם שם\"\u0004 — \u0003מלמד שטעונין\u0004 הבגדים \u0003גניזה,\u0004 שאין משתמשים בהם שוב. \u0003אלא לר' דוסא\u0004 ש\u0003אמר\u0004 כי הכוונה היא רק לענין זה \u0003שלא ישתמש בהן\u0004 הכהן הגדול שוב \u0003ליום הכפורים אחר,\u0004 אבל כהן הדיוט רשאי להשתמש בהם, ולשיטתו אין דין מעילה בבגדים הללו, ונשארה איפוא רק תרומת הדשן כמי שנעשתה מצוותה ואף על פי כן מועלים בה, ואין כאן שני כתובים המלמדים כאחד, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 מדוע אין לומדים מתרומת הדשן שיש דין מעילה גם בדבר שנעשתה מצוותו, וכדם לאחר כפרה?","\u0003אלא\u0004 צריך לומר כי אין למדים מתרומת הדשן \u0003משום דהואי\u0004 \u0005[שהריהם]\u0006 \u0003תרומת הדשן ועגלה ערופה\u0004 (שאסורה העגלה בהנאה לאחר שנערפה ונעשתה מצוותה) \u0003שני כתובים הבאין כאחד, וכל שני כתובים הבאין כאחד אין מלמדין.\u0004","ומקשים עוד: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ששני כתובים הבאים כאחד \u0003אין מלמדין, אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ששני כתובים הבאים כאחד \u0003מלמדין, מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 ומדוע לא נלמד מהם לענין מעילה בדם לאחר כפרה? ומשיבים: טעם הדבר הוא משום ש\u0003תרי\u0004 \u0005[שני]\u0006"],["\u0003מיעוטי כתיבי\u0004 \u0005[מיעוטים כתובים]\u0006 בהלכות אלה (תרומת הדשן ועגלה ערופה), שכן \u0003הכא כתיב\u0004 \u0005[כאן,\u0006 בתרומת הדשן, \u0005נאמר]\u0006 \"ושמו אצל המזבח\" (ויקרא ו, ג), והלשון \u0003\"ושמו\"\u0004 מורה שרק בזה יש דין מעילה בדבר שנעשתה בו מצוותו, מה שאין כן בשאר דברים שנעשתה בהם מצוותם. וכמו כן \u0003התם כתיב\u0004 \u0005[שם,\u0006 בעגלה ערופה, \u0005נאמר]\u0006 \"ירחצו את ידיהם על העגלה הערופה בנחל\" (דברים כא, ו), ובאה המלה \u0003\"הערופה\",\u0004 ללמד שדווקא בזו יש דין מעילה אף שנעשתה מצוותה, מה שאין כן בשאר דברים שנעשתה בהם מצוותם. וכיון שיש בכתובים הללו מיעוטים — אין הם מלמדים. ושואלים: למעלה הובאו דרשות עולא והחכם מבית מדרשו של ר' ישמעאל ור' \u0003יוחנן, ללמד שאין בדם מעילה וכל אחד דרש מכתוב אחר (בפסוק\u0004 \"כי נפש הבשר בדם הוא ואני נתתיו לכם על המזבח לכפר על נפשותיכם כי הדם הוא בנפש יכפר\". ויקרא יז, יא), \u0003ותלתא קראי\u0004 \u0005[ושלושה מקראות]\u0006 \u0003למה לי\u0004 להשמיענו שאין איסור מעילה \u0003בדם?\u0004","","ומשיבים: מקרא \u0003חד למעוטי\u0004 \u0005[אחד\u0006 בא \u0005למעט]\u0006 דם \u0003מ\u0004דין \u0003נותר\u0004 (שאם שגג ואכל מן הדם שהיה נותר, אין הוא חייב אלא משום נותר, ולא משום דם). \u0003ו\u0004מקרא \u0003חד למעוטי\u0004 \u0005[אחד\u0006 בא \u0005למעט]\u0006 דם \u0003מ\u0004דין \u0003מעילה, ו\u0004מקרא \u0003חד למעוטי\u0004 \u0005[אחד\u0006 בא \u0005למעט]\u0006 דם \u0003מ\u0004איסור של אכילת דבר ב\u0003טומאה\u0004 (שאם אכל דם קדשים בהיותו טמא, אין הוא חייב על כך).","\u0003אבל\u0004 למעט דם \u0003מ\u0004דין \u0003פגול לא צריך קרא\u0004 \u0005[מקרא]\u0006 ללמד כן, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 כי \u0003כל\u0004 דבר הקדש \u0003שיש לו מתירין, בין לאדם\u0004 (לאכילה), \u0003ובין למזבח\u0004 (להקרבה) — \u0003חייבין עליו משום פגול,\u0004 אבל \u0003דם גופיה\u0004 \u0005[עצמו]\u0006 \u0003מתיר הוא,\u0004 ולכן אינו נעשה פיגול.","","כל דברי המאכל (\"אוכלים\") שנטמאו (בנגיעת שרץ מת בהם), והריהם מטמאים עתה אוכלים ומשקים, אינם מטמאים אלא אם כן יש שיעור כביצה. ולענין זה נקבע כי אם בחתיכת הבשר עצמה שנטמאה אין שיעור כביצה, ואולם עם \u0003העור\u0004 אליו היא דבוקה (אף שהוא עצמו אינו ראוי לאכילה), יש כדי להשלים לשיעור כביצה; \u0003ו\u0004כן אם עם \u0003הרוטב\u0004 (המרק הקרוש ומחובר לבשר, שאינו נאכל כשלעצמו), יש כדי להשלים לשיעור כביצה; \u0003ו\u0004כן אם עם \u0003הקיפה\u0004 (התבלינים השונים, כבצל וכשום, הניתנים בבשר בעת הבישול, להשבחת טעמו, ומתערב בהם מקצת מן הבשר, והם אינם נאכלים כשלעצמם), יש כדי להשלים לשיעור כביצה; \u0003ו\u0004כן \u0003האלל\u0004 (שאריות הבשר הדבוקות בעור בעת שנפשט מן הבשר); \u0003ו\u0004כן \u0003העצמות\u0004 שיש בהם מח שהוא אוכל, והעצם שומרת עליו; \u0003ו\u0004כן \u0003הגידין\u0004 שאין הם נאכלים כשלעצמם; \u0003ו\u0004כן \u0003הקרנים\u0004 בחלקן התחתון (הסמוך לבשר), במקום בו הם נחתכים ויוצא מהן דם; \u0003ו\u0004כן \u0003הטלפים\u0004 במקום בו הם נחתכים ויוצא מהם דם — כל אלה אף שאין הם עצמם מטמאים (אף שיש בהם עצמם שיעור כביצה, שהרי אין הם נאכלים כשלעצמם), מכל מקום הריהם","\u0003מצטרפין\u0004 לבשר להשלים לשיעור כביצה \u0003לטמא טומאת אוכלין. אבל\u0004 הם \u0003לא\u0004 מצטרפים לבשר נבילה שאין בו עצמו כשיעור כזית, לכדי שיעור כזית, שהוא השיעור המטמא ב\u0003טומאת נבלות.\u0004","\u0003כיוצא בו\u0004 לענין בשר המטמא טומאת אוכלים (אם נטמא בנגיעת שרץ מת בו) ואין הוא מטמא מטמא טומאת נבילות (אם הוא בשר נבילה), \u0003השוחט בהמה טמאה ל\u0004צורך \u0003ה\u0004\u0003גוי, ו\u0004היתה הבהמה עדיין חיה ו\u0003מפרכסת\u0004 אם נגע בה שרץ מת, הריהי \u0003מטמאה טומאת אוכלין, אבל לא טומאת נבלות עד שתמות, או עד שיתיז את ראשה\u0004 (אף שהיא עדיין מפרכסת), שאז היא מטמאה טומאת נבילה. מעתה, שראינו כי יש דברים המטמאים בטומאת אוכלים ואין הם מטמאים בטומאת נבילות, נמצאנו למדים כי \u0003ריבה\u0004 (הוסיף) הכתוב \u0003לטמא\u0004 ב\u0003טומאת אוכלין\u0004 יותר \u0003ממה שריבה\u0004 (שהוסיף) \u0003לטמא\u0004 ב\u0003טומאת נבלות.\u0004","ובענין ששנינו למעלה כי אין האלל מצטרף לבשר לטמא טומאת נבילות, \u0003ר' יהודה אומר\u0004 כי \u0003האלל המכונס\u0004 למקום אחד בזמן הפשטו, \u0003אם יש בו כזית במקום אחד\u0004 — הרי זה מטמא בטומאת נבילות. ומי שנגע בו ולאחר מכן נכנס למקדש או שאכל מן הקודש \u0003חייב עליו\u0004 עונש כרת, ככל טמא. שכן אדם זה שכינס את האלל, גילה דעתו שהריהו נחשב אצלו כבשר. שנינו במשנתנו כי העור אף שהוא עצמו אינו נאכל, ואולם \u0003בשל היותו מחובר אל האוכל כדבר המגן עליו (\"שומר\"), הריהו מצטרף אליו להשלים שיעורו לטומאת אוכלים, אך אינו מצטרף להשלים שיעורו\u0004 לטומאת נבילות. וכן \u0003תנינא להא\u0004 \u0005[שנינו את זה]\u0006 בבריתא, ובאופן מפורט, \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]:\u0006 יש דברים שהריהם \u0003שומרים\u0004 על דברי האוכל, ולכך הם מצטרפים אליהם \u0003ל\u0004ענין \u0003טומאה קלה\u0004 כטומאת אוכלים (שמטמאה דברי מאכל בלבד, ולא אדם וכלים). \u0003ו\u0004אולם \u0003לא\u0004 נאמר דין \u0003שומרים ל\u0004ענין \u0003טומאה חמורה\u0004 כטומאת נבילה (שמטמאה אף אדם וכלים). ומסבירים: שנוהג דין \u0003שומרים ל\u0004ענין \u0003טומאה קלה מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דתנא דבי\u0004 \u0005[ש\u0006כן \u0005שנה\u0006 החכם של \u0005בית]\u0006 מדרשו של \u0003ר' ישמעאל\u0004 על הכתוב בדין קבלת טומאה \"וכי יפול מנבלתם על כל זרע זרוע אשר יזרע טהור הוא. וכי יותן מים על זרע ונפל מנבלתם עליו טמא הוא לכם\" (ויקרא יא, לז—לח): בא הכתוב \u0003\"על כל זרע זרוע\"\u0004 ללמדנו כי דבר המאכל הנטמא הריהו \u0003כדרך שבני אדם מוציאין לזריעה,\u0004 והרי זה כ\u0003חטה בקליפתה, ו\u0004כ\u0003שעורה בקליפתה, ועדשים בקליפתן.\u0004 ומכאן נלמד שיש דין שומרים לענין טומאה קלה. \u0003ו\u0004ש\u0003לא\u0004 נוהג דין \u0003שומרים ל\u0004ענין \u0003טומאה חמורה מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]\u0006 על הכתוב בטומאת נבילה \"וכי ימות מן \u0003הבהמה אשר היא לכם לאכלה הנוגע בנבלתה יטמא עד הערב\"\u0004 (שם, לט): בא הכתוב \u0003\"בנבלתה\"\u0004 להורות: דווקא הנוגע בבשר הנבילה עצמה הוא שנטמא, \u0003ולא\u0004 הנוגע \u0003בעור שאין עליו כזית בשר\u0004 שאין זה מטמא.","","",""],["ודנים: \u0003יכול\u0004 נלמד מן הכתוב כי דווקא הנוגע בבשר הנבלה עצמה, הוא הנטמא בטומאת נבילה, ואולם \u0003הנוגע\u0004 בעור הנבילה, הנמצא \u0003כנגד בשר מאחוריו,\u0004 ואינו נוגע בבשר, \u0003לא יהא טמא?\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \"הנוגע בנבלתה יטמא עד הערב\" (ויקרא יא, לט), \u0003\"יטמא\"\u0004 — להורות כי גם הנוגע באופן זה הריהו טמא.","ותוהים: \u0003מאי קאמר\u0004 \u0005[מה הוא,\u0006 התנא שבברייתא זו \u0005אומר]?\u0006 שהרי נראים דבריו כסותרים זה את זה. שבתחילה אמר כי העור אינו מטמא בטומאת נבילה, ולאחר מכן אמר כי הנוגע בעור נטמא בטומאת נבילה! \u0003אמר רבא\u0004 בתשובה, \u0003ואמרי לה\u0004 \u0005[ויש האומרים אותה]\u0006 בשם החכם \u0003כדי:\u0004 \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא, ויש להשלימה, \u0005וכך יש לשנותה]:\u0006 מן הכתוב \"הנוגע \u0003בנבלתה\"\u0004 למדים אנו כי דווקא הנוגע בבשר הנבילה הוא שנטמא, \u0003ולא\u0004 הנוגע \u0003בעור שאין עליו כזית בשר, ו\u0004ה\u0003עור משלימו לכזית.\u0004 שכן אין העור מצטרף לבשר לענין טומאת נבילה.","\u0003יכול\u0004 יהא הדין \u0003שאני מוציא\u0004 מכלל טומאת נבילה \u0003אף\u0004 את ה\u0003עור שיש עליו כזית בשר,\u0004 ו\u0003הנוגע כנגד בשר מאחוריו, יכול לא יהא טמא, ואפילו מעשה \"יד\" נמי לא עביד\u0004 \u0005[גם כן לא יעשה]\u0006 העור, שהוא לא ייחשב כ\"יד\" לבשר לענין זה שייטמא הנוגע בו כאילו נגע בבשר!","לכך \u0003תלמוד לומר \"יטמא\".\u0004 שאף שאין השומר מצטרף לבשר להשלימו לשיעור \u0003כזית לטומאת נבילה, הריהו משמש כ\"יד\" לטומאה. ולכן אם יש בבשר כשיעור המטמא (כזית), ונגע האדם בעור אף שלא נגע בבשר עצמו — הריהו נטמא בכך.\u0004","למעלה הובאו ענייניהם של ה\"יד\" ושל ה\"שומר\" לדין הטומאה, ומרחיבים דבר זה. \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה בתחילת מסכת עוקצין\u0005]\u0006 בדיני ה\"יד\" לאוכל וה\"שומר\" לאוכל, ומה דינו של חלק אחר הדבוק לאוכל, ואולם אין הוא \"יד\" ולא \"שומר\": \u0003כל\u0004 חלק בדבר מאכל \u0003שהוא\u0004 משמש כ\u0003יד\u0004 לדבר המאכל, שאדם אוחז בו בשעת אכילתו את הדבר, \u0003ו\u0004הוא \u0003לא\u0004 משמש כ\u0003שומר\u0004 (כדבר המגן על דבר המאכל שלא יתקלקל) — הרי הוא \u0003טמא\u0004 על ידי המאכל, שאם נגעה טומאה ביד המאכל נטמא אף המאכל עצמו. \u0003ו\u0004כמו כן היד \u0003מטמא\u0004 את דבר המאכל, שאם היה המאכל טמא ונגעה ידו במאכל אחר — טמא. \u0003ו\u0004היד \u0003אינו מצטרף\u0004 לדבר המאכל להשלים לכשיעור הראוי כדי לטמא אחרים.","ואילו כל שהוא משמש כ\u0003שומר\u0004 לדבר המאכל, \u0003ואף על פי שאינו\u0004 משמש כ\u0003יד\u0004 — הריהו \u0003טמא\u0004 על ידי דבר המאכל, \u0003ו\u0004כמו כן הריהו \u0003מטמא\u0004 את דבר המאכל, \u0003ו\u0004אולם (שלא כ\"יד\") הוא גם \u0003מצטרף\u0004 לדבר המאכל להשלימו לשיעור הראוי לטומאה. וכל דבר שהוא \u0003לא יד ולא שומר\u0004 אף שהוא צמוד לדבר המאכל — אינו \u0003לא טמא\u0004 על ידי דבר המאכל, \u0003ולא מטמא\u0004 את דבר המאכל, ובוודאי שאינו מצטרף אליו להשלימו לשיעור הראוי לטומאה.","ומבררים: דין זה של \u0003ידות\u0004 שמביאות את הטומאה אל דבר המאכל (\"מכנסת\") וכן שהריהן מטמאות במגען את הנוגע בהן \u0003היכא כתיבי\u0004 \u0005[היכן\u0006 הם \u0005כתובים]?\u0006 ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדין קבלת הטומאה בטומאת אוכלים \u0003\"וכי יותן מים על זרע ונפל מנבלתם עליו טמא הוא לכם\"\u0004 (שם, לח), ובאה המלה \u0003\"לכם\"\u0004 ללמדנו: \u0003לכל שבצרכיכם,\u0004 שכל דבר שהמאכל צריך לו, מקבל טומאה כמוהו, וטמא ממנו ומטמא אותו, ומכאן נלמד \u0003לרבות את הידות,\u0004 שהן לצורך השימוש במאכל. שכיון שנטמא המאכל מן השרץ המת, אף היד נטמאה עמו.","\u0003ו\u0004עוד \u0003כתיב\u0004 \u0005[נאמר]\u0006 באותה פרשה בטומאת נבילה \u0003\"וכי ימות מן הבהמה אשר היא לכם\u0004 לאכלה הנוגע בנבלתה יטמא עד הערב\" (שם, לט), ובאה המלה \u0003\"לכם\"\u0004 ללמדנו: \u0003לכל שבצרכיכם,\u0004 שכל דבר שדבר המאכל צריך לו הריהו מטמא את האחרים. שכל שנגע ביד, הריהו נטמא בכך כנוגע בנבילה עצמה, ומכאן נלמד \u0003לרבות את הידות.\u0004 ומעתה יש לנו לימוד בדין \u0003יד\u0004 לענין \u0003להכניס\u0004 טומאה \u0003ו\u0004כן יש לנו לימוד לענין \u0003להוציא\u0004 טומאה.","ובאשר ל\u0003שומר להכניס ולהוציא\u0004 — \u0003לא צריך קרא\u0004 \u0005[מקרא]\u0006 מיוחד, ללמדנו כן, שהרי ב\u0003קל וחומר מיד\u0004 הוא \u0003אתי\u0004 \u0005[בא,\u0006 נלמד\u0005].\u0006 ובאופן זה: \u0003ומה יד,\u0004 שהיא קלה בהשוואה לשומר, \u0003ש\u0004הרי \u0003אינה מגינה\u0004 על דבר המאכל — \u0003מכנסת ומוציאה\u0004 את הטומאה. \u0003שומר\u0004 שהוא חמור בהשוואה ליד, שהרי הוא מגן על דבר המאכל — \u0003לא כל שכן\u0004 שהוא מכניס ומוציא את הטומאה!","ומעתה יש לשואל: \u0003שומר דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 שנחשב כדבר המאכל לענין הטומאה (וכדרך שלמדנו בעמוד הקודם מן הכתוב \"על כל זרע זרוע... טמא הוא לכם\". שם, לז—לח), \u0003למה לי\u0004 לכתבו? \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהרי זה להשמיענו לענין \u0003לצרף,\u0004 שמצטרף השומר לדבר המאכל לכלל שיעור המטמא.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 את הדרשות באופן שונה: \u0003יד,\u0004 שקלה בדינה מן השומר — הריהי נחשבת כדבר המאכל רק לענין \u0003להכניס\u0004 טומאה, \u0003ולא\u0004 לענין \u0003להוציא\u0004 טומאה. ואילו \u0003שומר,\u0004 שחמור בדינו מן היד — הריהו נחשב כדבר המאכל הן לענין \u0003להכניס ו\u0004הן לענין \u0003להוציא, אבל יד\u0004 לענין \u0003להוציא, ושומר\u0004 לענין \u0003לצרף\u0004 — \u0003לא!\u0004","ומשיבים: שתהא ה\u0003יד\u0004 \u0003נחשבת כדבר המאכל רק\u0004 \u0003להכניס\u0004 טומאה, \u0003ולא להוציא, לא מצית אמרת\u0004 \u0005[אין אתה יכול לומר],\u0006 שהרי סברה \u0003היא:\u0004 \u0003השתא עיולי מעיילא\u0004 \u0005[עכשיו,\u0006 שאתה אומר כי היא \u0005מכניסה\u0006 את הטומאה אל דבר המאכל שהוא טהור\u0005],\u0006 \u0003אפוקי מיבעיא\u0004 \u0005[\u0006שהיא \u0005מוציאה\u0006 את הטומאה מדבר המאכל הטמא לטמא אחרים \u0005נצרך\u0006 לומר\u0005]?!\u0006 הרי שיד מכניסה ומוציאה, ואילו שומר מכניס ומוציא (בקל וחומר מיד), ואף הריהו מצטרף.","ושבים ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: ה\u0003יד,\u0004 שהיא קלה בדינה מן השומר — נחשבת כדבר המאכל רק לענין \u0003להוציא\u0004 טומאה, \u0003ולא\u0004 לענין \u0003להכניס\u0004 אותה. ואילו ה\u0003שומר,\u0004 שהוא חמור בדינו מן היד — נחשב כדבר המאכל הן לענין \u0003להוציא ו\u0004הן לענין \u0003להכניס, אבל יד\u0004 לענין \u0003להכניס ושומר\u0004 לענין \u0003לצרף\u0004 — \u0003לא!\u0004","ומשיבים: אין לומר כן, כיון שיש לנו לימוד לענין \u0003יד יתירא\u0004 \u0005[יתר,\u0006 נוסף\u0005].\u0006 שכן \u0003כתיב\u0004 \u0005[נאמר]\u0006 באותה פרשה בדין טומאת כלים \"וכל אשר יפול מנבלתם עליו יטמא \u0003תנור וכירים יותץ\u0004 טמאים הם וטמאים יהיו לכם\" (שם, לה), ובאה המלה","\u0003\"לכם\"\u0004 — ללמדנו: \u0003לכל שבצרכיכם,\u0004 שכל דבר שהכלי צריך לו, מקבל טומאה כמוהו, וטמא ממנו ומטמא אותו, ומכאן נלמד \u0003לרבות את הידות,\u0004 שהן לצורך השימוש בכלי. שכיון שנטמא הכלי מן השרץ המת, אף היד נטמאה עמו. ומעתה נמצא כי שני לימודים יש לנו לידות, האחד לענין הכנסת טומאה והשני לענין הוצאת טומאה. ואילו שומר לענין הכנסה והוצאה אינו צריך לימוד (שנלמד בקל וחומר מידות), ובא הלימוד מ\"על כל זרע זרוע\" לענין הצטרפות לכדי שיעור.","ושואלים על כך: מבין שני המקראות הללו, בטומאת אוכלים ובטומאת כלים, \u0003הי מינייהו מייתר\u0004 \u0005[מי מהם מיותר],\u0006 שבאת לדורשו לענין יד להכנסת הטומאה? שהרי נצרכו שניהם להיכתב.","שכן אם \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003בזרעים\u0004 (בטומאת אוכלים) בלבד, \u0003וליתו הנך מינייהו\u0004 \u0005[ויבואו,\u0006 יילמדו \u0005אלה,\u0006 טומאת כלים וטומאת נבילה \u0005מהן]\u0006 — אין לומר כן, כיון שאפשר לדחות את הלימוד: \u0003מה לזרעים\u0004 (טומאת אוכלים), שיש בהם צד חמור בהשוואה לאלה, \u0003שכן טומאתן מרובה,\u0004 שהרי הם מקבלים טומאה אף מוולד הטומאה, תאמר בכלים שאין טומאתם מרובה, שאינם מקבלים טומאה אלא מאב הטומאה. וכן מרובה טומאת אוכלים מטומאת נבילה, כדרך ששנינו במשנתנו שריבה לטמא טומאת אוכלים מטומאת נבילה!","ואם \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \u0003בתנור\u0004 (בטומאת כלים), \u0003וליתי הנך מיניה\u0004 \u0005[ויבואו,\u0006 יילמדו \u0005אלה,\u0006 טומאת אוכלים וטומאת נבילה \u0005מהן]\u0006 — יש לדחות: \u0003מה לתנור,\u0004 שיש בו צד חמור בהשוואה לאלה, \u0003שכן מטמא\u0004 דברי מאכל אפילו \u0003מאוירו,\u0004 ולא רק במגע בו. מה שאין כן באלה!","ואם \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \u0003בנבלה, וליתי הנך מינה\u0004 \u0005[ויבואו,\u0006 יילמדו \u0005אלה,\u0006 טומאת אוכלים וטומאת כלים \u0005ממנה]\u0006 — יש לדחות: \u0003מה לנבלה\u0004 שיש בה כמה צדדים של חומרה בהשוואה לאלה, \u0003שכן\u0004 היא \u0003מטמאה אדם, ו\u0004כן שהיא \u0003מטמאה\u0004 \u0003במשא\u0004 (אם נושא אותה גם בלי לנגוע בה), \u0003ו\u0004עוד שה\u0003טומאה יוצאה מגופה\u0004 ואינה באה אליה מבחוץ!","ומשיבים: אכן \u0003חדא מחדא לא אתיא\u0004 \u0005[אחת מאחת אינה באה,\u0006 נלמדת\u0005],\u0006 שאי אפשר ללומדה מהלכה אחת, ואולם עדיין מיותר הוא כתוב אחד, שכן יש אפשרות ש\u0003תיתי חדא מתרתי\u0004 \u0005[שתבוא,\u0006 תילמד הלכה \u0005אחת משתיים].\u0006","ושואלים על כך: \u0003הי תיתי\u0004 \u0005[איך תבוא,\u0006 תילמד אחת משתים\u0005]?\u0006 \u0003לא לכתוב רחמנא\u0004 \u0005[שלא תכתוב התורה]\u0006 \u0003בזרעים\u0004 (בטומאת אוכלים), אלא רק בטומאת כלים וטומאת נבילה, \u0003ותיתי מהנך\u0004 \u0005[ושתבוא,\u0006 תילמד \u0005מאלה,\u0006 טומאת כלים וטומאת נבילה\u0005]\u0006 — יש לדחות: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן\u0004 יש בהן צד חמור שאין בטומאת אוכלים, שהריהן \u0003מטמאין\u0004 אף \u0003שלא בהכשר,\u0004 שאין צריך להכשיר אותם תחילה (בנתינת משקה עליהם) לקבל טומאה כדי שייטמאו ויטמאו, \u0003תאמר בזרעים\u0004 הקלים בדינם, \u0003ש\u0004הרי \u0003אין\u0004 הם \u0003מטמאין אלא בהכשר!\u0004","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 אין זו פירכה, \u0003שכן\u0004 \u0003פירות שלא הוכשרו, כתנור שלא נגמרה מלאכתו דמי\u0004 \u0005[נחשב],\u0006 ואף תנור כזה אינו מקבל טומאה.","\u0003אלא פריך הכי\u0004 \u0005[הקשה כך]:\u0006 \u0003מה להנך\u0004 \u0005[לאלה]\u0006 שיש בהם צד חמור בהשוואה לטומאת אוכלים, \u0003שכן\u0004 הם \u0003מטמאין\u0004 אף \u0003שלא בנגיעה,\u0004 שהרי תנור נטמא מן השרץ הנמצא באוירו ובלא שנגע בו. וכן הנבילה נטמאת מאליה, בלא דבר חיצוני שנגע בה. \u0003תאמר בזרעים\u0004 הקלים בדינם בהשוואה לאלה, \u0003ש\u0004הרי \u0003אין\u0004 הם \u0003מטמאין אלא בנגיעה!\u0004","ואם \u0003לא לכתוב רחמנא\u0004 \u0005[לא תכתוב התורה]\u0006 \u0003בתנור,\u0004 אלא רק בטומאת אוכלים ובטומאת נבילה, \u0003ותיתי מהנך\u0004 \u0005[ותילמד מאלה,\u0006 טומאת אוכלים וטומאת נבילה\u0005]\u0006 — יש לדחות: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 שיש בהם צד חמור בהשוואה לטומאת כלים, \u0003שכן\u0004 הם מין \u0003אוכל,\u0004 ואילו תנור ושאר כלים אינם מין אוכל!","ואם תאמר כי \u0003לא לכתוב רחמנא\u0004 \u0005[לא תכתוב התורה]\u0006 \u0003בנבלה\u0004 אלא רק בטומאת אוכלים ובטומאת כלים, \u0003ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד טומאת נבילה \u0005מאלה]\u0006 — \u0003אין הכי נמי\u0004 \u0005[כן הוא גם כן],\u0006 אפשר ללמוד כך. ושואלים: \u0003אלא\u0004 מעתה שלמדנו לענין טומאת נבילה, לימוד זה של \u0003יד\u0004 בכתוב שבטומאת \u0003נבלה למה לי?\u0004 ומשיבים: \u0003אם אינו ענין\u0004 ללמדנו \u0003ליד ל\u0004טומאת \u0003נבלה, תנהו ענין ליד דעלמא\u0004 \u0005[בכלל]\u0006 שבענייני אוכלים.","ומעתה נסכם: הרי לפנינו לימוד לענין \u0003יד להכניס\u0004 טומאה, ו\u0003יד להוציא\u0004 טומאה, ו\u0003שומר\u0004 נלמד בקל וחומר מיד שאף הוא מכניס ומוציא, ובא הלימוד (\"על כל זרע זרוע\") לענין \u0003לצרף\u0004 את שיעורו לגוף הדבר הנטמא.","ושואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 \u0003יד\u0004 האמור בטומאת \u0003נבלה אצטריך\u0004 \u0005[הוצרך],\u0006 \u0003דאי לא כתב רחמנא\u0004 \u0005[ש\u0006כן \u0005אם לא היתה כותבת התורה]\u0006 \u0003בנבלה, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003דיו לבא מן הדין\u0004 (הלכה הנלמדת ממידת גזירה שווה, כדין יד בטומאת נבילה הנלמדת מטומאת אוכלים וטומאת כלים) \u0003להיות כנדון\u0004 (כהלכות המלמדות בגזירה שווה). ומעתה הייתי אומר כי \u0003מה הנך\u0004 \u0005[אלה,\u0006 אוכלים וכלים\u0005]\u0006 היד שלהן \u0003לא מטמא אדם, אף\u0004 יד ה\u0003נבלה לא מטמאה אדם!\u0004","\u0003אלא\u0004 יש לומר כי \u0003יד\u0004 בטומאת \u0003נבלה\u0004 אכן \u0003מיצרך צריך\u0004 \u0005[צריכה\u0006 להיכתב\u0005],\u0006 \u0003ו\u0004אולם הכתוב המלמד לענין \u0003שומר\u0004 בטומאת \u0003נבלה הוא\u0004 ש\u0003לא צריך.\u0004 ומעתה יש לברר: \u0003למאי הלכתא כתביה רחמנא\u0004 \u0005[למה,\u0006 לאיזו הלכה \u0005כתבה אותו התורה]?\u0006 \u0003אי לאיצטרופי\u0004 \u0005[אם ל\u0006ענין \u0005צירוף]\u0006 השומר עם הבשר להשלימו לשיעור כזית לטמא — הרי כבר \u0003אמרת\u0004 כי השומר \u0003לא מצטרף,\u0004 וכפי שלמדנו כי מתמעטים השומרים מטומאת נבילה. \u0003ו\u0004אם לענין \u0003להוציא\u0004 את הטומאה — אף לכך אין צורך בכתוב, שהרי במידת \u0003קל וחומר מיד\u0004 הוא \u0003אתי\u0004 \u0005[בא,\u0006 נלמד\u0005],\u0006","\u0003אלא, אם אין ענין לשומר דנבלה, תנהו ענין ליד\u0004 של \u0003טומאת\u0004 \u0003נבלה, ואם אינו ענין ליד\u0004 של טומאת \u0003נבלה, תנהו ענין ליד דעלמא\u0004 \u0005[בכלל].\u0006 ומעתה נסכם: נמצאנו למדים \u0003יד\u0004 לענין \u0003להוציא,\u0004 ו\u0003יד\u0004 לענין \u0003להכניס, ושומר\u0004 לענין \u0003לצרף.\u0004"],["\u0003ו\u0004שואלים על הסבר זה: מדוע אומר אתה כי אם אינו ענין לשומר בענין טומאת נבילה תנהו ענין ליד בכלל, \u0003אימא\u0004 \u0005[אמור]\u0006 באופן אחר: \u0003אם אינו ענין לשומר\u0004 בטומאת \u0003נבלה תנהו ענין לשומר דעלמא\u0004 \u0005[בכלל],\u0006 לכל דברי מאכל. ואף שכבר למדנו מן הכתוב \"על כל זרע זרוע\" (ויקרא יא, לז) לענין שומר בכלל האוכלים, עדיין נצרכים אנו לשני לימודים: האחד בדין \u0003שומר\u0004 לענין \u0003להכניס\u0004 את הטומאה לדבר המאכל, \u0003ו\u0004השני בדין \u0003שומר\u0004 לענין \u0003לצרף\u0004 אותו להשלמת שיעור, \u0003אבל\u0004 בדין \u0003יד להכניס\u0004 את הטומאה — \u0003לא\u0004 למדנו, ואין לנו כל מקור המלמדנו כן!","\u0003אלא\u0004 כך צריך לומר: אכן אין למדים דין יד לענין הכנסת טומאה מהכתוב המיותר הנאמר בטומאת נבילה, ויש לשוב לאופן ההסבר הנאמר למעלה: שכן למדנו יד לענין הכנסת הטומאה מן הכתוב \"לכם\" האמור בטומאת זרעים, וביחס למה ששאלנו על כך שמא בא הכתוב הזה ללמד לענין יד להוצאה ולא לענין יד להכנסה — אין זה קשה, כי \u0003מעיקרא\u0004 \u0005[מתחילה,\u0006 ביסודו\u0005]\u0006 של הכתוב \"וכי יותן מים על זרע ונפל מנבלתם עליו טמא הוא לכם\" (שם, לח), \u0003כי כתיבא\u0004 \u0005[כאשר\u0006 הוא \u0005נאמר]\u0006 ללמדנו דין \u0003יד,\u0004 לענין \u0003הכנסה\u0004 של הטומאה \u0003כתיבא\u0004 \u0005[\u0006הוא ש\u0005נאמר].\u0006 ומעתה יש איפוא לסכם ולומר כי יד לענין הוצאה נלמדת בקל וחומר מיד לענין הכנסה, וכן דין שומר בטומאת אוכלים להכנסה ולהוצאה נלמד בקל וחומר מדין יד, ואילו דין שומר בטומאת אוכלים לענין צירוף נלמד מן הכתוב \"על כל זרע זרוע\".","ומקשים: \u0003אלא\u0004 מעתה, הלימוד לענין \u0003שומר\u0004 בטומאת \u0003נבלה\u0004 הנלמד מן הכתוב \"יטמא\", \u0003למה לי?\u0004 ומשיבים: נצרך הדבר \u0003לגופיה\u0004 \u0005[לגופו],\u0006 ללמדנו שנוהג דין שומר בטומאת נבילה.","ושואלים על כך: \u0003ולמאי\u0004 \u0005[ולמה,\u0006 לאיזה ענין\u0005]\u0006 נצרך להשמיענו לגופו? \u0003אי\u0004 \u0005[אם]\u0006 תאמר שבא \u0003ל\u0004ענין \u0003אצטרופי\u0004 \u0005[צירוף]\u0006 של השומר להשלמת שיעור טומאת נבילה בכזית — הרי כבר \u0003אמרת\u0004 במשנתנו כי השומר \u0003לא מצטרף\u0004 להשלים לשיעור טומאת נבילה. \u0003אי\u0004 \u0005[אם]\u0006 תאמר שבא לענין \u0003להכניס\u0004 טומאה \u0003ולהוציא\u0004 אותה — אין צורך בכתוב מיוחד להשמיענו כן, שהרי בדרך לימוד של \u0003קל וחומר מיד אתיא\u0004 \u0005[באה,\u0006 נלמד הדבר\u0005].\u0006 שכן חמור הוא שומר מן היד (שכן היד אינה מגינה, ואילו השומר מגן)! ומשיבים: אף שבא הדבר מקל וחומר, \u0003מילתא דאתיא\u0004 \u0005[דבר שבא,\u0006 יכול להילמד\u0005]\u0006 \u0003בקל וחומר,\u0004 בכל זאת יש ו\u0003טרח וכתב לה קרא\u0004 \u0005[טורח וכותב אותו המקרא]\u0006 ואין זה נחשב לייתור. ומעתה יודעים אנו שכדרך שהיד מוציאה את הטומאה, כן השומר מוציא את הטומאה, מדרשת הכתוב.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר שהתורה משמיעתנו גם דבר שיכול להילמד במידת קל וחומר, מעתה \u0003שומר דעלמא\u0004 \u0005[בכלל,\u0006 בטומאת אוכלים\u0005],\u0006 שאמרנו בו מקודם כי משום שאין צורך להשמיענו לענין הכנסה והוצאה (כי נלמד הדבר בקל וחומר מיד), יש לומר כי בא הכתוב ללמדנו דין צירוף. ועתה \u0003אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כך: אף בשומר בא הכתוב לענין \u0003להכניס\u0004 טומאה ולהוציאה. \u0003ו\u0004טעם הדבר שנכתב דבר בתורה, אף שהוא נלמד בקל וחומר: כי \u0003מלתא דאתי\u0004 \u0005[ודבר שבא,\u0006 יכול להילמד\u0005]\u0006 \u0003בקל וחומר,\u0004 יש ו\u0003טרח וכתב לה קרא\u0004 \u0005[טורח וכותב אותו המקרא]!\u0006","ואומרים: אף על פי כן, \u0003היכא דאיכא למידרש דרשינן\u0004 \u0005[במקום שאפשר לדרוש\u0006 את המקרא להשמיענו דין חדש, \u0005דורשים אנו],\u0006 ואין אנו אומרים שהפסוק בא רק ללמד מה שאפשר ללמוד בקל וחומר. ועוד מביאים בענין זה כי","\u0003רב חביבא אמר\u0004 בהסבר הדברים שלמדים אנו דין יד להכנסה משומר בטומאת נבילה. שאם אינו ענין לעצמו, שהרי הוא נלמד בקל וחומר מיד בטומאת נבילה, תנהו ענין ליד בטומאת אוכלים, וללמדנו דין יד לענין הכנסת טומאה. ובאשר לשאלה מדוע אין אנו אומרים תנהו ענין לשומר בטומאת אוכלים ולענין הכנסה וגם לענין צירוף — אין לומר כן, כי \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד\u0005]\u0006 הוא דין \u0003שומר\u0004 בטומאת \u0003נבלה, כיון\u0004 שאין הוא מצטרף לבשר להשלים לשיעור טומאה (כדין שומר בטומאת אוכלים), אלא הריהו רק מכניס ומוציא את הטומאה, ונמצא שכ \u0003מעשה יד קא עביד\u0004 \u0005[הוא עושה],\u0006 שהרי גם היד אינה אלא מכניסה ומוציאה את הטומאה, לכך דווקא \u0003איד\u0004 \u0005[על היד]\u0006 ולא על השומר \u0003שדינן ליה\u0004 \u0005[משליכים אנו,\u0006 דנים אנו, \u0005אותו\u0006 כתוב\u0005]\u0006 ללומדו באם אינו ענין לעצמו, תנהו ענין ליד.","למעלה (קיז,ב) הוסבר כי דין שומר לענין צירוף בטומאת אוכלים נלמד מן הכתוב \"על כל זרע זרוע אשר יזרע\", שתוספת הלשון \"אשר יזרע\" באה ללמדנו שדברי האוכל מיטמאים כדרך שבני אדם מוציאים את הזרעים לשדה לזריעה, חיטה בקליפתה ושעורה בקליפתה. ומביאים כי \u0003מתקיף לה\u0004 \u0005[מקשה על כך,\u0006 על דרשה זו\u0005]\u0006 \u0003רב יהודה בר ישמעאל\u0004 מהלכה \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הפיטמא\u0004 (הבליטה שבראש הפרי, במקום בו נשרה ניצתו) \u0003של\u0004 ה\u0003רמון\u0004 — \u0003מצטרפת\u0004 לפרי עצמו, להשלים שיעורו לשיעור כביצה. שהרי הפיטמה הינה שומר לפרי, שאם תינטל יירקב הפרי. \u0003והנץ\u0004 (הפרח, כעין שיער שמסביב לפיטמה) \u0003שלו\u0004 — \u0003אין מצטרף,\u0004 שאין הנץ נחשב שומר לפרי, אלא הוא שומר לשומר.","ויש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 מצטרפת הפיטמה להשלים את שיעור פרי הרימון, והרי \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003כאן\u0004 הכתוב \u0003\"על כל זרע זרוע\u0004 אשר יזרע\", שלמדנו ממנו דין שומר המצטרף משום שדין השומר הוא כדרך שבני אדם מוציאים לזריעה בשדה. \u0003ו\u0004אילו ברימונים \u0003ליכא\u0004 \u0005[אין כאן]\u0006 \"כדרך שבני אדם מוציאים לזריעה\", שהרי אין זורעים את זרעי העצים, אלא נוטעים שתילים. ואם נוטעים עץ רימון — כבר נשרה אותה פיטמה!","\u0003ותו\u0004 \u0005[ועוד]\u0006 יש להקשות על דרשה זו מ\u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנתנו\u0005]\u0006 כי \u0003העור והרוטב והקיפה וכו' מצטרף לטמא טומאת אוכלים, מנלן\u0004 \u0005[מנין לנו]\u0006 שאף בדברי אוכל אלה יש דין שומר, שהרי מן המקרא אנו יודעים רק לענין הדברים הנזרעים!","ומשיבים: \u0003אלא\u0004 יש לומר כי \u0003תלתא קראי כתיבי\u0004 \u0005[שלושה מקראות כתובים]\u0006 בדינו של השומר לענין טומאה (\"זרע\", \"זרוע\", \"יזרע\"): שכן אמר הכתוב \u0003\"על כל זרע זרוע אשר יזרע\",\u0004 מקרא \u0003חד\u0004 \u0005[אחד]\u0006 — \u0003ל\u0004למד עניינו של ה\u0003שומר\u0004 ב\u0003זרעים, ו\u0004מקרא \u0003חד\u0004 \u0005[אחד]\u0006 — \u0003ל\u0004למד עניינו של ה\u0003שומר\u0004 בפירות ה\u0003אילנות,\u0004 ומקרא \u0003אידך\u0004 \u0005[אחר]\u0006 — \u0003ל\u0004למד עניינו של ה\u0003שומר\u0004 ב\u0003בשר וביצים ודגים.\u0004","למעלה הובאו דרשות הכתוב \"וכי יפול מנבלתם על כל זרע זרוע אשר יזרע טהור הוא. וכי יותן מים על זרע ונפל מנבלתם עליו טמא הוא לכם\" (ויקרא יא, לז—לח) המלמדות לענין דין השומר, אכן עיקרו של כתוב זה הוא ללמדנו שטומאת אוכלים נוהגת רק בדבר שהוכשר לקבל טומאה, בירידת מים על הפירות. ובענין זה \u0003אמר רב חייא בר אשי,\u0004 \u0003אמר רב: יש\u0004 דין \u0003יד ל\u0004ענין \u0003טומאה,\u0004 שהיד מכניסה טומאה אל הדבר שהיא משמשת לו יד, וכן מוציאה ממנו טומאה לטמא אחרים, \u0003ו\u0004אולם \u0003אין\u0004 דין \u0003יד להכשר\u0004 האוכל לקבל טומאה על ידה. שאם נפלו מים על היד, ולא על האוכל עצמו — אין האוכל מוכשר בכך לקבל טומאה.","\u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 כי \u0003יש\u0004 דין \u0003יד\u0004 הן \u0003ל\u0004ענין \u0003טומאה ו\u0004הן \u0003ל\u0004ענין \u0003הכשר.\u0004","ומבררים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 ומסבירים: \u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור\u0006 שחלוקים הם ב\u0005סברה],\u0006 \u0003איבעית אימא קרא\u0004 \u0005[אם תרצה אמור\u0006 שחלוקים הם בפירוש ה\u0005מקרא].\u0006","ומפרטים: \u0003איבעית אימא קרא\u0004 \u0005[אם תרצה אמור\u0006 שחלוקים הם בפירוש ה\u0005מקרא],\u0006 שכן \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב, \u0005סבור]\u0006 כי \u0003מקרא נדרש\u0004 רק \u0003לפניו,\u0004 לגבי הענין האמור לפניו, \u0003ולא\u0004 לאמור \u0003לפני פניו.\u0004 ולכן הכתוב \"לכם\" מלמד לענין יד לטומאה (האמורה בפסוק זה עצמו לפניו, \"טמא הוא\"), ואין הוא מלמד לענין הכשר לטומאה (שאמור בתחילת הפסוק \"וכי יותן מים\", שהרי זה \"לפני פניו\").","\u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי \u0003מקרא נדרש לפניו ו\u0004גם \u0003לפני פניו,\u0004 ולכך יש לדרוש מן הכתוב \"לכם\" גם לענין יד להכשר אוכלים לטומאה.","\u0003איבעית אימא סברא\u0004 \u0005[אם תרצה אמור\u0006 שנחלקו ב\u0005סברה],\u0006 שכן \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי ה\u0003הכשר\u0004 לטומאה של האוכלים, \u0003תחלת טומאה הוא,\u0004 ולכן דינו כדין הטומאה, שאף בו יש דין יד. \u0003ו\u0004אילו \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב, \u0005סבור]\u0006 כי ה\u0003הכשר\u0004 לטומאה \u0003לאו\u0004 \u0005[לא]\u0006 \u0003תחלת טומאה הוא.\u0004","ומביאים, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן: כשם שיש יד לטומאה, כך יש יד להכשר\u0004 לטומאה. \u0003וכשם שאין\u0004 הפירות \u0003מקבלין טומאה אלא לכשיתלשו\u0004 ממקומם, שהרי אין הפרי המחובר לקרקע מקבל טומאה, שאם נגעה בו טומאה — אינו נטמא בכך. \u0003כך אין\u0004 הם \u0003מקבלין הכשר אלא עד\u0004 (משעה) \u0003שיתלשו,\u0004 שאם נפלו עליהם מים בעודם מחוברים — אין הם מוכשרים לקבל טומאה.","ועוד מחלוקת בין רב ור' יוחנן בדין יד. \u0003אמר רב: אין יד ל\u0004דבר אוכל ששיעורו \u0003פחות מכזית,\u0004 ולכך אם נגעה טומאה ביד זו — אין היד מכניסה טומאה לאוכל זה, וכמו כן אם היה אוכל זה טמא — אין היד מוציאה ממנו טומאה לטמא אחרים. \u0003ו\u0004כן \u0003אין\u0004 דין \u0003שומר ל\u0004דבר אוכל ששיעורו הוא \u0003פחות מכפול,\u0004 \u0003לא לענין שיצטרף השומר לשיעור כביצה (בטומאת אוכלים), ולא לענין שיכניס או שיוציא טומאה.\u0004","\u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 כי \u0003יש\u0004 דין \u0003יד\u0004 אף \u0003ל\u0004דבר ששיעורו \u0003פחות מכזית, ו\u0004כן \u0003יש\u0004 דין \u0003שומר\u0004 אף \u0003ל\u0004דבר ששיעורו \u0003פחות מכפול.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי שניהם ממה ששנינו: \u0003שתי עצמות\u0004 מת, \u0003ועליהן\u0004 היו \u0003שני חצאי זיתים\u0004 של בשר המת. אם עמד אדם \u0003והכניס\u0004 את \u0003ראשיהן\u0004 ה\u0003שניים\u0004 של העצמות (שאין בהן מבשר המת) \u0003לבית, והבית מאהיל עליהן,\u0004 על חלק זה של העצמות — \u0003הבית\u0004 נחשב כמאהיל אף על הבשר, ולכך הוא \u0003טמא\u0004 בטומאת אוהל.","\u0003יהודה בן נקוסא אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' יעקב: היאך\u0004 \u0005[כיצד]\u0006 \u0003שני עצמות מצטרפין לכזית,\u0004 והרי הבשר שעל כל עצם הוא פחות מכזית!"],["\u0003ו\u0004עתה מפרטים את השאלה: לשיטת \u0003רב\u0004 האומר שאין יד לפחות מכזית, וכן שאין שומר לפחות מכפול, \u0003האי\u0004 \u0005[זו]\u0006 הברייתא \u0003במאי אוקים לה\u0004 \u0005[במה,\u0006 באיזה אופן הוא \u0005מעמיד אותה]?\u0006 שהרי \u0003אי\u0004 \u0005[אם]\u0006 מדובר בה \u0003ב\u0004אחת מהעצמות הללו שאין בה כל מח (הנאכל), ואין היא משמשת אלא כ\u0003יד\u0004 לבשר (ששיעורו הוא כחצי זית) שעליה — \u0003קשיא רישא\u0004 \u0005[קשה תחילתה\u0006 של הברייתא\u0005]\u0006 מדברי התנא הראשון שאמר שנטמא הבית בטומאת אוהל — הרי שיש יד לטומאה לפחות מכזית.","ו\u0003אי\u0004 \u0005[אם]\u0006 מדובר בברייתא זו \u0003ב\u0004עצם שיש בה מח בצידה האחד, והריהי משמשת כ\u0003שומר\u0004 לדבר הנאכל אף ששיעורו הוא פחות מכזית — \u0003קשיא סיפא\u0004 \u0005[קשה סופה\u0006 של הברייתא\u0005],\u0006 מדברי יהודה בן נקוסא המטהר מטומאת אוהל — הרי שאין שומר לפחות מכזית, בעוד שלשיטת רב יש שומר לפחות מכזית!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שרב מעמיד את הברייתא \u0003ב\u0004עצם המשמשת כ\u0003שומר, איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שרב מעמיד את הברייתא \u0003ב\u0004עצם המשמשת כ\u0003יד.\u0004","ומפרטים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר \u0003ב\u0004עצם המשמשת כ\u0003יד, והוא\u0004 רב \u0003אמר כ\u0004דעת \u0003ר' יהודה בן נקוסא,\u0004 המטהר את הבית מטומאת אוהל, שהוא סבור שאין יד לפחות מכזית. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שמדובר \u0003ב\u0004עצם המשמשת כ\u0003שומר, והוא\u0004 רב \u0003אמר כ\u0004דעת \u0003תנא קמא\u0004 \u0005[התנא הראשון],\u0006 המטמא את הבית, שהוא סבור שיש שומר לפחות מכזית.","\u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 כי בכל הברייתא \u0003כולה\u0004 מדובר \u0003ב\u0004עצם המשמשת כ\u0003יד, והוא\u0004 ר' יוחנן \u0003אמר\u0004 את שיטתו \u0003כ\u0004דעת \u0003תנא קמא\u0004 \u0005[התנא הראשון],\u0006 המטמא את הבית, שהוא סבור שיש יד לפחות מכזית. ושלא כדעת יהודה בן נקוסא המטהר את הבית שהוא סבור שאין יד לפחות מכזית. ולענין מחלוקתם של רב ור' יוחנן מציעים:","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מן הברייתא שלא כשיטת רב, שכן שנינו ש\u0003ר' יהודה אומר\u0004 כי \u0003ה\u0004\u0003קולית\u0004 (עצם הירך) \u0003שיש עליה כזית בשר\u0004 — כזית הבשר \u0003גוררת\u0004 (מושכת אחריה) את הקולית \u0003כולה ל\u0004ענין ה\u0003טומאה,\u0004 שאם נגע שרץ בכל מקום שהוא בקולית — הריהי נטמאת בכך. \u0003אחרים אומרים\u0004 כי \u0003אפילו\u0004 אם \u0003אין עליה\u0004 על הקולית \u0003אלא\u0004 בשר ששיעורו \u0003כפול\u0004 בלבד — הבשר \u0003גוררת\u0004 את הקולית \u0003כולה לטומאה. ו\u0004מעתה יש להקשות לשיטת","\u0003רב:\u0004 האי \u0005[זו,\u0006 הברייתא, \u0003במאי מוקים לה\u0004 \u0005[במה,\u0006 באיזה אופן הוא \u0005מעמיד אותה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003ב\u0004קולית המשמשת כ\u0003יד\u0004 לבשר שעליה — \u0003קשיא סיפא\u0004 \u0005[קשה סוף\u0006 הברייתא\u0005],\u0006 משיטת אחרים הסבורים שאפילו אם לא היה בקולית אלא כפול בשר, הריהי משמשת כיד להכנסת טומאה. ושלא כשיטת רב האומר שאין יד לפחות מכזית. ו\u0003אי\u0004 \u0005[אם]\u0006 מדובר בברייתא זו \u0003ב\u0004קולית המשמשת כ\u0003שומר\u0004 לבשר שבה — \u0003קשיא רישא\u0004 \u0005[קשה תחילת\u0006 הברייתא\u0005],\u0006 משיטתו של ר' יהודה האומר שרק אם על הקולית כזית בשר הריהי מטמאת, שלא כשיטת רב האומר שיש שומר בפחות מכזית!","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר בברייתא \u0003ב\u0004קולית המשמשת כ\u0003יד\u0004 לבשר שעליה — \u0003והוא\u0004 רב \u0003אמר\u0004 את שיטתו \u0003כ\u0004דעת \u0003ר' יהודה\u0004 הסבור שרק אם יש על הקולית כזית בשר נטמאת כל הקולית, ואולם אם יש עליה פחות מכזית — אין היא נטמאת, שכן אין יד לפחות מכזית, וכשיטת רב. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שמדובר בברייתא \u0003ב\u0004קולית המשמשת כ\u0003שומר\u0004 לבשר שעליה — ושיטת רב היא \u0003כ\u0004שיטת \u0003אחרים\u0004 בברייתא הסבורים שיש שומר בפחות מכזית, ושלא כשיטת ר' יהודה.","\u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 כי בכל הברייתא \u0003כולה\u0004 מדובר \u0003ב\u0004קולית המשמשת כ\u0003שומר\u0004 לבשר שבה, \u0003והוא\u0004 ר' יוחנן \u0003אמר\u0004 את שיטתו \u0003כ\u0004דעת \u0003אחרים\u0004 הסבורים שיש שומר בשיעור כפול. ושלא כדעת ר' יהודה הסבור שאין שומר אלא בכזית.","ומקשים על הסבר זה בשיטת ר' יוחנן: כיצד מעמיד ר' יוחנן את שיטתו כדעת \u0003אחרים,\u0004 \u0003הא\u0004 \u0005[הרי]\u0006 רק בשיעור \u0003\"כפול\" קא אמרי\u0004 \u0005[הם אומרים כפול]\u0006 שיש שומר, ואילו ר' יוחנן אומר שיש שומר אפילו בפחות מכפול!","ומשיבים: בעיקר סבורים אחרים כי יש שומר אף בפחות מכפול, ואולם \u0003איידי דקאמר תנא קמא שיעורא\u0004 \u0005[מתוך שאמר התנא הראשון שיעור\u0006 מסויים, \"כזית\"\u0005],\u0006 \u0003קאמרי אינהו נמי שיעורא\u0004 \u0005[אמרו גם הם שיעור\u0006 מסויים, \"כפול\"\u0005],\u0006 אבל לדעתם הוא הדין אף בפחות מכפול.","\u0003אמר רבא: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 מלשון הברייתא \u0003ש\u0004\u0003ב\u0004עצם המשמשת כ\u0003שומר עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ולא בעצם המשמשת כיד. \u0003דקתני\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בה בעצם \u0003קולית,\u0004 והרי \u0003עצם זו לרוב יש בתוכה מח, והריהי משמשת כשומר לאוכל שבתוכה. ואילו היו דברי הברייתא עוסקים בעצם המשמשת כיד, היה לה לשנות דבריה בכל עצם שיש עליה בשר.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי בעצם המשמשת כשומר עוסקת הברייתא.","שנינו למעלה בברייתא את דעת אחרים בדין הקולית, שאפילו אין עליה כי אם כשיעור כפול, גורר הבשר את הקולית כולה לענין הטומאה. ובענין זה \u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו האמוראים, ש\u0003ר' חנינא אמר\u0004 כי \u0003זהו\u0004 בדווקא ה\u0003שיעור,\u0004 ואילו בפחות משיעור זה — אין הקולית נגררת אחר הבשר להיטמא. \u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 כי \u0003אין זה\u0004 ה\u0003שיעור\u0004 בדווקא, ואף בפחות מכפול יש דין שומר בקולית.","ותוהים על דברי ר' יוחנן: כיצד ניתן לומר כי \u0003\"אין זה שיעור\", והא קתני\u0004 \u0005[והרי שנינו]\u0006 בברייתא במפורש \"אפילו אין עליה אלא \u0003כפול\"!\u0004 ומשיבים: באמת סבורים אחרים שהוא הדין אף בפחות מכפול, ואולם \u0003איידי דקאמר תנא קמא שיעורא\u0004 \u0005[מתוך שאמר התנא הראשון שיעור\u0006 מסויים, \"כזית\"\u0005],\u0006 \u0003קאמרי אינהו נמי שיעורא\u0004 \u0005[אמרו גם הם שיעור\u0006 מסויים, \"כפול\"\u0005],\u0006 אבל כוונתם, אפילו בפחות מכן.","ובבירור מחלוקת זו מציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במשנה בדינו של תרמיל (\"שרביט\") שבתוכו גרגרי קטנית, ועמד ורוקן את התרמיל מגרגריו, ש\u0003ר' אלעזר בן עזריה מטהר ב\u0004תרמיל \u0003של פול\u0004 שיש בו גרגרים, שכן הפולים הם גסים, ואינם צריכים לתרמיל. ולכך אין התרמיל נחשב כשומר לאוכלים. \u0003ומטמא ב\u0004תרמיל \u0003של קטנית\u0004 אם נשאר גרגר אחד בתרמיל — \u0003מפני שרוצה במשמישן,\u0004 כלומר, שיהיה לו משהו לאחוז בו כאשר ינקה את הקטניות. הרי איפוא שיש שומר אף בפחות מכפול, ושלא כדברי ר' חנינא ורב!","ומשיבים: אין זו קושיה, שכן הסבר דברי אותה משנה, הריהו \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא\u0004 בתשובה לשאלה אחרת שהמשנה עוסקת באופן שנגע השרץ לא בתרמיל אלא \u0003בקולחא\u0004 \u0005[בקלח]\u0006 שהתרמילים נמצאים בו, \u0003ו\u0004אין נידון הדברים משום \"שומר\" אלא \u0003משום \"יד\",\u0004 שהרי הקלח משמש כיד לתרמילים ולקטניות שבתוכם.","מעתה \u0003הכא\u0004 \u0005[כאן],\u0006 בתשובה לשאלה זו \u0003נמי\u0004 \u0005[גם כן]\u0006 יש לומר בהסבר דברי המשנה שמדובר בה \u0003בקולחא\u0004 \u0005[בקלח],\u0006 \u0003ומשום יד. ומאי\u0004 \u0005[ומה]\u0006 פירוש דברי ר' אלעזר בן עזריה שאמר שאדם רוצה \u0003במשמישן?\u0004 כוונתו — \u0003בתשמישן,\u0004 בשימוש בהם באותם קלחים.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005של בית]\u0006 מדרשו של \u0003ר' ישמעאל\u0004 על הכתוב בטומאת אוכלים \u0003\"על כל זרע זרוע\"\u0004 (ויקרא י״א:ל״ז,חז), וכמובא בדף הקודם שהרי זה בא ללמד לענין השומר בדין הטומאה, ש\u0003כדרך שבני אדם מוציאין\u0004 בזריעה, \u0003חטה בקליפתה, ושעורה בקליפתה, ועדשים בקליפתן.\u0004 לכך הקליפה (המשמשת כשומר לאוכל שבתוכה) הריהי מצטרפת להשלים לשיעור טומאת אוכלים. הרי איפוא שיש שומר אף בפחות מכפול, שכן קליפת החיטה והשעורה והעדשים מועטה משיעור כפול. והרי זה שלא כדעת ר' חנינא ורב!","ומשיבים: אין זו קושיה, שכן \u0003בריה\u0004 שלימה, עצמאית, דבר שלם כגרגרי החיטה והשעורה בקליפתן עליהם, \u0003שאני\u0004 \u0005[שונה]\u0006 דינו. ולכן יש בהם שומר אף בפחות משיעור כפול.","ועוד בדיני שומרים לאוכל, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אושעיא:\u0004"],["אחר שלמדנו כי השומר מצטרף לאוכל שבתוכו להשלימו לשיעור כביצה לענין טומאת אוכלים, \u0003שני שומרין\u0004 של דבר מאכל, \u0003מהו\u0004 הדין לענין \u0003שיצטרפו\u0004 להשלים לשיעור ביצה?","ומבררים את השאלה: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר],\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003ב\u0004אופן שהיו השומרים נתונים \u0003זה על גב זה,\u0004 כדבר מאכל שיש לו שתי קליפות, פנימית וחיצונית — \u0003ומי איכא\u0004 \u0005[והאם יש,\u0006 נוהג דין\u0005]\u0006 שומר במקרה כזה \u0003של\u0004 \u0003שומר על גב שומר?\u0004","\u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 כי \u0003ר' יהודה אומר\u0004 שיש \u0003שלש קליפות בבצל,\u0004 הנבדלות זו מזו בדינן. שהקליפה ה\u0003פנימית, בין\u0004 שהיא \u0003שלמה\u0004 ו\u0003בין\u0004 שהיא \u0003קדורה\u0004 (נקובה) — היא עצמה נחשבת כאוכל, ולכך היא \u0003מצטרפת\u0004 לבצל שבתוכה להשלמת שיעורו לכביצה. ואילו הקליפה ה\u0003אמצעית,\u0004 אינה נחשבת אוכל, ואולם אם היא \u0003שלמה\u0004 — היא משמשת כשומר לבצל שבתוכה ולכך היא \u0003מצטרפת\u0004 אליו להשלים שיעורו, ואולם אם היא \u0003קדורה,\u0004 ולכן אינה משמשת לשמירה על הבצל — \u0003אין מצטרפת\u0004 להשלים לשיעור. ואילו הקליפה ה\u0003חיצונה\u0004 הדקה ביותר, שאינה נאכלת — \u0003בין כך ובין כך,\u0004 בין שהיא נקובה ובין שהיא שלימה, הריהי \u0003טהורה,\u0004 שאינה מצטרפת לבצל להשלים לשיעור. הרי שאין שומר על גב שומר!","ומסבירים: לא באופן זה שאל \u0003רב אושעיא\u0004 את שאלתו, אלא במקרה של \u0003שומר אוכל שחלקו,\u0004 שחילק את האוכל עם השומר שעליו, באופן שהשומרים נפרדים זה מזה, ואולם חלקי האוכל מחוברים זה לזה. שכך \u0003קמיבעיא ליה\u0004 \u0005[היא נשאלה לו],\u0006 ואלו הם צדדי הבעיה: האם","\u0003כיון דהאי\u0004 \u0005[ש\u0006שומר \u0005זה]\u0006 הנמצא על חלק האחד של האוכל שוב \u0003לא מגין אהאי\u0004 \u0005[על\u0006 חלק \u0005זה,\u0006 השני\u0005]\u0006 של האוכל. \u0003ו\u0004בדומה לכך, שומר \u0003האי\u0004 \u0005[זה]\u0006 של החלק השני של האוכל שוב \u0003לא מגין אהאי\u0004 \u0005[על\u0006 חלק \u0005זה\u0006 הראשון\u0005]\u0006 של האוכל — מעתה \u0003לא מצטרפת\u0004 להשלים את שיעור כביצה של שני חלקי האוכל.","\u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר מן הצד השני כי \u0003כיון דהאי\u0004 \u0005[ש\u0006שומר \u0005זה]\u0006 \u0003מגין אדידיה\u0004 \u0005[על\u0006 חלק האוכל \u0005שלו],\u0006 \u0003ו\u0004כמו כן שומר \u0003האי\u0004 \u0005[זה]\u0006 \u0003מגין אדידיה\u0004 \u0005[על\u0006 חלק האוכל \u0005שלו],\u0006 ושני חלקי האוכל מחוברים זה לזה, נחשב הכל כמחובר, ו\u0003מצטרפין\u0004 השומרים להשלמת שיעור כביצה.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה ממה ששנינו בדינן של קטניות, ש\u0003ר' אלעזר בן עזריה מטהר בשל פול\u0004 שיש בו גרגרים, שאין התרמיל שלהם נחשב כשומר לגרגריו, משום שהפולים הם גסים ואינם צריכים לשרביט. \u0003ומטמא \u0004את התרמיל \u0003בשל קטנית \u0004אם נשאר גרגיר בתרמיל, \u0003מפני ש\u0004אדם \u0003רוצה ב\u0004תרמילים אלו לשם \u0003משמישן \u0004(שימושם כשומר לגרגרים). והרי כל תרמיל אינו שומר אלא על הגרגרים שבתוכו בלבד, שאין בהם כדי שיעור כביצה, ובכל זאת מצטרפים התרמילים זה לזה להשלמת שיעור טומאה.","ודוחים: הרי כבר \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא\u0004 בהסבר דברי ר' אלעזר בן עזריה שאין המדובר בתרמילי הקטניות, אלא \u0003בקולחא\u0004 \u0005[בקלח],\u0006 שהתרמילים נתונים בו, \u0003ו\u0004אין ר' אלעזר בן עזריה מטמא את הקטניות משום שומר (שהרי הקלח אינו שומר על גרגרי הקטניות), אלא \u0003משום יד,\u0004 שמשמש הקלח לאחיזה לצורך הקטניות, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"במשמישן\"?\u0004 — \u0003בתשמישן.\u0004","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעית רב אושעיא ממה \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005של בית]\u0006 מדרשו של \u0003ר' ישמעאל\u0004 על הכתוב בטומאת אוכלים \u0003\"על כל זרע זרוע\"\u0004 (ויקרא יא, לז), וכמובא בדף הקודם שהרי זה בא ללמד לענין השומר בדין הטומאה, ש\u0003כדרך שבני אדם מוציאין\u0004 בזריעה, \u0003חטה בקליפתה, ושעורה בקליפתה, ועדשים בקליפתן.\u0004 לכך הקליפה (המשמשת כשומר לאוכל שבתוכה) מצטרפת להשלים לשיעור טומאת אוכלים. והרי בגרגר חיטה ושעורה אחת אין בקליפה כדי להשלימו לשיעור כביצה, ואין זאת אלא שלמדנו שמצטרפות קליפותיהן של הרבה גרגרי חיטה ושעורה כדי להשלימן לשיעור כביצה, ומעתה נמצא פתרון לבעיית רב אושעיא, בעניינו של שומר שחילקו, שהריהו מצטרף.","ודוחים: \u0003כ\u0004דרך ש\u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא\u0004 בהסבר דברי ר' אלעזר בן עזריה המובאים למעלה שאין המדובר בהם בתרמיל הקטניות ומשום שומר, אלא \u0003בקולחא\u0004 \u0005[בקלח],\u0006 \u0003ומשום יד,\u0004","הכא נמי \u0005[כאן גם כאן,\u0006 בדברי החכם מבית מדרשו של ר' ישמעאל\u0005]:\u0006 אין המדובר בגרגרי החיטה והשעורה כשלעצמן, אלא \u0003בשדרה\u0004 שבה נתונים הגרגרים, \u0003ומשום שומר.\u0004 שכל גרגרי החיטה אחוזים בעיגול סביב שדרת השיבולת, ושומרים הם זה לזה, שאם תיפול קליפתו של אחד מהם, תיפולנה אחריה גם קליפות האחרים והגרגרים עימן. ולכך מצטרפות הקליפות זו לזו.","ותוהים על הסבר זה: \u0003בשלמא\u0004 \u0005[נניח,\u0006 מובן הדבר\u0005]\u0006 שגרגרי \u0003עיליתא צריכי לתתיתא\u0004 \u0005[\u0006השורות \u0005העליונות\u0006 בשיבולת \u0005צריכים את\u0006 הגרגרים של השורות \u0005התחתונות]\u0006 להחזיק אותם, \u0003אלא תתיתא מאי צריכי לעיליתא\u0004 \u0005[התחתונות מה\u0006 הן \u0005צריכות את העליונות]?\u0006 ומשיבים: הכוונה לגרגרים ש\u0003בחד דרא\u0004 \u0005[בשורה אחת]\u0006 בשיבולת החיטה, שאלה עומדים בצפיפות בסמוך זה לזה, ואם תיפול קליפתו של אחד מהם, ואף העליון, תתערער הקבוצה, ויפלו השאר.","ושואלים: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 \u0003כ\u0004שיעור \u0003ביצה אוכלין בחד דרא\u0004 \u0005[בשורה אחת]\u0006 של חיטה? ומשיבים: כן, כגון \u0003בחטי\u0004 \u0005[בחיטים]\u0006 שהיו בזמנו של \u0003שמעון בן שטח,\u0004 שהיו גדולות ביותר.","ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן]\u0006 לתרץ כך, מעתה שוב אין צורך להסביר את דברי החכם של בית מדרשו של ר' ישמעאל שמדובר בשדרה של חיטה, ובהרבה גרגרים הנתונים בה, אלא בגרגר \u0003חדא\u0004 \u0005[אחד]\u0006 של \u0003חטה נמי\u0004 \u0005[גם כן]\u0006 יכול אתה להסביר את דברי חכם זה, וכגון \u0003בחטי\u0004 \u0005[בחיטים]\u0006 שהיו בזמנו של \u0003שמעון בן שטח\u0004 שהיו גדולות מאד.","למעלה (קיח,ב) אגב דיון הובאה מחלוקתם של חכמים ויהודה בן נקוסא, ועתה דנים בהלכה זו \u0003גופא\u0004 \u0005[לגופה].\u0006 שנינו: \u0003שני עצמות ועליהן שני חצאי זיתים, והכניס ראשיהן שנים לבית, והבית מאהיל עליהן\u0004 — לדעת חכמים \u0003הבית טמא\u0004 בטומאת אוהל, ומטמא את הנמצא בתוכו, שכן שני חצאי הזית מצטרפים לשיעור כזית, המטמא בטומאת אוהל.","ואילו \u0003יהודה בן נקוסא אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' יעקב: היאך\u0004 \u0005[כיצד]\u0006 שני חצאי זית הנמצאים ב\u0003שני עצמות\u0004 נבדלות \u0003מצטרפין לכזית?\u0004 ומכאן נסיק שעצם שיש עליה בצידה האחד שיעור שלם של כזית בשר מן המת, ועמד והכניס לתוך הבית את צידה האחר של העצם שאין בו בשר מן המת — מטמאה את הבית בטומאת אוהל, לדעת הכל.","ובענין זה \u0003אמר ריש לקיש: לא שנו\u0004 שכך הדין, \u0003אלא\u0004 רק ב\u0003עצם,\u0004 ומשום \u0003דהוי\u0004 \u0005[שהריהי]\u0006 משמשת כ\u0003יד\u0004 לבשר המת. \u0003אבל נימא\u0004 \u0005[שערה]\u0006 שעל ראשה האחד נמצא בשר מן המת בשיעור כזית, והכניס לתוך הבית את ראשה השני של השערה — אין הבית נטמא בכך, שכן השערה \u0003לא הויא\u0004 \u0005[אינה נהיית]\u0006 \u0003יד\u0004 לבשר. \u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 ש\u0003אפילו נימא נמי הויא\u0004 \u0005[שערה גם כן הינה]\u0006 \u0003יד\u0004 לבשר, ונטמא הבית בכך.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו כי \u0003עור שיש עליו כזית בשר, הנוגע בציב\u0004 (חוט בשר) \u0003היוצא ממנו,\u0004 מן הבשר, \u0003ו\u0004כן הנוגע \u0003בשערה ש\u0004נמצאת \u0003כנגדו,\u0004 מעברו האחר של העור שבו נמצאת חתיכת הבשר — \u0003טמא.\u0004 ויש לדייק בדברים: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הסיבה לכך שהנוגע בציב נטמא בכך, הרי זה \u0003משום יד,\u0004 והרי זה שלא כדברי ריש לקיש שאמר שאין השערה נחשבת יד לבשר!","משיב ריש לקיש לשאלה זו: \u0003לא,\u0004 אין זה משום שהשערה משמשת כיד לבשר, אלא \u0003משום\u0004 שהיא משמשת כ\u0003שומר\u0004 לבשר. ותוהים על הסבר זה: והרי העור הוא השומר על הבשר, ואילו השערה נמצאת מעל העור, \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 \u0003שומר על גבי שומר?\u0004 \u0003ומשיבים:\u0004 \u0003חלחולי מחלחל\u0004 \u0005[מחלחלת]\u0006 השערה מבעד לעור ומגיעה עד לבשר, ואף היא שומרת על הבשר בחלקה שלה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך,\u0006 על תשובה זו\u0005]\u0006 \u0003רב אחא בר יעקב: אלא מעתה\u0004 שאמרנו כי יש נקבים בעור שדרכם השערה מחלחלת מבעד לעור ומגיעה לבשר עצמו, \u0003תפילין היכי כתבינן\u0004 \u0005[איך אנו כותבים]?\u0006 \u0003הא בעינן\u0004 \u0005[הרי אנו צריכים]\u0006 בכתיבת התפילין שתהא זו \u0003כתיבה תמה\u0004 (רצופה ושלימה), שלא יהיה דבר המפסיק בתוכה, \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שכן הנקבים המשמשים למעבר השערות בעור מפסיקים בתוך הכתיבה!","ומעירים: \u0003אשתמיטתיה\u0004 \u0005[נשמט ממנו,\u0006 מרב אחא בר יעקב שהקשה כן\u0005]\u0006 \u0003הא\u0004 \u0003דאמרי במערבא\u0004 \u0005[\u0006הלכה \u0005זו שאמרו בארץ ישראל]\u0006 כי \u0003כל נקב שהדיו עובר עליו\u0004 ומכסה אותו — \u0003אינו\u0004 נחשב \u0003נקב\u0004 לענין פסול בכתיבה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תשובה אחרת לשאלת ר' יוחנן על ריש לקיש מדברי משנה זו: כל המשנה \u0003כוליה\u0004 \u0005[כולה]\u0006 המטמאת את הנוגע בציב או בשערה, מדברת בטומאה \u0003משום יד,\u0004 ולא משום שומר. ואולם אין בכך משום קושיה על שיטת ריש לקיש הסבור שאין השערה נחשבת כיד, שכן הסבר הדברים הוא \u0003כ\u0004דרך ש\u0003אמר ר' אלעא\u0004 בפירוש משנה אחרת, שמדובר בה \u0003במלאי\u0004 (בשערה) \u0003שבין המלאים\u0004 (וכפי שיוסבר להלן),","\u0003הכא נמי\u0004 \u0005[כאן,\u0006 במשנה זו לענין טומאת הנוגע בשערה, \u0005גם כן]\u0006 יש לומר שאין המדובר בשערה אחת בודדת, אלא \u0003בנימא\u0004 \u0005[בשערה]\u0006 \u0003שבין הנימין\u0004 \u0005[שערות]\u0006 מרובות, ובאמצעות כל אותן שערות ניתן להחזיק את הבשר (ובאותה עת, השערות הללו לא תינתקנה ממקומן), ולכך הריהן משמשות כיד.","ואומרים: \u0003והיכא אתמר\u0004 \u0005[והיכן נאמרו]\u0006 דבריו אלה של \u0003ר' אלעא\u0004 במקורם? ומשיבים: \u0003אהא\u0004 \u0005[על\u0006 משנה \u0005זו]\u0006 ששנינו בה כי ה\u0003מלאי\u0004 (השערות שבראש השיבולת) \u0003שבשבלים\u0004 הריהם \u0003מיטמאין\u0004 מן האוכל, שאם נגעה טומאה בשיבולים נטמאו גם שערותיהן, \u0003ומטמאין\u0004 את השיבולים אם נגעה טומאה בשערות, \u0003ו\u0004אולם הם \u0003אינן מצטרפין\u0004 לשיבולים להשלימן לשיעור טומאה, וכדין יד. ושאלו בבירור משנה זו: \u0003מלאי למאי חזי\u0004 \u0005[למה\u0006 לאיזה שימוש הוא \u0005ראוי]\u0006 שייחשב בו כיד לשיבולים? ועל כך \u0003אמר ר' אלעאי\u0004 בתשובה: אין המדובר במלאי אחד בודד, שאמנם אין הוא כשלעצמו ראוי לשמש כיד לשיבולת, אלא \u0003במלאי שבין המלאים,\u0004 בקבוצה מרוכזת של שערות שבראשי השיבולת, ואלה מסוגלות לאחוז בהן את השיבולת בלא שתינתקנה ממנה. למעלה הובאה מחלוקת ר' יוחנן וריש לקיש בדין שערה, האם היא משמשת כיד לדבר הנמצא תחתיה, ואת הדיון בדברי ריש לקיש. ועתה מביאים כי","\u0003לישנא אחרינא אמרי לה\u0004 \u0005[\u0006ב\u0005לשון אחרת אומרים אותה\u0006 את המחלוקת שבין ר' יוחנן וריש לקיש והדיון שבעקבותיה\u0005]\u0006 באופן זה: שלא נחלקו בדינה של שערה אחת, אלא מוסכם על הכל שאין זו נחשבת כיד. ונחלקו רק בקבוצת שערות האם אלה נחשבות כיד או לא. והקשה ר' יוחנן לריש לקיש (הסבור שאין השערות נחשבות כיד) ממה ששנינו במשנה בדינו של הנוגע בשערה היוצאת מן העור שבצידו האחר ישנה חתיכת בשר מן המת, שהריהו טמא, והרי איפוא שהשערות נחשבות כיד. ועל כך השיב ריש לקיש כי אין הטומאה משום שהשערות נחשבות כיד אלא משום שהן נחשבות כשומר, שכן הן מגינות על הבשר. ומעירים כי","\u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, ש\u0003משום שומר\u0004 היא טומאתו של הנוגע ולא משום יד, \u0003דאי סלקא דעתך\u0004 \u0005[ש\u0006כן \u0005אם עולה על דעתך]\u0006 לומר שטומאתו היא \u0003משום יד\u0004 — \u0003נימא\u0004 \u0005[שערה]\u0006 \u0003אחת למאי חזי\u0004 \u0005[למה\u0006 לאיזה שימוש היא \u0005ראויה]\u0006 שתיחשב בו כיד לבשר?","ודוחים: אין זו ראיה, שכן \u0003כ\u0004דרך ש\u0003אמר ר' אלעא\u0004 בהסבר המשנה המזכירה \"מלאי\" שאין הכוונה לאחת בודדת, אלא \u0003במלאי שבין המלאין, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לומר שאין המדובר בשערה בודדת אלא \u0003בנימא שבין הנימין.\u0004","ואומרים: \u0003והיכא אתמר\u0004 \u0005[והיכן נאמרו]\u0006 דבריו אלה של \u0003ר' אלעא\u0004 במקורם? ומשיבים: \u0003אהא דתנן\u0004 \u0005[על\u0006 משנה \u0005זו ששנינו]\u0006 בה כי ה\u0003מלאי\u0004 (השערות שבראש השיבולת) \u0003שבשבלים\u0004 הריהם \u0003מיטמאין\u0004 מן האוכל, שאם נגעה טומאה בשיבולים נטמאו גם שערותיהן, \u0003ומטמאין\u0004 את השבלים אם נגעה טומאה במלאי, \u0003ו\u0004אולם הם \u0003אינן מצטרפין\u0004 לשיבולים להשלימן לשיעור טומאה, וכדין יד. ושאלו בבירור משנה זו: \u0003מלאי למאי חזי\u0004 \u0005[למה\u0006 לאיזה שימוש הוא \u0005ראוי]\u0006 שייחשב בו ליד לשיבולים? ועל כך \u0003אמר ר' אלעאי:\u0004 בתשובה: אין המדובר במלאי אחד בודד, שאינו ראוי לשמש כיד לשיבולת, אלא \u0003במלאי שבין המלאים,\u0004 בקבוצה מרוכזת של שערות שבראשי השיבולת, ואלה מסוגלות לאחוז בהן את השיבולת בלא שתינתקנה ממנה.","\u0003ו\u0004מביאים אופן נוסף בו נשנתה מחלוקתם של ר' יוחנן וריש לקיש, ודרך הדיון שבעקבות מחלוקתם. שכן \u0003איכא דמתני לה\u0004 \u0005[יש ששונים אותה]\u0006 את מחלוקתם של ר' יוחנן וריש לקיש"],["\u0003אמתניתין\u0004 \u0005[על\u0006 מה ששנינו ב\u0005משנתנו]\u0006 כי \u0003העור והרוטב והקיפה\u0004 והאלל והעצמות והגידים והקרנים והטלפים \u0003מצטרפין\u0004 להשלים את שיעורו של הבשר לשיעור כביצה, \u0003לטמא טומאת אוכלין.\u0004","ועל כך \u0003אמר ריש לקיש\u0004 כי \u0003לא שנו\u0004 שמצטרפים אלה עם הבשר \u0003אלא\u0004 דווקא \u0003עצם\u0004 והדברים האחרים המנויים עימה, ומשום \u0003דהוי\u0004 \u0005[שהריהי]\u0006 משמשת כ\u0003שומר\u0004 לבשר, \u0003אבל נימא\u0004 \u0005[שערה]\u0006 אינה מצטרפת לבשר להשלים שיעורו לטומאה, שכן \u0003לא הויא\u0004 \u0005[אין היא]\u0006 משמשת כ\u0003שומר\u0004 לבשר. \u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 כי \u0003אפילו נימא נמי הויא\u0004 \u0005[שערה גם כן הינה]\u0006 \u0003שומר\u0004 לבשר, ולכך מצטרפת להשלים שיעורו לטומאה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן:\u0004 והרי השערה נמצאת על העור (המשמש כשומר לבשר), ומעתה השערה היא שומר על גבי שומר, \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 דין \u0003שומר על גבי שומר?\u0004 השיב לו ר' יוחנן: \u0003חלחולי מחלחל\u0004 \u0005[מחלחלת]\u0006 השערה מבעד לעור ומגיעה עד לבשר, ואף היא שומרת על הבשר בחלקה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך,\u0006 על תשובה זו\u0005]\u0006 \u0003רב אחא: אלא מעתה\u0004 שאמרנו כי יש נקבים בעור שדרכם השערה מחלחלת מבעד לעור ומגיעה לבשר עצמו, \u0003תפילין היכי כתבינן\u0004 \u0005[איך אנו כותבים]?\u0006 \u0003הא בעינן\u0004 \u0005[הרי אנו צריכים]\u0006 בכתיבת התפילין שתהא זו \u0003כתיבה תמה\u0004 (רצופה ושלימה), שלא יהיה דבר המפסיק בתוכה, \u0003וליכא\u0004 \u0005[ואין כאן]\u0006 שכן נקבי השערות בעור מפסיקים בתוך הכתיבה!","ומעירים: \u0003אשתמיטתיה\u0004 \u0005[נשמט ממנו,\u0006 מרב אחא שהקשה כן\u0005]\u0006 \u0003הא דאמרי במערבא\u0004 \u0005[\u0006הלכה \u0005זו שאמרו בארץ ישראל]\u0006 כי \u0003כל נקב שהדיו עובר עליו\u0004 ומכסה אותו — \u0003אינו\u0004 נחשב \u0003נקב\u0004 לענין זה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 ממה ששנינו כי \u0003עור שיש עליו כזית בשר, הנוגע בציב\u0004 (סיב, חוט בשר) \u0003היוצא ממנו,\u0004 מן הבשר, \u0003ו\u0004כן זה הנוגע \u0003בשערה ש\u0004נמצאת \u0003כנגדו,\u0004 מעברו האחר של העור שבו נמצאת חתיכת הבשר — \u0003טמא.\u0004 ויש לדייק: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הסיבה שהנוגע בשערה נטמא הרי זה — \u0003משום שומר,\u0004 ושלא כדברי ריש לקיש שאמר שאין השערה נחשבת שומר לבשר! ודוחה ריש לקיש: \u0003לא,\u0004 אין טעם הדבר משום שהשערה משמשת כשומר לבשר, אלא \u0003משום\u0004 שהיא משמשת כ\u0003יד\u0004 לבשר.","ושואלים על הסבר זה: \u0003נימא\u0004 \u0005[שערה]\u0006 \u0003אחת למאי חזי\u0004 \u0005[למה\u0006 לאיזה שימוש היא \u0005ראויה]\u0006 שתיחשב כיד לבשר? ומשיבים: אין המדובר בשערה בודדת, אלא בקבוצת שערות, שהרי אלה משמשות כיד לחתיכת הבשר, שאפשר לאחוז בהן את הבשר, בלא שתינתקנה. \u0003כ\u0004דרך ש\u0003אמר ר' אלעא\u0004 בהסבר המשנה המזכירה \"מלאי\" והסביר ר' אלעא שאין הכוונה לאחת בודדת, אלא \u0003במלאי שבין המלאין, הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לומר שאין המדובר בשערה בודדת אלא \u0003בנימא שבין הנימין.\u0004","ואומרים: \u0003והיכא אתמר\u0004 \u0005[והיכן נאמרו]\u0006 דבריו אלה של \u0003ר' אלעא\u0004 במקורם? ומשיבים: \u0003אהא דתנן\u0004 \u0005[על\u0006 משנה \u0005זו ששנינו]\u0006 בה כי \u0003המלאי\u0004 (השערות שבראש השיבולת) \u0003שבשבלין מיטמאין\u0004 מן האוכל, שאם נגעה טומאה בשיבולים נטמאו גם שערותיהן, \u0003ומטמאין\u0004 את השיבולים אם נגעה במלאי טומאה, \u0003ו\u0004אולם הם \u0003אינן מצטרפין\u0004 לשיבולים להשלימן לשיעור טומאה, וכדין יד. ושאלו בבירור משנה זו: \u0003מלאי למאי חזי\u0004 \u0005[למה\u0006 לאיזה שימוש הוא \u0005ראוי]\u0006 שייחשב בו ליד לשיבולים? ועל כך \u0003אמר ר' אלעאי:\u0004 בתשובה: אין המדובר במלאי בודד, שאמנם אין הוא כשלעצמו ראוי לשמש כיד לשיבולת, אלא \u0003במלאי שבין המלאין,\u0004 בקבוצה מרוכזת של שערות שבראשי השיבולת, ואלה מסוגלות לאחוז בהן את השיבולת בלא שתינתקנה ממנה.","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003הרוטב,\u0004 מצטרף לבשר להשלים שיעורו לכביצה לענין טומאת אוכלים, אבל הוא עצמו אינו מקבל טומאה. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 טיבו\u0005]\u0006 של \u0003רוטב\u0004 זה? \u0003אמר רבא:\u0004 הכוונה ל\u0003שומנא\u0004 \u0005[השומן]\u0006 שעל המרק בו התבשל הבשר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: אם כך הדבר, \u0003הוא\u0004 (הרוטב) \u0003עצמו יטמא טומאת אוכלין,\u0004 שהרי הוא נאכל! \u0003אלא\u0004 יש לומר כי הכוונה ב\"רוטב\" ל\u0003חלב דקריש\u0004 \u0005[הנוזל\u0006 היוצא מן הבשר, \u0005שקרש],\u0006 שהוא אינו נאכל לעצמו, ואולם הוא מצטרף לבשר.","ושואלים: \u0003מאי איריא קריש\u0004 \u0005[מדוע דווקא קרש]?\u0006 \u0003כי לא קריש נמי\u0004 \u0005[כאשר לא קרש גם כן]\u0006 יצטרף לבשר. ואין לומר שמשום שהנוזל אינו \u0003קרוש, הריהו משקה, ואין משקים מצטרפים למאכלים —\u0004 שהרי \u0003אמר ריש לקיש\u0004 כי ה\u0003ציר\u0004 (הנוזל היוצא בשעת בישול) מן הירק \u0003ש\u0004נמצא \u0003על גבי ירק מצטרף לכ\u0004 שיעור \u0003כותבת ביום הכפורים,\u0004 לחייב את האדם האוכל ביום זה כשיעור הזה, אף על פי שהוא נוזל!","ואומרים: בעיקרו של דבר אין המשקים מצטרפים למאכלים להשלימם לשיעור קבלת טומאת אוכלים. וטעם הדבר \u0003התם\u0004 \u0005[שם]\u0006 באכילה ביום הכיפורים, שכן ביום הכיפורים גם בדבר שאין הוא אוכל מתחייבים על אכילתו \u0003משום יתובי דעתא\u0004 \u0005[ישוב הדעת]\u0006 \u0003הוא.\u0004 שהרי אמרה התורה בדין צום יום הכיפורים \"כי כל הנפש אשר לא תעונה בעצם היום הזה ונכרתה מעמיה\" (ויקרא כג, כט), ולכך אף \u0003ב\u0004אכילה \u0003כל דהו\u0004 \u0005[כל שהיא]\u0006 שבה \u0003מיתבא דעתיה\u0004 \u0005[מתיישבת דעתו],\u0006 הריהו חייב.","מה שאין כן \u0003הכא\u0004 \u0005[כאן,\u0006 לענין צירוף להשלמת שיעור לקבלת טומאה\u0005]\u0006 — \u0003משום איצטרופי\u0004 \u0005[צירוף]\u0006 \u0003הוא\u0004 זה, ולכן \u0003אי\u0004 \u0005[אם]\u0006 הנוזל היוצא מן הבשר הוא \u0003קריש\u0004 \u0005[קרוש]\u0006 — הריהו \u0003מצטרף\u0004 לבשר, ואולם \u0003אי לא קריש\u0004 \u0005[אם\u0006 הוא \u0005לא קרוש]\u0006 — הוא \u0003לא מצטרף.\u0004","\u0003ו\u0004עוד שנינו במשנתנו ש\u0003הקיפה\u0004 מצטרפת לבשר להשלים שיעורו לכביצה לענין טומאת אוכלים, ואולם היא עצמה אינה מקבלת טומאה. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 טיבה\u0005]\u0006 של \u0003קיפה\u0004 זו? \u0003אמר רבה:\u0004 הכוונה היא ל\u0003פירמא\u0004 \u0005[המשקע המורכב מחלקיקים דקים של הבשר המתבשל].\u0006","\u0003אמר ליה\u0004 \u0005[לן]\u0006 \u0003אביי\u0004 לרבה בשאלה על הסברו: אם כך הדבר, \u0003הוא\u0004 (הקיפה) \u0003עצמו יטמא טומאת אוכלין,\u0004 שהרי הוא נאכל! \u0003אלא אמר רב פפא:\u0004 הכוונה היא ל\u0003תבלין\u0004 המתבשל עם הבשר. שהוא עצמו אינו נאכל, ואולם הוא מצטרף לאכילת הבשר, ולכך הוא משלים את שיעורו.","מתוך שנידון עניין הקיפה, מביאים בדינו של זה שהקפה (הקריש על ידי חימום ממושך) דברים האסורים באכילה, שכן \u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 מי ש\u0003הקפה את הדם,\u0004 שעשאו מוצק, \u0003ואכלו\u0004 באופן זה, \u0003או שהמחה\u0004 (המיס) \u0003את החלב,\u0004 והפכו לנוזל, \u0003וגמעו\u0004 — \u0003חייב\u0004 כרת על אכילה ושתייה זו, ככל השותה דם והאוכל חלב.","ומבררים: \u0003בשלמא\u0004 \u0005[נניח,\u0006 זה מובן\u0005]\u0006 מדוע מי ש\u0003הקפה את הדם ואכלו,\u0004 שחייב עליו כי \u0003כיון דאקפיה\u0004 \u0005[שהקריש אותו]\u0006 — \u0003אחשובי אחשביה\u0004 \u0005[החשיב אותו]\u0006 בכך כאוכל, ובאיסור דם נאמר לשון אכילה (\"כל חלב וכל דם לא תאכלו\". ויקרא ג, יז). \u0003אלא\u0004 זה \u0003ש\u0004\u0003המחה את החלב וגמעו\u0004 מדוע הוא חייב, והרי באיסור חלב \u0003אכילה כתיבא ביה\u0004 \u0005[נאמרה בו]\u0006 ולא שתיה (\"כל חלב שור וכשב ועז לא תאכלו\". שם ז, כג), \u0003והא לאו\u0004 \u0005[וזו לא]\u0006 \u0003אכילה היא!\u0004","\u0003אמר ריש לקיש:\u0004 אף השותה חלב (שהומס) חייב על כך, שכן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 באיסור אכילת חלב \"כי כל אוכל חלב מן הבהמה... ונכרתה הנפש האוכלת מעמיה\" (שם, כה), ובאה המלה \"ה \u0003נפש\"\u0004 — \u0003לרבות את השותה.\u0004","ומעירים: \u0003תניא נמי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 איסור אכילת \u0003חמץ\u0004 בפסח, \u0003כהאי גוונא\u0004 \u0005[כגון זה].\u0006 שכן שנינו כי אם \u0003המחהו\u0004 את הלחם \u0003וגמעו\u0004 כנוזל, \u0003אם חמץ הוא\u0004 לחם זה — הריהו \u0003ענוש כרת\u0004 על שתיה זו, כאוכל חמץ בפסח. ו\u0003אם מצה היא\u0004 לחם זה — \u0003אין אדם יוצא בה ידי חובתו בפסח,\u0004 שאין זו נחשבת כאכילת מצוה.","ומבררים: \u0003בשלמא\u0004 \u0005[נניח,\u0006 זה מובן\u0005]\u0006 מה שאמרו \u0003ש\u0004\u0003אם מצה היא אין אדם יוצא בה ידי חובתו בפסח\u0004 — שכן במצות מצה בפסח נאמר \"לא תאכל עליו חמץ שבעת ימים תאכל עליו מצות לחם עוני\" (דברים טז, ג), הרי שדווקא \u0003\"לחם עוני\" אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 שמקיימים בו מצוה זו, \u0003ו\u0004אילו \u0003האי\u0004 \u0005[זה]\u0006 לחם שהומס — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003לחם עוני הוא. אלא\u0004 מה שאמרו \u0003ש\u0004\u0003אם חמץ הוא,\u0004 הריהו \u0003ענוש כרת,\u0004 קשה, שהרי \u0003אכילה כתיבא ביה\u0004 \u0005[נאמרה בו,\u0006 באיסור חמץ בפסח\u0005],\u0006 וזה לא אכל אלא שתה!","\u0003אמר ריש לקיש\u0004 בתשובה: אף השותה חמץ (שהומס) חייב על כך, שכן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 באיסור אכילת חמץ בפסח \"כי כל אוכל חמץ ונכרתה הנפש ההיא מישראל\" (שמות יב, טו), ובאה המלה \"ה \u0003נפש\"\u0004 — \u0003לרבות את השותה. ו\u0004מוסיפים:","\u0003תניא נמי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 טומאת האוכל \u0003נבלת עוף טהור כהאי גוונא\u0004 \u0005[כגון זה].\u0006 שכן שנינו שאם \u0003המחהו\u0004 (המיס אותו את נבלת העוף) \u0003באור\u0004 (באש), ושתה את הנוזל — הריהו \u0003טמא\u0004 בכך. ואולם אם המיס אותו \u0003בחמה\u0004 (בחום השמש) ושתה את הנוזל, הריהו \u0003טהור. והוינן\u0004 \u0005[והיינו עסוקים\u0006 התקשינו\u0005]\u0006 \u0003בה,\u0004 הלא \u0003אכילה כתיב ביה\u0004 \u0005[כתובה בו,\u0006 בטומאת נבלת העוף\u0005]\u0006 ולא שתיה (\"וכל נפש אשר תאכל נבלה וטרפה... וטמא עד הערב\". ויקרא יז, טו)!","\u0003אמר ריש לקיש:\u0004 אף השותה נבלת עוף (שהומסה) נטמא בכך, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בטומאה זו \"וכל \u0003נפש\"\u0004 — \u0003לרבות את השותה.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שריבתה התורה אף את השותה נבלת עוף שהומסה, מעתה זו שהומסה \u0003בחמה נמי\u0004 \u0005[גם כן]\u0006 ייטמא בה, ולא רק בזו שהומסה באש! ומשיבים: אין נטמאים מנבילה שהומסה \u0003בחמה\u0004 משום שבהמסה זו הנמשכת זמן רב \u0003איסרוחי מסרח\u0004 \u0005[נסרחת]\u0006 הנבילה, ואינה ראויה עוד לשתיה.","למעלה הובאו שלוש דרשות מפי ריש לקיש, ושלושתן מלמדות מן הכתוב \"נפש\" לרבות אף את השותה. \u0003ו\u0004עתה מסבירים כי \u0003צריכי\u0004 \u0005[צריכים]\u0006 אנו את כל שלוש הדרשות הללו. משום \u0003דאי כתב רחמנא\u0004 \u0005[שאילו היתה כותבת התורה]\u0006 כן רק בענין אכילת \u0003חלב\u0004 שהומס — \u0003חמץ\u0004 שהומס \u0003לא אתי מיניה\u0004 \u0005[לא היה בא,\u0006 נלמד \u0005ממנו],\u0006 \u0003שכן\u0004 איסור אכילת חלב חמור מאיסור אכילת חמץ, שהרי לחלב מעולם \u0003לא היתה לו שעת הכושר\u0004 (זמן שבו הוא היה מותר באכילה). וכמו כן גם אכילת \u0003נבלה\u0004 שהומסה \u0003לא אתי מיניה\u0004 \u0005[לא היתה באה,\u0006 נלמדת \u0005ממנו]\u0006 — \u0003שכן\u0004 איסור אכילת חלב חמור מאיסור אכילת נבילה, שהרי האוכלו \u0003ענוש כרת,\u0004 בעוד שהאוכל נבילה אינו אלא","בלאו. \u0003ו\u0004כן \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 כן רק בענין אכילת \u0003חמץ\u0004 שהומס — \u0003חלב\u0004 שהומס \u0003לא אתי מיניה\u0004 \u0005[לא היה בא,\u0006 נלמד \u0005ממנו]\u0006 \u0003שכן\u0004 יש צד חומרה בחמץ בהשוואה לחלב, שהרי החמץ \u0003לא הותר מכללו,\u0004 שכן כל דברי החמץ אסורים, ואילו בחלב יש המותרים, כחלב חיה. \u0003ו\u0004כמו כן גם \u0003נבלה\u0004 שהומסה \u0003לא אתיא מיניה\u0004 \u0005[לא היתה באה,\u0006 נלמדת \u0005ממנו]\u0006 — \u0003שכן\u0004 יש בה צד חומרה בהשוואה לאכילת נבלת עוף, שהרי האוכלה \u0003ענוש כרת,\u0004 בעוד שהאוכל נבלת עוף אינו עובר אלא בלאו.","\u0003ו\u0004כמו כן \u0003אי כתב רחמנא\u0004 \u0005[אם היתה כותבת התורה]\u0006 כן רק \u0003ב\u0004אכילת \u0003נבלה\u0004 שהומסה — \u0003הנך לא אתיא מינה\u0004 \u0005[אלה,\u0006 חמץ שהומס וחלב שהומס, \u0005לא היו באים\u0006 נלמדים \u0005ממנה],\u0006 שהרי יש בה חומרה אחרת שאין בהם, \u0003שכן\u0004 היא \u0003מטמאה\u0004 את האוכלה, מה שאין כן אלה. ומשום כך נצרכו כל שלוש הדרשות הללו.","ושואלים: אכן הלכה \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003מ\u0004הלכה \u0003חדא\u0004 \u0005[אחת]\u0006 אמנם \u0003לא אתיא\u0004 \u0005[אינה באה,\u0006 נלמדת\u0005],\u0006 וכפי שנתפרט למעלה, ואולם \u0003תיתי חדא מתרתי\u0004 \u0005[תבוא,\u0006 תילמד הלכה \u0005אחת משתים\u0006 האחרות\u0005]!\u0006 ותוהים: \u0003הי תיתי\u0004 \u0005[איזו\u0006 הלכה היא ש\u0005תבוא,\u0006 תילמד\u0005]?\u0006 אם \u0003לא לכתוב רחמנא\u0004 \u0005[לא תכתוב התורה]\u0006 \u0003בנבלה\u0004 שהומסה, \u0003ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה,\u0006 חמץ וחלב\u0005]\u0006 — יש פירכה בדבר, שכן יש לומר \u0003מה להנך\u0004 \u0005[לאלה]\u0006 שיש בהם צד חומרה שאינו באכילת נבילה, \u0003שכן ענוש כרת\u0004 עליהם!","ואם \u0003לא לכתוב רחמנא\u0004 \u0005[לא תכתוב התורה]\u0006 \u0003בחמץ\u0004 שהומס, \u0003ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה,\u0006 חלב ונבילה\u0005]\u0006 — יש פירכה בדבר, שכן יש לומר \u0003מה להנך\u0004 \u0005[לאלה],\u0006 שיש להם צד חומרה שאינו באכילת חמץ, \u0003שכן לא היתה להן שעת הכושר,\u0004 מה שאין כן בחמץ שהיתה לו שעת היתר (לפני הפסח).","ואם \u0003לא לכתוב רחמנא\u0004 \u0005[לא תכתוב התורה]\u0006 \u0003בחלב\u0004 שהומס, \u0003ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה,\u0006 חמץ ונבילה\u0005]\u0006 — יש פירכה בדבר, שכן יש לומר \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן לא הותר מכללן, תאמר בחלב שהותר מכללו!\u0004 ולכך נצרכו כל שלוש הדרשות הללו להיאמר.","\u0003ו\u0004מבררים: \u0003מאי ניהו\u0004 \u0005[מה הוא]\u0006 חלב שהותר מכללו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה ל\u0003חלב בהמה\u0004 שהותר \u0003לגבוה\u0004 (להקרבה בבית המקדש) — אין זה דבר שקיים רק באיסור חלב, שהרי אכילת \u0003נבלה נמי אשתראי\u0004 \u0005[גם כן הותרה]\u0006 ב\u0003מליקת\u0004 קרבן ה\u0003עוף לגבוה.\u0004 שכן המליקה של העוף עושה אותו לנבילה לאכילת אדם, ובכל זאת קרבנות העוף מצוותן היא במליקה!","\u0003ואלא\u0004 תאמר כי הכוונה היא ל\u0003חלב חיה\u0004 שהותרה אכילתו (מכלל כל החלבים) \u0003להדיוט,\u0004 מה שאין כן בחמץ ובנבילה — אף זו אינו צד חומרה המיוחד רק לאיסור חלב, שהרי אכילת \u0003נבלה נמי אשתראי\u0004 \u0005[גם כן הותרה]\u0006 לאכילת אדם, ב\u0003מליקה\u0004 של קרבן \u0003חטאת העוף\u0004 שנאכל העוף (שהוא נבילה, כיון שנמלק ולא נשחט) \u0003לכהנים!\u0004","ומשיבים: \u0003לעולם\u0004 צריך לפרש כי הכוונה היא שהותרה אכילתו של \u0003חלב חיה להדיוט, ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 \u0003לך\u0004 שגם באכילת נבילה מוצאים אנו שהותרה מכללה, שהרי ה\u0003כהנים\u0004 אוכלים מחטאת עוף שנמלק — אין זו פירכה, כיון שלא נחשב דבר זה כאכילת הדיוט, כי \u0003כהנים משלחן גבוה,\u0004 משולחנו של הקדוש ברוך הוא, \u0003קא זכו\u0004 \u0005[הם זוכים],\u0006 וכיון שהותר קרבן זה למזבח, הותר גם להם.","ושואלים עוד: \u0003והא דתניא\u0004 \u0005[וזה ששנינו\u0006 בברייתא\u0005]\u0006 על הכתוב באיסור אכילת השרצים \"אלה הטמאים לכם בכל השרץ\" (ויקרא יא, לא), שבאה המלה \u0003\"הטמאים\"\u0004 בלשון ריבוי \u0003לאסור\u0004 אף את \u0003צירן ורוטבן וקיפה שלהן, למה לי\u0004 פסוק מיוחד ללמדנו כן? \u0003ליגמר מהני\u0004 \u0005[שילמד מאלה,\u0006 חלב וחמץ ונבילה שהומסו\u0005]!\u0006","ומשיבים: \u0003צריכי\u0004 \u0005[צריכים]\u0006 הדברים להיכתב, \u0003דאי לא כתב רחמנא\u0004 \u0005[ש\u0006כן \u0005אם לא היתה כותבת התורה]\u0006 כך באכילת שרצים, והיינו למדים זאת מאלה — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003דיו לבא מן הדין\u0004 (הדבר הנלמד באחת מדרכי הלימוד, כהיקש) \u0003להיות כנדון\u0004 (כדבר המלמד). ומעתה הייתי אומר: \u0003מה התם\u0004 \u0005[שם,\u0006 באכילת חלב וחמץ ונבילה שהומסו\u0005]\u0006 אינו חייב על אכילתו אלא \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 שיעור \u0003כזית, אף הכא נמי\u0004 \u0005[כאן,\u0006 באכילת צירם ורוטבם של השרצים\u0005]\u0006 אינו חייב אלא \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003כזית,\u0004 לכן נכתבה דרשה מיוחדת לעניינם של הציר והרוטב והקיפה היוצא מן השרצים, ללמדנו שחייבים על אכילתם אף בשיעור כעדשה, כאכילת השרץ עצמו."],["ושבים ומקשים: \u0003וליכתוב רחמנא\u0004 \u0005[ושתכתוב התורה]\u0006 רק \u0003בשרצים\u0004 שצירם ורוטבם והקיפה שלהם אף הם אסורים באכילה, \u0003וליתו הנך וליגמרו מינייהו\u0004 \u0005[ויבואו אלה,\u0006 חלב וחמץ \u0005ונבלה שהומסו,\u0006 \u0005ויילמדו מהם],\u0006 ואין צורך בדרשות מיוחדות לכל אחד מאלה!","ומשיבים: אי אפשר ללמוד כך, \u0003משום דאיכא למיפרך\u0004 \u0005[שיש מקום לפרוך,\u0006 לשבור\u0005]\u0006 את ההיקש לשרצים, ולומר \u0003מה לשרצים שכן\u0004 יש בהם צד חומרה שאין בכל אלה, שהרי \u0003טומאתן\u0004 של השרצים היא \u0003במשהו.\u0004","למעלה התברר דינם של המשקים היוצאים מן השרצים, שנלמד מכתוב מיוחד, ולא מדינם של החלב והחמץ והנבילה שהומסו למשקים. \u0003ו\u0004מבררים עוד בהלכה \u0003הא\u0004 \u0005[זו]\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 בברייתא\u0005]\u0006 כי \u0003הטבל\u0004 (הפירות האסורים באכילה משום שעדיין לא הופרשו מהם התרומות ומעשרות), \u0003והחדש\u0004 (התבואה של שנה זו, שלא הותרה עדיין באכילה על ידי הנפת העומר), \u0003ו\u0004פירות של \u0003ההקדש, ו\u0004פירות השנה \u0003השביעית\u0004 (שנת השמיטה), האסורים באכילה לאחר הביעור, \u0003ו\u0004פירות \u0003הכלאים\u0004 (הכרם בו נזרעו תבואות) — בכל אלה \u0003כולן\u0004 דין ה\u0003משקין היוצאין מהן\u0004 מן הפירות הוא \u0003כמותן,\u0004 שאף המשקים אסורים באכילה. ומבררים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 הלכה זו?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003ליגמר מהנך\u0004 \u0005[שנלמד מאלה,\u0006 חלב וחמץ ונבילה ושרצים שהומסו\u0005]\u0006 — יש צד פירכה על השוואה זו, שיש לומר: \u0003מה להנך\u0004 \u0005[לאלה,\u0006 חלב, חמץ, נבילה ושרצים\u0005]\u0006 שיש בהם צד חומרה שאין בפירות הללו שרוצים אנו ללומדם מהם, \u0003שכן איסור הבא מאליו\u0004 (מעצמו, ובלא מעורבות אדם בדבר) \u0003הוו\u0004 \u0005[הם],\u0006","ומעתה \u0003תינח היכא\u0004 \u0005[נניח,\u0006 יפה הדבר \u0005במקום]\u0006 שהאיסור הנלמד הוא \u0003איסור\u0004 ה\u0003בא מאליו,\u0004 וכגון הטבל והחדש והשביעית והכלאיים, ואולם \u0003היכא\u0004 \u0005[במקום]\u0006 \u0003דלאו\u0004 \u0005[שאין]\u0006 זה \u0003איסור הבא מאליו,\u0004 כבפירות ההקדש (שהוקדשו למקדש בידי אדם) \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שהמשקים היוצאים מהם אסורים באכילה כמותם?","ומשיבים: \u0003גמרינן\u0004 \u0005[למדים אנו]\u0006 דין זה \u0003מבכורים,\u0004 שאף שאין זה איסור הבא מאליו (שהרי האדם הוא המפריש את הביכורים מפירות אדמתו), בכל זאת דין המשקים היוצאים מן הפירות הוא כדין הפירות עצמם. ושואלים: \u0003ובכורים גופייהו מנלן\u0004 \u0005[עצמם מנין לנו]\u0006 שכך הוא דינם?","\u0003דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003ר' יוסי\u0004 על הכתוב במצות הביכורים \"ולקחת מראשית כל פרי האדמה אשר תביא מארצך\" (דברים כו, ב): המלה \u0003\"פרי\"\u0004 יש בה להורות כי דווקא \u0003פרי אתה מביא\u0004 למצות הביכורים, \u0003ואי\u0004 (ואין) \u0003אתה מביא משקה\u0004 למצות הביכורים. ואולם אם \u0003הביא\u0004 למקדש כביכורים מכרמו \u0003ענבים, ודרכן\u0004 ועשה מהם יין, \u0003מנין\u0004 שקיים בכך מצות ביכורים? \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) \"אשר \u0003תביא\"\u0004 — שהיא לשון ריבוי, ללמד שאף משקים בכלל זה.","אולם \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את ההשוואה לביכורים ולומר: \u0003מה לבכורים שכן\u0004 יש בהם צד חומרה שאין בפירות הקדש, שהרי הביכורים \u0003טעונין\u0004 (חייבים) \u0003קרייה\u0004 (קריאה), אמירת פרשת \"ארמי אובד אבי\" (שם ה-י), \u0003והנחה\u0004 של פירות הביכורים במקדש (\"והנחתו לפני ה' אלהיך והשתחוית לפני ה' אלהיך\". שם, י). מה שאין כן בפירות הקדש!","\u0003אלא גמר\u0004 \u0005[למד]\u0006 דין פירות הקדש שנימוחו \u0003מ\u0004דין פירות \u0003תרומה\u0004 שנימוחו.","ושואלים: \u0003ותרומה גופה מנלן\u0004 \u0005[עצמה מנין לנו]\u0006 שכך הוא דינה? \u0003דאיתקש\u0004 \u0005[ש\u0006כן \u0005הוקשתה\u0006, הושוותה\u0005]\u0006 \u0003לבכורים,\u0004 שכך \u0003אמר מר\u0004 \u0005[החכם]\u0006 בפירוש הכתוב \"לא תוכל לאכול בשעריך מעשר דגנך ותירושך ויצהרך ובכורות בקרך וצאנך\" (שם יב, יז) כי הביטוי \u0003\"ותרומת ידך\"\u0004 — \u0003אלו\u0004 ה\u0003בכורים.\u0004 הרי שהביכורים מכונים \"תרומה\", ומעתה כשם שבביכורים דין המשקים היוצאים מן הפרי הריהו כפרי, כן בתרומה דין המשקים היוצאים מן הפרי הריהו כפרי. ובאו משקים היוצאים מפירות הקדש ולמדים ממשקים היוצאים מפירות התרומה.","ומקשים על כך: הרי אפשר לפרוך השוואה זו, ולומר: \u0003מה לתרומה שכן\u0004 יש בה צד חומרה, שהרי הזרים (שאינם כהנים) האוכלים אותה \u0003חייבין עליה מיתה\u0004 בידי שמים \u0003ו\u0004תשלום \u0003חומש\u0004 (חמישית בנוסף לתשלום הקרן), מה שאין כן באכילת פירות הקדש!","\u0003אלא\u0004 תאמר כי \u0003גמר\u0004 \u0005[למד]\u0006 דין משקים היוצאים מפירות ההקדש \u0003מתרוייהו\u0004 \u0005[משניהם],\u0006 \u0003מתרומה ובכורים\u0004 — גם על כך יש מקום פירכה: \u0003מה לתרומה ובכורים שכן חייבין עליהם מיתה ו\u0004תשלום \u0003חומש!\u0004","\u0003אלא, אתיא\u0004 \u0005[באה,\u0006 נלמד\u0005]\u0006 דין משקים בפירות הקדש \u0003מ\u0004דין משקים היוצאים מפירות ה\u0003תרומה ו\u0004מדין משקים של \u0003חד מהנך\u0004 \u0005[אחד מאלה,\u0006 חמץ או נבילה\u0005],\u0006 \u0003או\u0004 שלמדים \u0003מבכורים וחד מהנך\u0004 \u0005[ואחד מאלה].\u0006","למעלה התברר דין המשקים היוצאים מפירות הקדש שהוא כדין הפירות עצמם, \u0003והא דתנן\u0004 \u0005[וזהו ששנינו\u0006 במשנה\u0005]\u0006 כי הזר (זה שאינו כהן) השותה יין או שמן של תרומה חייב כאוכל את הפירות עצמם, שהרי אמרה תורה כי השמן והיין חייבים בתרומה (\"כל חלב יצהר וכל חלב תירוש\". במדבר יח, יב). שכל דיני תרומה נוהגים בהם, שהרי עומדים הענבים והזיתים לעשות מהם יין ושמן. ואולם פירות אחרים שעיקרם אינו לשתיה אלא לאכילה — אין אדם רשאי לעשות מהם משקים, שהרי בכך הוא מפחית מחשיבותם של הפירות. ואם עבר אדם ועשה \u0003דבש\u0004 מפירות \u0003תמרים\u0004 של תרומה, \u0003ויין\u0004 מ\u0003תפוחים, וחומץ\u0004 מ\u0003סיתווניות\u0004 (ענבים שנגמר בישולם בתקופת הסתיו, ועושים מהם חומץ), \u0003ושאר מיני פירות של תרומה\u0004 שסחטם למיצם — \u0003ר' אליעזר מחייב\u0004 את האוכלם בשוגג בתשלום \u0003קרן וחומש,\u0004 וכדין האוכל את הפירות עצמם. \u0003ו\u0004אילו \u0003ר' יהושע פוטר\u0004 אותו מתשלום חומש.","ומבררים: \u0003במאי פליגי\u0004 \u0005[במה נחלקו]\u0006 ר' אליעזר ור' יהושע? — \u0003ב\u0004דרכי הלימוד, האם כאשר למדים אנו הלכה אחת מהלכה אחרת באחת מדרכי הלימוד (כגזירה שווה או בנין אב). שאחד סבור כי אומרים אנו: \u0003דון\u0004 (למד) \u0003מינה\u0004 \u0005[ממנה,\u0006 מן ההלכה המלמדת\u0005]\u0006 את עיקרו של הדין, \u0003ו\u0004הוסף ולמד \u0003מינה\u0004 \u0005[ממנה]\u0006 גם את שאר העניינים האמורים בה. \u0003ו\u0004אילו האחר סבור כי אומרים אנו \u0003ב\u0004דרך הלימוד כי \u0003דון\u0004 (למד) \u0003מינה\u0004 \u0005[ממנה,\u0006 מן ההלכה המלמדת\u0005]\u0006 את עיקרו של הדין, \u0003ו\u0004אולם \u0003אוקי באתרה\u0004 \u0005[העמד\u0006 אותה \u0005במקומה]\u0006 ואל תלמד הלאה בשאר ענייניה, בזאת \u0003קמיפלגי\u0004 \u0005[הם חלוקים].\u0006","ומפרטים: ש\u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 שאומרים אנו \u0003דון מינה ומינה\u0004 \u0005[למד ממנה וממנה],\u0006 ומעתה יש לומר: \u0003מה בכורים\u0004 — דין ה\u0003משקין היוצא מהן\u0004 הוא \u0003כמותן,\u0004 כמו הפירות עצמם. \u0003אף\u0004 ב\u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 דין ה\u0003משקין היוצא מהן\u0004 הוא \u0003כמותן, ומינה\u0004 \u0005[וממנה]\u0006 אתה למד עוד לומר: \u0003מה בכורים\u0004 — באים לא רק מן הענבים ומן הזיתים, אלא \u0003אפילו\u0004 מ\u0003שאר מינין\u0004 (שבכלל שבעת המינים). ואף דין המשקים של שאר הפירות בביכורים הוא כדין הפירות עצמם. \u0003אף תרומה נמי\u0004 \u0005[גם כן]\u0006 דין המשקים היוצאים מפירותיה אינו רק בענבים וזיתים, אלא \u0003אפילו\u0004 ב\u0003שאר מינין. ו\u0004אילו","\u0003ר' יהושע סבר\u0004 \u0005[סבור]\u0006 שאכן אומרים אנו \u0003דון\u0004 \u0005[למד ממנה],\u0006 ומעתה: \u0003מה בכורים\u0004 — דין ה\u0003משקין היוצאין מהן\u0004 הוא \u0003כמותן,\u0004 כמו הפירות עצמם. \u0003אף\u0004 ב\u0003תרומה\u0004 דין ה\u0003משקין היוצאין מהן\u0004 הוא \u0003כמותן, ו\u0004אולם \u0003אוקי באתרה\u0004 \u0005[העמד\u0006 אותה \u0005במקומה]:\u0006 \u0003מה משקין\u0004 ש\u0003קדשים\u0004 \u0005[מקדישים,\u0006 מפרישים\u0005]\u0006 אותם \u0003בתרומה,\u0004 רק \u0003תירוש ויצהר\u0004 (יין ושמן) — \u0003אין\u0004 \u0005[כן],\u0006 ואולם \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא.\u0004 ומכאן נלמד כי \u0003אף משקין היוצאין מהן כמותן\u0004 בפירות התרומה, דווקא \u0003תירוש ויצהר\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חייבים עליהם בתשלומים, ואילו \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא\u0004 חייבים עליו.","\u0003ו\u0004מבררים: \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]\u0006 כי \u0003אין מביאין\u0004 למקדש \u0003בכורים\u0004 מכל \u0003משקה\u0004 היוצא מן הפירות, \u0003אלא\u0004 ממשקה \u0003היוצא מן הזיתים ומן הענבים\u0004 בלבד, כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006","— \u0003ר' יהושע היא,\u0004 ש\u0003אמר: דון מינה ואוקי באתרה\u0004 \u0005[למד ממנה והעמד במקומה].\u0006 וכיון שדין תרומה נלמד מדין בכורים רק לענין יין ושמן, ושב \u0003וגמר להו\u0004 \u0005[ולמד אותם]\u0006 את דין ה\u0003בכורים מ\u0004דין \u0003ה\u0004\u0003תרומה,\u0004 הרי זה בא ללמדנו שאף לענין הביכורים דין המשקה היוצא מן הפירות כדין הפירות אינו אלא בשמן ויין בלבד. ואילו לדעת ר' אליעזר הלמד דין התרומה מדין הביכורים אף לשאר משקים, מעתה להביא ביכורים למקדש אף ממשקים הבאים משאר פירות. ושלא כדברי משנה זו.","\u0003ו\u0004\u0003עוד מבררים:\u0004 \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]\u0006 כי \u0003אין סופגין\u0004 (לוקים) \u0003את הארבעים\u0004 מלקות \u0003משום\u0004 שתיית משקה היוצא מפירות \u0003ערלה אלא על\u0004 המשקה \u0003היוצא מן\u0004 פירות \u0003הזיתים ומן הענבים,\u0004 ולא על משקים אחרים, כשיטת \u0003מני\u0004 \u0005[מי היא]?\u0006","— כשיטת \u0003ר' יהושע היא,\u0004 ש\u0003אמר: דון מינה ואוקי באתרה\u0004 \u0005[למד ממנה והעמד אותה במקומה],\u0006 \u0003וגמר להו\u0004 \u0005[ולמד אותם]\u0006 את דין ה\u0003בכורים מתרומה,\u0004 שאין דין המשקים היוצאים מפירות התרומה כדין הפירות עצמם אלא בשמן וביין."],["\u0003והדר מייתי לה\u0004 \u0005[ואחר כך מביא,\u0006 לומד \u0005אותה]\u0006 את ההלכה בעניינם של המשקים היוצאים מפירות ה\u0003ערלה,\u0004 מגזירה שווה של המלים \u0003\"פרי\"\u0004 האמור באיסור ערלה (\"וערלתם ערלתו את פריו\". ויקרא יט, כג), ו\u0003\"פרי\"\u0004 הנאמר במצות \u0003בכורים\u0004 (\"ולקחת מראשית כל פרי האדמה\". דברים כו, ב). ללמדנו שכשם שאין בביכורים דין המשקים כדין הפירות אלא ב\u0003זיתים וענבים, כך הוא גם בדינם של המשקים היוצאים משאר פירות לענין ערלה, שאין חייבים מלקות על שתייתם.\u0004","\u0003ו\u0004שנינו במשנתנו בין הדברים המצטרפים עם הבשר להשלים שיעורו לענין טומאת אוכלים, אף שהם עצמם אינם נאכלים, את \u0003האלל.\u0004 ונחלקו חכמים \u0003מאי\u0004 \u0005[מה]\u0006 טיבו של ה\u0003אלל.\u0004 ש\u0003ר' יוחנן אמר\u0004 כי הכוונה היא ל\u0003מרטקא\u0004 \u0005[גיד השדרה והצוואר],\u0006 \u0003וריש לקיש אמר\u0004 שהכוונה היא לשאריות \u0003בשר\u0004 הנותרות על העור לאחר \u0003שפלטתו\u0004 (חתכה) ה\u0003סכין\u0004 את הבשר מן העור.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על פירושו של ריש לקיש מן הכתוב \u0003\"ואולם אתם טופלי שקר רופאי אליל כולכם\"\u0004 (איוב יג, ד), ובאה בו המלה \"אליל\" בכתיב חסר \"אלל\". \u0003בשלמא למאן דאמר\u0004 \u0005[נניח לשיטת\u0006 ר' יוחנן \u0005שאומר]\u0006 שהכוונה היא ל\u0003מרטקא\u0004 — \u0003היינו\u0004 \u0005[זהו]\u0006 שטען איוב נגד חבריו האומרים לו דברים שאין בהם תועלת לו, שהריהם כבאים לרפא את המרטקא \u0003דלאו בר\u0004 \u0005[שלא בן]\u0006 \u0003רפואה הוא,\u0004 \u0003אלא למאן דאמר\u0004 \u0005[לשיטת\u0006 ריש לקיש \u0005שאומר]\u0006 כי הכוונה היא ל\u0003בשר שפלטתו סכין,\u0004 והלא בשר שכזה \u0003בר\u0004 \u0005[בן]\u0006 \u0003רפואה הוא,\u0004 שהבשר המתדלדל מן החי, \u0003ניתן לאיחוי!\u0004","ומשיבים: \u0003ב\u0004משמעות המלה \u0003\"אלל\" דקרא\u0004 \u0005[שבמקרא]\u0006 מוסכם על הכל, ואף לדעת ריש לקיש, שהכוונה היא לגיד השדרה והצוואר, \u0003דכולי עלמא לא פליגי\u0004 \u0005[ש\u0006כן בכך \u0005הכל אינם חלוקים],\u0006 שכך הוא בלשון מקרא. ואולם \u0003כי פליגי\u0004 \u0005[כאשר חלוקים]\u0006 ר' יוחנן וריש לקיש הרי זה \u0003ב\u0004פירוש המלה \u0003\"אלל\" דמתניתין\u0004 \u0005[של משנתנו],\u0006 בלשון חכמים, ולדעת ריש לקיש משמעה הוא בשר שפלטתו סכין.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לריש לקיש ממה ששנינו במשנתנו \u0003ש\u0004\u0003ר' יהודה אומר\u0004 כי \u0003האלל\u0004 של הנבילה \u0003המכונס\u0004 במקום אחד, \u0003אם יש\u0004 בו שיעור \u0003כזית\u0004 הנמצא \u0003במקום אחד\u0004 — \u0003חייבין עליו\u0004 אם אכלוהו משום נבילה, ואם נגעו בו ונכנסו למקדש, משום ביאת מקדש בטומאה, \u0003ו\u0004בהסבר דברי ר' יהודה אלה \u0003אמר רב הונא: ו\u0004אין מדובר אלא אם אדם \u0003הוא\u0004 זה \u0003שכנסו\u0004 לאלל זה במקום אחד, ולא שהתכנס האלל מאליו או על ידי תינוקות. שכיון שכינסו, גילה בכך דעתו שהריהו מחשיבו כבשר. ומעתה יש לומר:","\u0003בשלמא למאן דאמר\u0004 \u0005[נניח,\u0006 מובן הדבר, \u0005ל\u0006דעת \u0005מי שאומר,\u0006 ריש לקיש\u0005]\u0006 כי הכוונה היא ל\u0003בשר שפלטתו סכין\u0004 — \u0003היינו\u0004 \u0005[זהו]\u0006 הטעם לשיטת ר' יהודה \u0003דכי איכא\u0004 \u0005[שכאשר יש]\u0006 מן האלל המכונס (בידי אדם) שיעור \u0003כזית, מיחייב\u0004 \u0005[הריהו מתחייב]\u0006 על כך, שהרי החשיבו לבשר. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר,\u0006 ר' יוחנן\u0005]\u0006 שהכוונה היא \u0003ל\u0004\u0003מרטקא\u0004 — גם \u0003כי איכא\u0004 \u0005[כאשר יש]\u0006 אלל בשיעור \u0003כזית\u0004 במקום אחד, \u0003מאי הוי\u0004 \u0005[מה נהיה,\u0006 מה בכך\u0005]?\u0006 והלא האלל \u0003עץ בעלמא\u0004 \u0005[סתם]\u0006 \u0003הוא,\u0004 שאינו ראוי למאכל!","ומשיבים: אכן \u0003אליבא\u0004 \u0005[לפי שיטתו]\u0006 של \u0003ר' יהודה לא פליגי\u0004 \u0005[אינם חלוקים\u0006 ר' יוחנן וריש לקיש\u0005],\u0006 והכל מודים כי לדעת ר' יהודה האלל הוא בשר שפלטתו סכין. ואולם \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 ר' יוחנן וריש לקיש בפירוש המלה \"אלל\" \u0003אליבא דרבנן\u0004 \u0005[לפי שיטת חכמים]\u0006 נחלקו. ש\u0003ר' יוחנן אמר\u0004 כי לדעת חכמים \u0003מרטקא נמי\u0004 \u0005[גם כן]\u0006 \u0003מצטרף\u0004 להשלים לשיעור כביצה לטומאת אוכלים. \u0003ו\u0004אילו \u0003ריש לקיש אמר\u0004 כי אמרו חכמים את דבריהם \u0003דוקא\u0004 ב\u0003בשר שפלטתו סכין, אבל\u0004 ב\u0003מרטקא\u0004 סבורים חכמים כי \u0003לא מצטרף\u0004 לבשר להשלים לשיעור כביצה.","ומבררים: \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003בשר שפלטתו סכין\u0004 ששנינו בו שהריהו מצטרף לבשר להשלים לשיעור כביצה, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן \u0003דחשיב עליה\u0004 \u0005[שחשב עליו]\u0006 לאוכלו — מדוע אמרו שאינו נחשב לענין הטומאה אלא רק מצטרף לבשר, \u0003אפילו באנפי נפשיה\u0004 \u0005[בפני עצמו]\u0006 יהא \u0003מיטמא,\u0004 כשאר אוכלים! \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003דלא חשיב עליה\u0004 \u0005[שלא חשב עליו]\u0006 לאוכלו — מדוע מצטרף לבשר לענין טומאת אוכלים, והרי \u0003בטוליה בטליה\u0004 \u0005[ביטל אותו]\u0006 במחשבתו מכלל מאכל!","ואומרים כי \u0003ר' אבין ור' מיישא\u0004 תירצו שאלה זו, \u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר\u0004 שמדובר באופן שעל \u0003מקצתו\u0004 של הבשר שפלטתו הסכין \u0003חישב עליו\u0004 לאוכלו, ולא פירש באיזה חלק מבשר זה היתה מחשבתו. ולכך אין בשר זה שעל העור מטמא, שהרי לא חשב על כולו לאוכלו. ואולם אותו מקצת שחשב עליו לאוכלו, מצטרף לבשר להשלים שיעורו לכביצה.","\u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר\u0004 שמדובר באופן שלא חישב האדם כלל על בשר זה שעל העור לאוכלו, ואולם \u0003מקצתו\u0004 של אותו בשר שעל העור בתחילה \u0003פלטתו חיה\u0004 (כגון כלב) שנשכה את הבהמה, ואחר כך שחט אדם את הבהמה \u0003ו\u0004את \u0003מקצתו\u0004 האחרת של בשר זה שעל העור \u0003פלטתו\u0004 ה\u0003סכין\u0004 שבידי אדם. ואין אנו יודעים איזה חלק הוא זה שפלטתו החיה ואיזהו החלק שפלטו האדם. שהחלק שפלטתו החיה \u0003לא ביטל אותו מדעתו מכלל אכילה, ומאחר ואין אנו יודעים איזה הוא חלק זה, לכך אין בשר זה מטמא, אולם הוא מצטרף לשאר הבשר.\u0004","שנינו במשנתנו כי הקרנים מצטרפות לבשר להשלימו לשיעור לענין טומאת אוכלים, ובענין זה מביאים מה ש\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה במסכת טהרות\u0005]\u0006 כי \u0003החרטום\u0004 (מקור) \u0003והצפרנים\u0004 שבעוף \u0003מיטמאין\u0004 אם נגע בהם שרץ, \u0003ו\u0004אם טמאים הם ונגעו באוכלים טהורים הריהם \u0003מטמאין\u0004 אותם (שכן הם נחשבים כיד לענין שתיכנס ותצא הטומאה על ידם) \u0003ומצטרפין\u0004 לשיעור כזית לענין טומאת העוף הטהור, ולשיעור כביצה לענין טומאת אוכלים. ותוהים: והלא ה\u0003חרטום עץ בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא,\u0004 ומדוע הוא מצטרף עם הבשר כאוכל?","\u0003אמר ר' אלעזר\u0004 בהסבר הדברים כי מדובר כאן \u0003בחרטום\u0004 ה\u0003תחתון.\u0004 ומקשים: והרי החרטום ה\u0003תחתון נמי\u0004 \u0005[גם כן]\u0006 \u0003עץ בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא! אמר רב פפא:\u0004 אין הכוונה אלא לחלק החרטום \u0003ה\u0004\u0003תחתון של עליון,\u0004 כלומר, הקרום הבשרי שבתוך הפה הדבוק לחרטום העליון לאורכו.","וכן מה ששנינו שם כי ה\u0003צפרנים\u0004 מצטרפות \u0003אמר ר' אלעזר\u0004 כי אין הכוונה לציפורניים עצמן, אלא \u0003ל\u0004\u0003מקום\u0004 שורשי הציפורניים, \u0003המובלעים בבשר.\u0004","וכן מה ששנינו במשנתנו כי ה\u0003קרנים\u0004 מצטרפות לבשר לענין שיעור טומאת אוכלים, \u0003אמר רב פפא\u0004 כי הכוונה היא \u0003במקום שחותכין\u0004 את הקרניים \u0003ויוצא מהן דם\u0004 ולא למעלה שהוא קשה לגמרי.","שנינו במשנתנו כי \u0003כיוצא בו\u0004 (בבשר המטמא טומאת אוכלים ואין הוא מטמא טומאת נבילות) הוא \u0003השוחט בהמה\u0004 טמאה לצורך גוי, ועדיין הבהמה מפרכסת, ש","מטמאה טומאת אוכלים אבל לא טומאת נבילות. ובענין זה \u0003אמר ר' אסי\u0004 כי יש מן החכמים ש\u0003שונין\u0004 בדין טומאת הבהמה שנשחטה ועודה מפרכסת כך: \u0003ישראל ב\u0004זמן ששחט בהמה \u0003טמאה, ו\u0004כן \u0003גוי ב\u0004זמן ששחט בהמה \u0003טהורה\u0004 — אין די בעצם שחיטתה שתהא הבהמה נחשבת כאוכל (לקבלת טומאת אוכלים), אלא \u0003צריכין\u0004 השוחטים את הבהמה לחשוב \u0003מחשבה\u0004 שתהא נאכלת (לגוי) כפי שהיא עתה, \u0003ו\u0004כן יש צורך ב\u0003הכשר מים\u0004 (או שאר המשקים המכשירים לקבל טומאה), הבאים \u0003ממקום אחר,\u0004 שאין דם השחיטה של בהמה זו מכשירה לקבל טומאה, כיון שהרי זו דם הבאה מהשחיטה הראויה.","ותוהים: \u0003הכשר\u0004 משקים לשם קבלת טומאת אוכלים \u0003למה לי?\u0004 והלוא \u0003סופו\u0004 של בשר בהמה זו, לכשתמות, \u0003לטמא טומאה חמורה\u0004 (טומאת נבילה), \u0003ו\u0004כלל הוא בדיני טומאה כי \u0003כל\u0004 דבר \u0003שסופו לטמא טומאה חמורה, לא בעי\u0004 \u0005[צריך]\u0006 \u0003הכשר,\u0004 והריהו מקבל טומאת אוכלים אף בלא שהוכשר בנתינת משקה עליו.","\u0003דתני דבי\u0004 \u0005[ש\u0006כן \u0005שנה\u0006 החכם \u0005של בית]\u0006 מדרשו של \u0003ר' ישמעאל\u0004 על הנאמר בדין הכשר משקים \u0003\"וכי יותן מים על זרע\u0004 ונפל מנבלתם עליו טמא הוא לכם\" (ויקרא יא, לח) \u0003מה זרעים שאין סופן לטמא טומאה חמורה, צריכין הכשר. אף כל\u0004 דבר מאכל \u0003שאין סופו לטמא טומאה חמורה צריך הכשר.\u0004 יצא מכלל זה הדבר שסופו לקבל טומאה חמורה (כטומאת הנבילה) שאין צריך הכשר משקים כדי לקבל טומאת אוכלים.","\u0003ו\u0004כן \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי: מפני מה אמרו\u0004 חכמים כי \u0003נבלת עוף טהור צריכה מחשבה\u0004 לאכילה, על מנת שתטמא, \u0003ו\u0004אולם \u0003אינה צריכה הכשר\u0004 משקים? \u0003מפני\u0004"],["\u0003שסופה\u0004 של נבילה זו של העוף הטמא שתבוא \u0003לטמא\u0004 את האדם האוכלה \u0003טומאה חמורה\u0004 בשעה שהיא בבית הבליעה. ולכך אין נבלת העוף צריכה להכשר מים כדי לטמא טומאת אוכלים!","\u0003אמר חזקיה\u0004 בתשובה: טעמם של חכמים (שהביא ר' אסי את דבריהם) שהצריכו הכשר מים לבהמה המפרכסת הוא \u0003הואיל ויכול\u0004 עתה השוחט את הבהמה הזו \u0003לגוררה\u0004 (לחותכה) כולה לפיסות בשר קטנות שאין בכל אחת מהן שיעור כזית (ולכך אינה נטמאת בטומאת נבילה), \u0003ולהעמידה\u0004 לבהמה זו כולה \u0003על\u0004 שיעור שהוא \u0003פחות מכזית.\u0004 ונמצא שאין זה ברור שסופה של הבהמה המפרכסת לבוא לכלל טומאת נבילות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' זירא\u0004 בתמיהה על תשובה זו: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר חזקיה הכי\u0004 \u0005[כך]?\u0006 \u0003והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו חזקיה ור' יוחנן בדינה של הבהמה ש\u0003שחט בה\u0004 בבהמה טמאה \u0003שנים\u0004 (שני הסימנים שבצוואר: הוושט והקנה) \u0003או\u0004 ששחט בה \u0003רוב שנים,\u0004 שהיא השחיטה המכשירה את הבהמה הטהורה לאכילה לישראל, \u0003ועדיין היא,\u0004 הבהמה, \u0003מפרכסת. חזקיה אמר:\u0004 בהמה זו \u0003אינה\u0004 בכלל איסור \u0003לאברים\u0004 שבה, שאין בה איסור אבר מן החי, ולכך מותר הגוי (האסור באכילת אבר מן החי) באכילתה. ואילו \u0003ר' יוחנן אמר\u0004 כי בהמה זו \u0003ישנה\u0004 בכלל איסור אבר מן החי \u0003לאברים\u0004 שבה.","והם מנמקים את דבריהם: \u0003חזקיה אמר\u0004 שהבהמה \u0003אינה\u0004 אסורה \u0003לאברים,\u0004 שהרי \u0003מתה היא\u0004 כיון שנשחטו בה שני סימניה או רובם. ואילו \u0003ר' יוחנן אמר\u0004 כי בהמה זו \u0003ישנה\u0004 עדיין באיסורה \u0003לאברים\u0004 כי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003מתה היא,\u0004 שהרי היא עדיין מפרכסת. הרי איפוא שלדעת חזקיה בהמה זו נחשבת כמי שכבר מתה למרות שהיא עדיין מפרכסת, ומעתה מדוע לא תיחשב גם כן כמתה לענין טומאת נבילות?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לר' ירמיה בתשובה לשאלתו: לדעת חזקיה בהמה זו \u0003יצתה\u0004 (יצאה) \u0003מכלל חיה\u0004 (לענין שאין עוד באבריה איסור אבר מן החי), \u0003ו\u0004אולם \u0003לכלל מתה\u0004 היא עדיין \u0003לא באת\u0004 (באה), \u0003ולכך אין בה עדיין טומאת נבילות.\u0004","למעלה הובאה מחלוקתם של חזקיה ור' יוחנן בדינה של בהמה שנשחטה ועדיין היא מפרכסת. ועתה דנים במחלוקת זו ל\u0003גופא\u0004 \u0005[לעצמה].\u0006 בהמה ש\u0003שחט בה שנים\u0004 (סימנים, קנה וושט), \u0003או רוב שנים, ועדיין היא מפרכסת. חזקיה אמר\u0004 כי היא \u0003אינה לאברים,\u0004 ואילו \u0003ר' יוחנן אמר\u0004 שהיא \u0003ישנה לאברים. אמר ר' אלעזר\u0004 בהכרעת המחלוקת להלכה: \u0003נקוט להא\u0004 \u0005[תפוס,\u0006 קבל כהלכה למעשה \u0005את\u0006 דעה \u0005זו]\u0006 של \u0003ר' יוחנן בידך,\u0004 ומשום \u0003דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003רב אושעיא כוותיה\u0004 \u0005[כמותו]\u0006 בברייתא.","\u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב אושעיא: ישראל ששחט בהמה טמאה ל\u0004אכילתו של \u0003גוי,\u0004 אם \u0003שחט בה שנים\u0004 סימנים \u0003או רוב שנים, ו\u0004עדיין הבהמה \u0003מפרכסת\u0004 לאחר השחיטה — בהמה זו \u0003מטמאה טומאת אוכלין,\u0004 כיון שנחשבת היא עתה כאוכל (ומטמאת אוכל אחר), \u0003אבל\u0004 היא \u0003לא\u0004 נטמאת ומטמאת ב\u0003טומאת נבלות\u0004 כל עוד היא מפרכסת.","\u0003אבר הפורש ממנה\u0004 מבהמה זו שנשחטה ועדיין מפרכסת נחשב \u0003כפורש מן החי\u0004 שהוא מטמא עתה בטומאת נבילות, כדינו של כל אבר מן החי. \u0003ו\u0004דינו של ה\u0003בשר הפורש ממנה כ\u0004דינו של ה\u0003בשר הפורש מן החי,\u0004 שאמנם אין הוא נחשב לענין טומאת אוכלים, \u0003ו\u0004אולם הוא \u0003אסור\u0004 באכילה \u0003לבני נח. ו\u0004אסור בשר זה שפרש מן הבהמה בעודה מפרכסת באכילה \u0003אפילו לאחר שתצא נפשה.\u0004 הרי שברייתא זו היא כדעת ר' יוחנן הסבור שיש איסור אבר מן החי בבהמה המפרכסת, ושלא כדעת חזקיה.","ומאחר והובא חלקה הראשון של הברייתא (כראיה לשיטת ר' יוחנן) מביאים את המשך דבריה: ואם הישראלי \u0003שחט בה\u0004 בבהמה הטמאה שנשחטה לאכילת הגוי לא את שני סימניה אלא סימן \u0003אחד\u0004 בלבד \u0003או רוב\u0004 סימן \u0003אחד,\u0004 ומפרכסת הבהמה לאחר שחיטתה — אין זו כדרך שחיטה ראויה, ולכך \u0003אינה מטמאה טומאת אוכלין.\u0004 וכיוצא בזה אם לא שחטה אלא \u0003נחרה\u0004 (הרג אותה שלא בשחיטה) — \u0003אין בה טומאה של כלום. ו\u0004הוא הדין ב","\u0003גוי ששחט בהמה טהורה לישראל, ומפרכסת\u0004 הבהמה לאחר שחיטתה — נחשבת היא כאוכל לענין שהיא \u0003מטמאה טומאת אוכלין, אבל\u0004 היא \u0003לא\u0004 נטמאת ומטמאת ב\u0003טומאת נבלה.\u0004","\u0003אבר הפורש ממנה\u0004 מבהמה זו שנשחטה ועדיין מפרכסת נחשב \u0003כפורש מן החי\u0004 לענין שהוא מטמא עתה בטומאת נבילות, כדינו של כל אבר מן החי. \u0003ו\u0004דינו של ה\u0003בשר הפורש ממנה כ\u0004דינו של ה\u0003בשר הפורש מן החי,\u0004 שאינו נחשב לענין טומאת אוכלים, \u0003ו\u0004אולם הוא \u0003אסור\u0004 באכילה \u0003לבני נח. ו\u0004אסור בשר זה שפרש מן הבהמה בעודה מפרכסת \u0003אפילו לאחר שתצא נפשה.\u0004","ואם \u0003שחט בה\u0004 הגוי בבהמה הטהורה סימן \u0003אחד או רוב\u0004 סימן \u0003אחד\u0004 — \u0003אינה מטמאה טומאת אוכלין.\u0004 וכיוצא בדבר אם \u0003נחרה\u0004 — \u0003אין בה טומאה של כלום.\u0004","ובמקרה שבו \u0003שחט\u0004 ה\u0003גוי\u0004 בהמה טהורה \u0003במקום שאין\u0004 שחיטתו \u0003עושה אותה טרפה\u0004 (כששחט רק חלק מן הסימנים, כגון חצי קנה, ובכך אין הבהמה נטרפת) \u0003ובא ישראל וגמרה\u0004 לשחיטה זו, שחתך את אותו הסימן ואת הסימן האחר, כולו או רובו — בהמה זו \u0003כשרה\u0004 לאכילה, שהרי נשחטה בידי ישראל.","ואולם אם \u0003שחט ישראל, בין במקום שעושה אותה טרפה\u0004 (ששחט רובו של סימן, שבכך הבהמה נטרפת), \u0003ובין במקום שאין עושה אותה טרפה\u0004 (ששחט רק חלק מן הסימן), \u0003ובא גוי וגמר\u0004 את שחיטתו של הישראל — \u0003שחיטתו פסולה.\u0004","ומוסיפה עוד הברייתא: זה \u0003הרוצה שיאכל מ\u0004בשרה של \u0003בהמה\u0004 שנשחטה \u0003קודם שתצא נפשה,\u0004 משום שיפה בשר זה לבריאות, כיצד יעשה? הריהו \u0003חותך כזית בשר מבית שחיטתה\u0004 (מקום השחיטה), \u0003ומולחו יפה יפה\u0004 יותר מבשר אחר, שכן עדיין לא הספיק הדם לצאת, ובשעה שחותך הוא מבשר זה נבלע הדם בו, \u0003ומדיחו\u0004 במים לאחר המליחה \u0003יפה יפה,\u0004 להסיר את המלח והדם, \u0003וממתין לה עד שתצא נפשה, ואוכלו. אחד גוי ואחד ישראל מותרין בו,\u0004 שאין בו משום איסור אבר מן החי.","ומעירים: דברי ברייתא זו \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לרב אידי בר אבין,\u0004 שכן \u0003אמר רב אידי בר אבין, אמר ר' יצחק בר אשיין: הרוצה שיבריא,\u0004 מה יעשה? הריהו \u0003חותך כזית בשר מבית שחיטה, ומולחו יפה יפה, ומדיחו יפה יפה, וממתין לה עד שתצא נפשה, אחד גוי ואחד ישראל מותרים בו.\u0004","למעלה למדנו כי ישראל השוחט בהמה טמאה לגוי (וכן גוי השוחט בהמה טהורה), אף שהיא עדיין מפרכסת נחשבת היא כאוכל לענין טומאת אוכלים, ובענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' אלעזר:\u0004 אם בתוך שחיטה זו, השוחט \u0003שהה בה\u0004 (באמצע השחיטה) או ש\u0003דרס בה\u0004 את הסכין, שאלה מן הדברים הפוסלים את השחיטה, \u0003מהו\u0004 דינה. האם רק השחיטה הראויה בכל דיניה היא העושה את הבהמה המפרכסת כאוכל, ובאופנים הללו שאין זו שחיטה ראויה לא תועיל השחיטה לכך. או שמא גם השחיטה שאינה מדוקדקת בכל הלכות שחיטה עושה את הבהמה לאוכל?","\u0003אמר ליה ההוא סבא\u0004 \u0005[אמר לו אותו זקן]\u0006 בפתרון בעייתו: \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יוחנן:\u0004 אין המדובר אלא בשחיטה הראויה בכל אופניה, ולכך היא \u0003צריכה הכשר שחיטה כבהמה טהורה.\u0004 ומבררים: \u0003\"הכשר\u0004 שחיטה\" \u0003למאי\u0004 \u0005[למה]\u0006 הכוונה? \u0003אמר רב שמואל בר יצחק:\u0004 הכוונה היא ל\u0003בדיקת סכין,\u0004 שיבדוק חכם את הסכין לפני השחיטה.","ומביאים עוד בעיה בענין זה, מה ש\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' זירא מרב ששת:\u0004 בהמה זו הטמאה שנשחטה בידי ישראל והריהי עתה מפרכסת, והריהי נמצאת עתה באוהל שבו יש טומאת מת, ובמעי ה של אותה בהמה ישנם דברים שבלעתם קודם שנשחטה, \u0003מהו\u0004 הדין לענין \u0003שתציל\u0004 הבהמה \u0003על\u0004 הדברים \u0003הבלועין שבתוכה\u0004 שלא ייחשבו אלה כנמצאים בתוך אוהל המת, ולא ייטמאו? האם היא נחשבת כחיה (ומצילה את הכלים שבתוכה) או שמא היא נחשבת כמתה (ואין היא מצילה אותם)?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת לר' זירא בתמיהה על שאלתו: והרי כיון שאמרנו שבהמה זו \u0003מטמאה טומאת אוכלין,\u0004 והרי שנחשבת היא כמתה, \u0003ו\u0004מעתה כיצד אפשר לומר שהיא \u0003מצלת\u0004 על הבלועים שבתוכה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא בתשובה: ואולם כמו כן אמרנו גם ש\u0003אינה מטמאה טומאת נבלות,\u0004 והרי שאין היא נחשבת כמתה אלא כחיה, \u0003ו\u0004מעתה כיצד אפשר לומר ש\u0003לא תציל\u0004 על הבלועים שבתוכה?","\u0003אמר אביי\u0004 בהכרעת הבעיה: יש לנהוג לחומרה ולכן בהמה זו \u0003אינה מצלת על הבלועים שבתוכה, דהא\u0004 \u0005[שהרי]\u0006 \u0003מטמאה טומאת אוכלין, ו\u0004מצד שני \u0003הרובעה חייב, דהא\u0004 \u0005[שהרי]\u0006 היא \u0003אינה מטמאה טומאת נבלה,\u0004 ונחשבת כחיה.","עוד שנינו במשנתנו כי \u0003ר' יהודה אומר\u0004 בדינו של \u0003האלל\u0004 המכונס במקום אחד, שאם יש בו שיעור כזית במקום אחד, \u0003הריהו חייב עליו.\u0004 ובהסבר שיטתו של ר' יהודה \u0003אמר רב הונא: והוא\u0004 (ובלבד, כלומר, דין זה נאמר רק בזמן \u0003שכנסו\u0004 אדם בר דעת, שגילה בכך דעתו שמחשיב הוא את האלל כראוי לאכילה.","\u0003ו\u0004עוד \u0003אמר רב הונא:\u0004 \u0003שני חצאי זיתים\u0004 של בשר נבילה \u0003שישנן על גבי העור\u0004 — \u0003העור מבטלן\u0004 לכל אחת מחתיכות הבשר הללו, שאין העור מטמא בטומאת הנבילה והחתיכות הללו מתבטלות אצלו. ולכך אין כאן מקום לטומאת נבילה."]]};
